-- 성경통독도우미 — 단답형을 본문 사실 확인 객관식으로 바꾼다.
--
-- 단답형 169개는 손으로 적어야 해서 맞춤법 하나에 오답 처리가 됐고, 무엇보다
-- 통독한 내용을 확인하는 데는 보기에서 고르는 편이 낫다. 문제와 해설은 그대로
-- 두고 보기 넷을 붙였다 — 오답은 같은 갈래(사람은 사람, 땅은 땅, 숫자는 숫자)에서
-- 골랐다. 엉뚱한 것을 섞으면 본문을 안 읽어도 답이 보인다.
--
-- correctIndex는 전부 0이지만 뜻이 없다. 앱이 보여 줄 때 문제마다 고정된 순서로
-- 섞기 때문이다(shuffleChoices.ts). 저장된 자리에 기대지 않는다.

update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["빛", "해와 달", "물고기와 새", "사람"], "question": "하나님이 첫째 날에 만드신 것은 무엇입니까?", "explanation": "첫째 날에 하나님이 \"빛이 있으라\" 하시니 빛이 생겼습니다. 해와 달과 별은 넷째 날에 만드셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["땅의 흙대로", "하나님의 형상대로", "천사의 모양대로", "짐승의 모양대로"], "question": "하나님은 사람을 무엇대로 만드셨다고 했습니까?", "explanation": "\"하나님이 자기 형상 곧 하나님의 형상대로 사람을 창조하시되\"라고 했습니다. 사람이 하나님을 닮은 특별한 존재라는 뜻입니다.", "correctIndex": 1}, {"id": 3, "type": "choice", "choices": ["아쉽다", "좋다", "부족하다", "무섭다"], "question": "하나님이 만드신 것을 보시고 하신 말씀은 무엇입니까?", "explanation": "하나님은 만드실 때마다 \"좋았더라\"고 하셨고, 다 만드신 뒤에는 \"심히 좋았더라\"고 하셨습니다.", "correctIndex": 1}, {"id": 4, "type": "choice", "question": "하나님이 세상을 만드시는 데 걸린 날은 며칠입니까?", "choices": ["엿새", "사흘", "이레", "열흘"], "correctIndex": 0, "explanation": "하나님은 엿새 동안 세상을 만드시고 일곱째 날에 쉬셨습니다."}, {"id": 5, "type": "choice", "choices": ["첫째 날", "둘째 날", "넷째 날", "여섯째 날"], "question": "해와 달과 별은 몇째 날에 만들어졌습니까?", "explanation": "넷째 날에 하늘의 빛들을 만드셔서 낮과 밤을 나누고 계절과 날과 해를 이루게 하셨습니다.", "correctIndex": 2}, {"id": 6, "type": "choice", "choices": ["땅의 모든 생물을 다스리는 일", "하늘을 나는 일", "별을 세는 일", "바다를 가르는 일"], "question": "하나님이 사람에게 맡기신 일은 무엇입니까?", "explanation": "하나님은 사람에게 땅을 채우고 다스리며 물고기와 새와 짐승을 돌보게 하셨습니다. 마음대로 해치라는 뜻이 아니라 맡아서 잘 관리하라는 뜻입니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "\"태초에 하나님이 ○○를 창조하시니라\" — ○○에 들어갈 말은?", "choices": ["천지", "해와 달", "빛과 어둠", "사람과 짐승"], "correctIndex": 0, "explanation": "창세기의 첫 문장입니다. 하늘과 땅, 즉 온 세상이 하나님에게서 시작되었다는 선언입니다."}]'::jsonb where book_id = 1 and chapter = 1;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["땅의 흙", "물", "나무", "돌"], "question": "하나님이 사람을 만드실 때 쓰신 재료는 무엇입니까?", "explanation": "하나님이 땅의 흙으로 사람을 지으시고 코에 생명의 숨을 불어넣으시니 사람이 살아 있는 존재가 되었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["생명나무 열매", "선악을 알게 하는 나무의 열매", "동산 가운데 모든 열매", "무화과나무 열매"], "question": "하나님이 사람에게 먹지 말라고 하신 것은 무엇입니까?", "explanation": "동산의 모든 나무 열매는 먹어도 되지만 선악을 알게 하는 나무의 열매만은 먹지 말라고 하셨습니다.", "correctIndex": 1}, {"id": 3, "type": "choice", "choices": ["빛을 만드심", "쉬시고 그날을 복되게 하심", "사람을 만드심", "비를 내리심"], "question": "하나님이 일곱째 날에 하신 일은 무엇입니까?", "explanation": "하나님은 하시던 일을 마치고 일곱째 날에 쉬셨습니다. 그리고 그날을 복되게 하시고 거룩하게 하셨습니다.", "correctIndex": 1}, {"id": 4, "type": "choice", "question": "하나님이 사람을 두신 동산의 이름은 무엇입니까?", "choices": ["에덴", "가나안", "고센", "모리아"], "correctIndex": 0, "explanation": "하나님은 동쪽 에덴에 동산을 만드시고 지으신 사람을 거기 두셨습니다."}, {"id": 5, "type": "choice", "choices": ["사람이 혼자 있는 것", "사람이 일하는 것", "동산에 나무가 많은 것", "강이 흐르는 것"], "question": "하나님이 \"좋지 않다\"고 하신 것은 무엇입니까?", "explanation": "1장에서 계속 \"좋다\"고 하시던 하나님이 여기서 처음으로 \"좋지 않다\"고 하십니다. 사람이 혼자 있는 것이었고, 그래서 돕는 짝을 만들어 주셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["동산을 가꾸고 지키는 일", "아무 일도 안 하는 것", "사냥", "집을 짓는 일"], "question": "하나님이 사람에게 에덴동산에서 하게 하신 일은 무엇입니까?", "explanation": "일은 벌이 아니라 처음부터 사람에게 주어진 몫이었습니다. 하나님은 사람을 동산에 두어 그곳을 가꾸고 지키게 하셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "아담이 자기 곁에 온 사람을 보고 부른 이름은 무엇입니까?", "choices": ["여자", "하와", "돕는 배필", "산 자의 어머니"], "correctIndex": 0, "explanation": "아담은 \"이는 내 뼈 중의 뼈요 살 중의 살이라\" 하며 여자라고 불렀습니다. 남자에게서 취했기 때문이라고 설명합니다."}]'::jsonb where book_id = 1 and chapter = 2;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["너희가 결코 죽지 아니하리라", "열매가 맛이 없다", "동산을 떠나라", "하나님이 오신다"], "question": "뱀이 여자에게 한 말은 무엇입니까?", "explanation": "뱀은 하나님이 하신 말씀을 정면으로 뒤집었습니다. \"죽으리라\"고 하신 말씀에 대해 \"결코 죽지 아니하리라\"고 한 것입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["하나님께 감사함", "자기들이 벗은 줄 알고 몸을 가림", "동산 밖으로 나감", "뱀을 잡음"], "question": "열매를 먹은 뒤 두 사람이 처음 한 일은 무엇입니까?", "explanation": "눈이 밝아져 자기들이 벗은 줄 알고 무화과나무 잎을 엮어 몸을 가렸습니다. 그리고 하나님을 피해 숨었습니다.", "correctIndex": 1}, {"id": 3, "type": "choice", "choices": ["두려워서 숨었습니다", "잘못했습니다", "여기 있습니다", "아무 말도 하지 않음"], "question": "하나님이 \"네가 어디 있느냐\"고 물으셨을 때 아담의 대답은?", "explanation": "아담은 벗었으므로 두려워 숨었다고 답했습니다. 그리고 곧바로 \"하나님이 주신 여자가 주기에 먹었다\"며 책임을 미룹니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "아담은 열매를 먹은 책임을 누구에게 미뤘습니까?", "choices": ["여자", "뱀", "하나님", "땅"], "correctIndex": 0, "explanation": "아담은 여자 탓을, 여자는 뱀 탓을 했습니다. 잘못을 인정하지 않고 서로에게 미루는 모습이 그대로 드러납니다."}, {"id": 5, "type": "choice", "choices": ["가죽옷을 지어 입히심", "동산을 없애심", "뱀을 죽이심", "비를 내리심"], "question": "하나님이 두 사람을 동산에서 내보내신 뒤 하신 일은 무엇입니까?", "explanation": "하나님은 사람에게 가죽옷을 지어 입히셨습니다. 벌을 주시면서도 돌보시는 마음이 함께 나타납니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["여자의 후손이 네 머리를 상하게 할 것이다", "여자의 후손이 너를 섬길 것이다", "여자의 후손이 사라질 것이다", "여자의 후손이 뱀이 될 것이다"], "question": "하나님이 뱀에게 하신 말씀 중 여자의 후손에 대한 내용은?", "explanation": "\"여자의 후손은 네 머리를 상하게 할 것이요 너는 그의 발꿈치를 상하게 할 것이니라.\" 성경 전체에서 처음 나오는 구원의 약속으로 읽는 구절입니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "아담이 아내에게 지어 준 이름은 무엇입니까?", "choices": ["하와", "사라", "리브가", "미리암"], "correctIndex": 0, "explanation": "모든 산 자의 어머니가 되기 때문에 하와라고 불렀습니다."}]'::jsonb where book_id = 1 and chapter = 3;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["가인은 농사, 아벨은 양치기", "가인은 양치기, 아벨은 농사", "둘 다 농사", "둘 다 어부"], "question": "가인과 아벨은 각각 무슨 일을 했습니까?", "explanation": "가인은 땅을 가는 농부였고 아벨은 양 치는 목자였습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["죄가 문 앞에 엎드려 있으니 죄를 다스리라", "동생을 떠나라", "제물을 더 가져오라", "땅을 떠나라"], "question": "하나님이 가인에게 하신 경고는 무엇입니까?", "explanation": "하나님은 가인이 화를 내며 얼굴이 굳어졌을 때 미리 경고하셨습니다. 죄가 문 앞에 웅크리고 있으니 다스리라는 것이었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["내가 알지 못하나이다, 내가 내 아우를 지키는 자니이까", "들에 있습니다", "죄송합니다", "아무 말도 하지 않음"], "question": "하나님이 \"네 아우 아벨이 어디 있느냐\"고 물으셨을 때 가인의 대답은?", "explanation": "가인은 모른다고 잡아뗐을 뿐 아니라 되레 따져 물었습니다. 3장의 아담처럼 잘못을 인정하지 않는 모습입니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "가인이 죽인 동생의 이름은 무엇입니까?", "choices": ["아벨", "셋", "가인", "에녹"], "correctIndex": 0, "explanation": "가인은 들에서 동생 아벨을 쳐죽였습니다. 성경에 나오는 첫 살인입니다."}, {"id": 5, "type": "choice", "choices": ["만나는 사람이 그를 죽이지 못하게 하려고", "가인을 높이려고", "농사를 잘 짓게 하려고", "길을 잃지 않게 하려고"], "question": "하나님이 가인에게 표를 주신 이유는 무엇입니까?", "explanation": "가인은 자기를 만나는 자가 죽일까 두렵다고 했고, 하나님은 그를 죽이지 못하도록 표를 주셨습니다. 벌을 주시면서도 생명을 지키신 것입니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["셋", "에녹", "라멕", "노아"], "question": "아담과 하와가 아벨 대신 얻은 아들의 이름은?", "explanation": "하와는 \"하나님이 아벨 대신에 다른 씨를 주셨다\"며 아들의 이름을 셋이라 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "가인이 하나님을 떠나 살게 된 땅의 이름은 무엇입니까?", "choices": ["놋", "하란", "고센", "우스"], "correctIndex": 0, "explanation": "가인은 하나님 앞을 떠나 에덴 동쪽 놋 땅에 살았습니다."}]'::jsonb where book_id = 1 and chapter = 4;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["에녹", "므두셀라", "라멕", "셋"], "question": "이 족보에서 죽지 않고 하나님이 데려가신 사람은 누구입니까?", "explanation": "\"에녹이 하나님과 동행하더니 하나님이 그를 데려가시므로 세상에 있지 아니하였더라.\" 족보에서 유일하게 \"죽었더라\"가 없는 사람입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "성경에서 가장 오래 산 사람의 이름은 무엇입니까?", "choices": ["므두셀라", "아담", "노아", "에녹"], "correctIndex": 0, "explanation": "므두셀라는 969세를 살고 죽었습니다."}, {"id": 3, "type": "choice", "choices": ["죽었더라", "기뻐하였더라", "싸웠더라", "떠났더라"], "question": "이 족보에서 계속 반복되는 말은 무엇입니까?", "explanation": "이름마다 \"몇 년을 살고 죽었더라\"가 반복됩니다. 죄가 들어온 뒤 죽음이 모든 사람에게 이어졌다는 것을 담담하게 보여 줍니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["하나님과 동행하였다", "가장 부자였다", "가장 힘이 셌다", "가장 오래 살았다"], "question": "에녹에 대해 성경이 반복해서 말하는 것은 무엇입니까?", "explanation": "에녹은 300년 동안 하나님과 동행했다고 두 번이나 강조됩니다. 오래 산 것보다 어떻게 살았는지가 중요하게 다뤄집니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "이 족보의 마지막에 나오는 사람은 누구입니까?", "choices": ["노아", "에녹", "라멕", "셋"], "correctIndex": 0, "explanation": "족보는 노아와 그의 세 아들 셈, 함, 야벳에서 마칩니다."}, {"id": 6, "type": "choice", "choices": ["셈, 함, 야벳", "가인, 아벨, 셋", "에녹, 라멕, 므두셀라", "아브람, 나홀, 하란"], "question": "노아의 세 아들은 누구입니까?", "explanation": "노아는 오백 세 된 후에 셈과 함과 야벳을 낳았습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["아담", "노아", "가인", "에녹"], "question": "이 족보는 누구에서 시작합니까?", "explanation": "\"이것은 아담의 계보를 적은 책이니라\"로 시작합니다. 하나님이 사람을 지으실 때 하나님의 모양대로 지으셨다는 말을 다시 한번 짚고 넘어갑니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 5;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["마음으로 생각하는 모든 계획이 항상 악했다", "서로 도우며 살았다", "하나님을 잘 섬겼다", "아무 잘못이 없었다"], "question": "하나님이 보시기에 그 시대 사람들은 어떠했습니까?", "explanation": "사람의 죄악이 세상에 가득하고 마음으로 생각하는 모든 계획이 항상 악할 뿐이었다고 합니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["하나님께 은혜를 입고 하나님과 동행했다", "가장 부자였다", "왕이었다", "배를 만드는 기술자였다"], "question": "노아에 대해 성경이 말하는 것은 무엇입니까?", "explanation": "노아는 그 시대에 의롭고 흠 없는 사람이었으며 하나님과 동행했습니다. 5장의 에녹과 같은 표현입니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "하나님이 노아에게 만들라고 하신 것은 무엇입니까?", "choices": ["방주", "제단", "성읍", "탑"], "correctIndex": 0, "explanation": "하나님은 잣나무로 방주를 만들되 안팎에 역청을 칠하라고 하셨습니다."}, {"id": 4, "type": "choice", "choices": ["모든 생물을 암수 한 쌍씩 데려오라", "큰 짐승만 데려오라", "아무것도 데려오지 말라", "새만 데려오라"], "question": "방주에 태울 짐승에 대한 하나님의 명령은 무엇입니까?", "explanation": "살아 있는 모든 생물을 암수 한 쌍씩 방주로 데려와 살아남게 하라고 하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["노아와 아내, 세 아들과 며느리들", "노아 혼자", "온 마을 사람들", "노아와 아내 둘만"], "question": "방주에 함께 들어갈 사람은 누구였습니까?", "explanation": "노아와 그의 아내, 세 아들과 세 며느리, 모두 여덟 사람입니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "이 장의 마지막 문장은 노아가 어떻게 했다고 말합니까?", "choices": ["하나님이 명하신 대로 다 했다", "까닭을 물은 뒤에 했다", "가족과 의논한 뒤에 했다", "며칠 미루다가 했다"], "correctIndex": 0, "explanation": "\"노아가 그와 같이 하되 하나님이 자기에게 명하신 대로 다 준행하였더라.\" 설명도 반문도 없이 그대로 했다는 것이 노아를 보여 줍니다."}, {"id": 7, "type": "choice", "choices": ["한탄하시고 마음 아파하셨다", "기뻐하셨다", "아무 말씀도 없으셨다", "자랑하셨다"], "question": "하나님이 사람을 지으신 것을 두고 하신 말씀은?", "explanation": "하나님은 땅 위에 사람 지으셨음을 한탄하시고 마음에 근심하셨다고 합니다. 심판이 분노가 아니라 아픔에서 나온 것임을 보여 줍니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 6;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "비가 며칠 동안 내렸습니까?", "choices": ["사십 일", "이레", "백오십 일", "일 년"], "correctIndex": 0, "explanation": "사십 주야를 비가 땅에 쏟아졌습니다."}, {"id": 2, "type": "choice", "choices": ["하나님", "노아", "노아의 아들들", "아무도 닫지 않음"], "question": "방주의 문을 닫으신 분은 누구입니까?", "explanation": "\"여호와께서 그를 들여보내고 문을 닫으시니라.\" 사람이 아니라 하나님이 닫으셨다는 것이 이 장면의 핵심입니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["육백 세", "오백 세", "칠백 세", "구백 세"], "question": "노아가 방주에 들어간 것은 몇 살 때입니까?", "explanation": "노아가 육백 세 되던 해 둘째 달 열이렛날에 홍수가 시작되었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["큰 깊음의 샘이 터지고 하늘의 창이 열림", "바다에서만", "강이 넘쳐서", "눈이 녹아서"], "question": "홍수의 물은 어디에서 왔습니까?", "explanation": "땅 아래에서도 물이 솟고 하늘에서도 쏟아졌습니다. 위아래에서 한꺼번에 물이 몰려온 것입니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["일곱 쌍", "한 쌍", "두 쌍", "열 쌍"], "question": "정결한 짐승은 몇 쌍씩 데려가라고 하셨습니까?", "explanation": "정결한 짐승은 일곱 쌍씩, 정결하지 않은 짐승은 한 쌍씩 데려가라고 하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "방주에 들어간 사람은 모두 몇 명입니까?", "choices": ["여덟 명", "네 명", "여섯 명", "열두 명"], "correctIndex": 0, "explanation": "노아와 아내, 세 아들과 세 며느리 — 모두 여덟 사람입니다."}, {"id": 7, "type": "choice", "choices": ["백오십 일", "사십 일", "일 년", "열흘"], "question": "물이 땅에 넘친 기간은 얼마입니까?", "explanation": "비는 사십 일 동안 내렸고, 물이 땅에 넘친 것은 백오십 일이었습니다. 비가 그쳤다고 곧바로 물이 빠진 것이 아닙니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 7;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["하나님이 노아를 기억하셨다", "비가 그쳤다", "노아가 배에서 나왔다", "땅이 말랐다"], "question": "이 장은 어떤 말로 시작합니까?", "explanation": "\"하나님이 노아와 그와 함께 방주에 있는 모든 들짐승과 가축을 기억하사.\" 물이 빠진 것보다 하나님이 기억하셨다는 것이 먼저 나옵니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "방주가 멈춰 선 산의 이름은 무엇입니까?", "choices": ["아라랏 산", "시내 산", "모리아 산", "호렙 산"], "correctIndex": 0, "explanation": "일곱째 달 열이렛날에 방주가 아라랏 산에 머물렀습니다."}, {"id": 3, "type": "choice", "choices": ["감람나무 새 잎사귀", "나뭇가지", "풀", "아무것도 없음"], "question": "두 번째로 보낸 비둘기가 물고 온 것은 무엇입니까?", "explanation": "비둘기가 감람나무 새 잎사귀를 물고 돌아왔습니다. 노아는 그것을 보고 물이 줄어든 것을 알았습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["까마귀", "비둘기", "독수리", "참새"], "question": "노아가 처음 내보낸 새는 무엇입니까?", "explanation": "노아는 먼저 까마귀를 내보냈고, 그 뒤에 비둘기를 내보냈습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["제단을 쌓고 제사를 드림", "집을 지음", "농사를 시작함", "마을을 세움"], "question": "땅에서 나온 노아가 가장 먼저 한 일은 무엇입니까?", "explanation": "노아는 여호와께 제단을 쌓고 정결한 짐승으로 번제를 드렸습니다. 살아남은 뒤 가장 먼저 한 일이 예배였습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["다시는 사람 때문에 땅을 저주하지 않겠다", "다시는 비를 내리지 않겠다", "사람을 더 만들지 않겠다", "방주를 다시 만들게 하겠다"], "question": "하나님이 마음속으로 하신 약속은 무엇입니까?", "explanation": "하나님은 다시는 사람으로 말미암아 땅을 저주하지 않고, 모든 생물을 다시 멸하지 않겠다고 하셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "하나님이 \"쉬지 아니하리라\"고 하신 것들 중는 무엇입니까?", "choices": ["심음과 거둠", "해와 달", "하늘과 땅", "빛과 어둠"], "correctIndex": 0, "explanation": "땅이 있을 동안에는 심음과 거둠, 추위와 더위, 여름과 겨울, 낮과 밤이 쉬지 않을 것이라고 하셨습니다."}]'::jsonb where book_id = 1 and chapter = 8;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "하나님이 다시는 물로 땅을 멸하지 않겠다는 약속의 표로 주신 것은?", "choices": ["무지개", "제단", "구름 기둥", "돌 기둥"], "correctIndex": 0, "explanation": "하나님은 구름 속에 무지개를 두어 언약의 증거로 삼으셨습니다. 무지개를 볼 때마다 그 약속을 기억하신다고 하셨습니다."}, {"id": 2, "type": "choice", "choices": ["하나님이 사람을 자기 형상대로 지으셨기 때문", "사람이 적기 때문", "피가 귀하기 때문", "싸움이 나기 때문"], "question": "하나님이 사람의 피를 흘리지 말라고 하신 이유는 무엇입니까?", "explanation": "사람의 목숨이 귀한 이유를 성경은 사람이 하나님의 형상대로 지어졌다는 데서 찾습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["포도주를 마시고 취함", "배를 다시 만듦", "아들을 내쫓음", "제사를 드리지 않음"], "question": "노아가 홍수 후에 한 일 중 문제가 된 것은 무엇입니까?", "explanation": "노아는 농사를 시작해 포도나무를 심었고, 포도주를 마시고 취해 장막 안에서 벌거벗었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["뒷걸음으로 들어가 옷으로 덮음", "밖에 알림", "아버지를 깨움", "장막을 떠남"], "question": "셈과 야벳이 아버지에게 한 행동은 무엇입니까?", "explanation": "두 사람은 옷을 어깨에 메고 뒷걸음쳐 들어가 아버지의 부끄러움을 덮었고 얼굴을 돌려 보지 않았습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["생육하고 번성하여 땅에 충만하라", "한곳에 모여 살아라", "배를 만들어라", "산으로 올라가라"], "question": "하나님이 노아와 아들들에게 다시 주신 복은 무엇입니까?", "explanation": "창세기 1장에서 사람에게 주셨던 말씀을 홍수 이후에 다시 주십니다. 새로 시작하게 하신 것입니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "아버지의 벌거벗은 것을 보고 밖에 알린 아들은 누구입니까?", "choices": ["함", "셈", "야벳", "가나안"], "correctIndex": 0, "explanation": "가나안의 아버지 함이 아버지의 하체를 보고 밖으로 나가 두 형제에게 알렸습니다."}, {"id": 7, "type": "choice", "choices": ["영원한 언약", "사람의 죄", "홍수", "방주"], "question": "하나님이 무지개를 보실 때 기억하시겠다고 한 것은 무엇입니까?", "explanation": "무지개를 보고 하나님과 모든 생물 사이의 영원한 언약을 기억하겠다고 하셨습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 9;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["노아의 세 아들 셈, 함, 야벳", "아담과 하와", "아브라함", "가인"], "question": "이 족보는 누구의 자손을 적은 것입니까?", "explanation": "노아의 아들 셈과 함과 야벳의 족보이며, 홍수 후에 그들에게서 아들들이 태어났습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "\"세상에 첫 용사\"라 불린 힘센 사냥꾼의 이름은 무엇입니까?", "choices": ["니므롯", "구스", "미스라임", "가나안"], "correctIndex": 0, "explanation": "함의 손자 니므롯은 세상에 첫 용사요 여호와 앞에서 용감한 사냥꾼이었다고 합니다."}, {"id": 3, "type": "choice", "choices": ["바벨", "예루살렘", "헤브론", "베들레헴"], "question": "니므롯의 나라가 시작된 도시 중 하나는 무엇입니까?", "explanation": "그의 나라는 시날 땅의 바벨과 에렉과 악갓에서 시작되었습니다. 다음 장 바벨탑 이야기와 이어집니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["여러 민족이 모두 한 가족에서 나왔다는 것", "누가 가장 힘이 셌는지", "누가 가장 오래 살았는지", "누가 가장 부자였는지"], "question": "이 족보가 보여 주려는 것은 무엇입니까?", "explanation": "이들에게서 백성들이 나뉘어 땅에 퍼졌다고 마무리합니다. 세상 민족들의 뿌리가 하나라는 것입니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["함", "셈", "야벳", "노아"], "question": "가나안은 누구의 아들입니까?", "explanation": "가나안은 함의 아들이며, 뒤에 이스라엘이 들어가 살게 되는 땅의 이름이 됩니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "노아의 세 아들의 이름을 모두 쓰세요.", "choices": ["셈, 함, 야벳", "가인, 아벨, 셋", "셈, 함, 데라", "야벳, 에녹, 라멕"], "correctIndex": 0, "explanation": "셈과 함과 야벳입니다. 이 세 사람에게서 온 땅의 민족이 퍼졌습니다."}, {"id": 7, "type": "choice", "choices": ["언어와 종족과 나라", "키와 몸무게", "재산", "나이"], "question": "족보에 나오는 사람들이 나뉜 기준으로 언급된 것은 무엇입니까?", "explanation": "각기 언어와 종족과 나라대로 나뉘었다고 반복해서 적습니다. 11장에서 언어가 나뉜 이유가 밝혀집니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 10;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["이름을 내고 흩어짐을 면하려고", "하나님께 예배하려고", "홍수를 피하려고", "적을 막으려고"], "question": "사람들이 탑을 쌓은 이유는 무엇입니까?", "explanation": "\"우리 이름을 내고 온 지면에 흩어짐을 면하자\"고 했습니다. 하나님이 퍼져 살라 하신 것과 정반대였습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["말을 뒤섞으심", "탑을 무너뜨리심", "비를 내리심", "땅을 가르심"], "question": "하나님은 그들을 어떻게 흩으셨습니까?", "explanation": "하나님은 그들의 언어를 혼잡하게 하여 서로 알아듣지 못하게 하셨습니다. 그러자 일을 멈추고 흩어졌습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "사람들이 쌓던 도시의 이름은 무엇입니까?", "choices": ["바벨", "니느웨", "소돔", "하란"], "correctIndex": 0, "explanation": "여호와께서 온 땅의 언어를 혼잡하게 하셨기 때문에 그 이름을 바벨이라 했습니다."}, {"id": 4, "type": "choice", "choices": ["벽돌과 역청", "돌과 나무", "흙과 풀", "쇠와 구리"], "question": "탑을 쌓을 때 사용한 재료는 무엇입니까?", "explanation": "돌 대신 벽돌을, 진흙 대신 역청을 썼다고 자세히 적습니다. 사람의 기술이 발전했다는 표시이기도 합니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["아브람", "이삭", "야곱", "요셉"], "question": "이 장 마지막에 등장하는, 데라의 아들은 누구입니까?", "explanation": "데라는 아브람과 나홀과 하란을 낳았습니다. 아브람은 다음 장에서 하나님의 부르심을 받습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "아브람의 아내 이름은 무엇입니까?", "choices": ["사래", "밀가", "하갈", "리브가"], "correctIndex": 0, "explanation": "아브람의 아내 이름은 사래였습니다. 사래는 아이를 낳지 못했다고 이 장에 미리 적혀 있습니다."}, {"id": 7, "type": "choice", "choices": ["하나였다", "여럿이었다", "없었다", "글자만 있었다"], "question": "탑을 쌓기 전 온 땅의 언어는 어떠했습니까?", "explanation": "\"온 땅의 언어가 하나요 말이 하나였더라\"로 시작합니다. 그래서 무슨 일이든 함께 할 수 있었습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 11;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["고향과 친척과 아버지의 집을 떠나라", "제단을 쌓아라", "아들을 낳아라", "이집트로 가라"], "question": "하나님이 아브람에게 하신 첫 명령은 무엇입니까?", "explanation": "하나님은 아브람에게 익숙한 모든 것을 떠나 하나님이 보여 주실 땅으로 가라고 하셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "아브람이 하란을 떠날 때 나이는 몇 살입니까?", "choices": ["일흔다섯 살", "예순 살", "여든 살", "아흔아홉 살"], "correctIndex": 0, "explanation": "아브람이 하란을 떠날 때 칠십오 세였습니다."}, {"id": 3, "type": "choice", "choices": ["땅의 모든 족속이 너로 말미암아 복을 받을 것이다", "큰 민족을 이루게 하겠다", "네 이름을 창대하게 하겠다", "네가 왕이 되게 하겠다"], "question": "하나님이 아브람에게 주신 약속에 포함되지 않는 것은?", "explanation": "하나님은 큰 민족, 복, 창대한 이름, 그리고 아브람을 통해 모든 족속이 복을 받는다고 하셨습니다. 왕이 되게 하시겠다는 말씀은 여기 없습니다.", "correctIndex": 3}, {"id": 4, "type": "choice", "choices": ["그 땅에 기근이 들어서", "전쟁이 나서", "하나님이 명하셔서", "장사를 하려고"], "question": "아브람이 이집트로 내려간 이유는 무엇입니까?", "explanation": "가나안 땅에 기근이 심했기 때문에 아브람은 이집트에 잠시 머물려고 내려갔습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["내 누이라고 하라", "내 아내라고 하라", "아무 말도 하지 말라", "떠나라"], "question": "아브람이 이집트에서 아내 사래에 대해 한 말은 무엇입니까?", "explanation": "아브람은 자기가 죽임당할까 두려워 사래를 누이라고 말하게 했습니다. 하나님의 약속을 받은 사람도 두려움 앞에서는 흔들렸습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "아브람이 가나안에 들어와 하나님께 한 일은 무엇입니까?", "choices": ["제단을 쌓았다", "성을 쌓았다", "우물을 팠다", "밭을 샀다"], "correctIndex": 0, "explanation": "아브람은 세겜과 벧엘 근처에서 여호와께 제단을 쌓고 여호와의 이름을 불렀습니다."}, {"id": 7, "type": "choice", "choices": ["롯", "나홀", "하란", "이삭"], "question": "아브람과 함께 떠난 조카의 이름은 무엇입니까?", "explanation": "아브람은 아내 사래와 조카 롯을 데리고 하란을 떠났습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 12;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["소유가 많아 함께 살 수 없고 목자들이 다투어서", "사이가 나빠져서", "전쟁이 나서", "하나님이 명하셔서"], "question": "아브람과 롯이 갈라선 이유는 무엇입니까?", "explanation": "두 사람의 가축과 재산이 너무 많아 한 땅이 감당하지 못했고, 목자들 사이에 다툼이 생겼습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["네가 먼저 고르라, 나는 반대쪽으로 가겠다", "내가 먼저 고르겠다", "함께 살자", "떠나라"], "question": "아브람이 롯에게 한 제안은 무엇입니까?", "explanation": "어른이자 부름받은 당사자인 아브람이 선택권을 양보했습니다. 다투지 않으려는 마음이 먼저였습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["요단 온 들판(소돔 쪽)", "산지", "광야", "바닷가"], "question": "롯이 고른 땅은 어디입니까?", "explanation": "롯은 물이 넉넉해 여호와의 동산 같아 보이는 요단 들판을 골라 소돔까지 옮겨 갔습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "성경이 소돔 사람들에 대해 미리 적어 둔 말은 무엇입니까?", "choices": ["악하여 여호와 앞에 큰 죄인이었다", "물이 넉넉한 땅이었다", "아브람의 친척이 살았다", "기근이 심했다"], "correctIndex": 0, "explanation": "\"소돔 사람은 악하여 여호와 앞에 큰 죄인이었더라\"고 미리 밝힙니다. 눈에 좋아 보이는 선택의 뒷면입니다."}, {"id": 5, "type": "choice", "choices": ["눈을 들어 사방을 보라, 이 땅을 네게 주겠다", "롯을 따라가라", "이집트로 가라", "기다려라"], "question": "롯이 떠난 뒤 하나님이 아브람에게 하신 말씀은?", "explanation": "보이는 땅을 다 주시겠다고 하시고, 자손을 땅의 티끌같이 많게 하시겠다고 약속하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["헤브론 마므레 상수리 수풀", "소돔", "벧엘", "애굽"], "question": "아브람이 옮겨 가서 제단을 쌓은 곳은 어디입니까?", "explanation": "아브람은 헤브론에 있는 마므레 상수리 수풀로 옮겨 거기서 여호와께 제단을 쌓았습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "아브람은 이집트에서 나온 뒤 어디로 돌아갔습니까?", "choices": ["벧엘", "세겜", "헤브론", "브엘세바"], "correctIndex": 0, "explanation": "아브람은 처음 제단을 쌓았던 벧엘과 아이 사이로 돌아가 거기서 여호와의 이름을 불렀습니다."}]'::jsonb where book_id = 1 and chapter = 13;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["조카 롯이 잡혀갔기 때문", "재물을 얻으려고", "왕이 되려고", "땅을 넓히려고"], "question": "아브람이 군사를 이끌고 나선 이유는 무엇입니까?", "explanation": "아브람은 조카가 사로잡혔다는 말을 듣고 집에서 기르고 훈련한 사람들을 데리고 쫓아갔습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "아브람이 데려간 사람은 몇 명입니까?", "choices": ["삼백십팔 명", "백 명", "육백 명", "천 명"], "correctIndex": 0, "explanation": "집에서 길리고 훈련된 자 삼백십팔 명을 거느리고 갔습니다."}, {"id": 3, "type": "choice", "question": "떡과 포도주를 가지고 나와 아브람을 축복한 살렘 왕은 누구입니까?", "choices": ["멜기세덱", "아비멜렉", "그돌라오멜", "베라"], "correctIndex": 0, "explanation": "살렘 왕 멜기세덱은 지극히 높으신 하나님의 제사장이었고, 뒤에 히브리서에서 예수님을 설명할 때 다시 등장합니다."}, {"id": 4, "type": "choice", "choices": ["얻은 것의 십분의 일", "땅", "가축 전부", "아무것도 안 줌"], "question": "아브람이 멜기세덱에게 준 것은 무엇입니까?", "explanation": "아브람은 그 얻은 것에서 십분의 일을 멜기세덱에게 주었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["실 한 오라기도 받지 않겠다", "절반만 받겠다", "고맙게 받겠다", "나중에 받겠다"], "question": "소돔 왕이 재물을 가지라고 했을 때 아브람의 대답은?", "explanation": "\"네가 아브람으로 치부하게 하였다 할까 하여\"라며 거절했습니다. 하나님이 주신 복이라는 것을 흐리고 싶지 않았습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["살렘 왕이며 지극히 높으신 하나님의 제사장", "군대 대장", "상인", "농부"], "question": "멜기세덱은 어떤 사람으로 소개됩니까?", "explanation": "왕이면서 동시에 제사장이라는 점이 특별합니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["밤에 나누어 습격해 쫓아감", "돈을 주고 사 옴", "왕에게 부탁함", "기다림"], "question": "아브람이 롯을 되찾은 방법은 무엇입니까?", "explanation": "아브람은 사람들을 나누어 밤에 습격했고 다메섹 왼편 호바까지 쫓아가 모두 되찾아 왔습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 14;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["네 자손이 이와 같으리라", "이 땅을 떠나라", "별을 세지 말라", "기다리지 말라"], "question": "하나님이 아브람에게 별을 보여 주시며 하신 말씀은?", "explanation": "하늘의 별을 셀 수 있나 보라 하시고, 네 자손이 그와 같으리라고 하셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "\"아브람이 여호와를 믿으니 여호와께서 이를 그의 ○로 여기시고\" — ○은?", "choices": ["의", "복", "상", "언약"], "correctIndex": 0, "explanation": "성경 전체에서 믿음과 의를 잇는 가장 중요한 구절 중 하나입니다. 로마서와 갈라디아서가 이 구절을 인용합니다."}, {"id": 3, "type": "choice", "choices": ["연기 나는 화로와 타는 횃불", "아브람", "천사", "바람"], "question": "언약을 맺을 때 쪼갠 고기 사이로 지나간 것은 무엇입니까?", "explanation": "아브람은 깊이 잠들어 있었고 하나님을 나타내는 화로와 횃불만 지나갔습니다. 지키는 책임을 하나님이 홀로 지셨다는 뜻으로 읽습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["남의 땅에서 사백 년 동안 종이 되었다가 나올 것", "곧 왕이 될 것", "평안히 살 것", "흩어질 것"], "question": "하나님이 아브람에게 미리 알려 주신 자손의 앞일은?", "explanation": "이방 땅에서 객이 되어 괴롭힘을 받다가 큰 재물을 가지고 나오리라고 하셨습니다. 출애굽의 예고입니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["다메섹 사람 엘리에셀", "롯", "이스마엘", "이삭"], "question": "아브람이 처음에 자기 상속자로 여긴 사람은 누구입니까?", "explanation": "자식이 없던 아브람은 집에서 길린 종 엘리에셀이 상속자가 될 것이라 말했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["두려워하지 말라 나는 네 방패요 큰 상급이니라", "떠나라", "기다려라", "제단을 쌓아라"], "question": "하나님이 아브람에게 하신 첫 말씀은 무엇입니까?", "explanation": "환상 중에 임한 말씀입니다. 아브람이 품고 있던 두려움을 먼저 다루셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "아브람이 하나님께 솔직히 물은 것은 무엇에 대한 것입니까?", "choices": ["자식이 없는 것", "먹을 것이 없는 것", "땅이 없는 것", "형제와 다툰 것"], "correctIndex": 0, "explanation": "\"내게 씨를 주지 아니하셨으니\"라며 자식이 없는 현실을 그대로 아뢰었습니다."}]'::jsonb where book_id = 1 and chapter = 15;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["몸종 하갈을 남편에게 주어 아이를 얻는 것", "다른 나라로 가는 것", "아이를 입양하는 것", "더 기다리는 것"], "question": "사래가 낸 방법은 무엇입니까?", "explanation": "기다리다 지친 사래가 사람의 방법을 냈고, 아브람도 그 말을 들었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "하갈이 하나님을 부른 이름은 무엇입니까?", "choices": ["감찰하시는 하나님", "전능하신 하나님", "여호와 이레", "여호와 닛시"], "correctIndex": 0, "explanation": "\"나를 살피시는 하나님\"이라는 뜻입니다. 아무도 없는 광야에서 자기를 보고 계셨다는 고백입니다."}, {"id": 3, "type": "choice", "choices": ["여주인에게 돌아가 복종하라", "더 멀리 가라", "여기 머물라", "애굽으로 가라"], "question": "여호와의 사자가 하갈에게 한 말은 무엇입니까?", "explanation": "돌아가라 하시면서도 \"네 씨를 크게 번성하게 하리라\"는 약속을 함께 주셨습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "하갈이 낳은 아들의 이름은 무엇입니까?", "choices": ["이스마엘", "이삭", "미디안", "그일라"], "correctIndex": 0, "explanation": "\"여호와께서 네 고통을 들으셨음이니라\" 하여 이스마엘이라 이름 지으라 하셨습니다."}, {"id": 5, "type": "choice", "choices": ["여주인을 업신여기고, 사래는 하갈을 학대함", "두 사람이 친해짐", "아브람이 하갈을 내보냄", "아무 일 없음"], "question": "하갈이 임신한 뒤 생긴 일은 무엇입니까?", "explanation": "사람의 방법으로 얻으려다 집안이 어그러졌습니다. 사래는 그 괴로움을 아브람 탓으로 돌렸습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["팔십육 세", "칠십오 세", "구십구 세", "백 세"], "question": "아브람이 이스마엘을 낳았을 때 나이는?", "explanation": "하갈이 이스마엘을 낳을 때 아브람은 팔십육 세였습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["광야의 샘 곁", "소돔", "헤브론", "애굽"], "question": "하갈이 여호와의 사자를 만난 곳은 어디입니까?", "explanation": "술 길 광야의 샘 곁에서 만났고, 그 우물을 브엘라해로이라 불렀습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 16;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "아브람이 받은 새 이름은 무엇입니까?", "choices": ["아브라함", "이스라엘", "아비멜렉", "아브넬"], "correctIndex": 0, "explanation": "\"많은 민족의 아버지\"라는 뜻으로 아브라함이 되었습니다."}, {"id": 2, "type": "choice", "choices": ["사라", "리브가", "하갈", "라헬"], "question": "사래가 받은 새 이름은 무엇입니까?", "explanation": "하나님은 사래를 사라라 부르라 하시고 그에게 복을 주어 여러 민족의 어머니가 되게 하겠다고 하셨습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["할례", "제사", "금식", "십일조"], "question": "하나님이 언약의 표로 명하신 것은 무엇입니까?", "explanation": "남자는 난 지 팔 일 만에 할례를 받아야 했고, 집에서 난 자와 돈으로 산 자도 모두 포함되었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["엎드려 웃었다", "울었다", "화를 냈다", "아무 말 없었다"], "question": "아들을 낳는다는 말에 아브라함은 어떻게 했습니까?", "explanation": "백 세 된 사람이 어찌 낳으며 사라가 어찌 낳으랴 하며 마음속으로 웃었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "태어날 아들의 이름으로 하나님이 정해 주신 것은?", "choices": ["이삭", "이스마엘", "야곱", "에서"], "correctIndex": 0, "explanation": "이삭은 \"웃음\"이라는 뜻입니다. 웃었던 그 자리에서 이름이 나왔습니다."}, {"id": 6, "type": "choice", "choices": ["전능한 하나님", "거룩한 하나님", "질투하는 하나님", "만군의 여호와"], "question": "하나님이 아브라함에게 자신을 뭐라고 소개하셨습니까?", "explanation": "\"나는 전능한 하나님이라\" 하시고 아브라함 앞에서 행하여 완전하라고 하셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["이스마엘에게도 복을 주어 큰 나라가 되게 하겠다", "이스마엘은 잊어라", "이스마엘을 내보내라", "아무 말씀도 없으셨다"], "question": "아브라함이 이스마엘에 대해 구한 것에 하나님은 어떻게 답하셨습니까?", "explanation": "언약은 이삭과 세우시겠다 하시면서도 이스마엘에게 복을 주어 열두 두령을 낳게 하겠다고 하셨습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 17;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "\"여호와께 ○○지 못한 일이 있겠느냐\" — ○○에 들어갈 말은?", "choices": ["능하지", "가지", "알지", "듣지"], "correctIndex": 0, "explanation": "사라가 웃은 것을 아시고 하신 말씀입니다. 나이도 몸도 안 되는 상황에 대한 답이었습니다."}, {"id": 2, "type": "choice", "choices": ["열 명", "오십 명", "스무 명", "다섯 명"], "question": "아브라함이 소돔을 위해 마지막으로 여쭌 숫자는?", "explanation": "오십에서 시작해 사십오, 사십, 삼십, 이십, 열까지 내려가며 여섯 번 간청했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["자기와 남편이 너무 늙었기 때문", "손님이 우스워서", "기뻐서", "믿기지 않아 기뻐서만"], "question": "사라가 웃은 이유는 무엇입니까?", "explanation": "\"내가 노쇠하였고 내 주인도 늙었으니 내게 무슨 즐거움이 있으리요\" 하며 속으로 웃었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["달려나가 몸을 굽히고 급히 음식을 준비함", "못 본 척함", "문 앞에서 돌려보냄", "천천히 맞이함"], "question": "아브라함이 손님들을 맞은 태도는 어떠했습니까?", "explanation": "아브라함은 달려나가 영접하고 사라에게 급히 떡을 만들게 하고 송아지를 잡아 대접했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["아브라함이 큰 나라가 되고 그 자손에게 여호와의 도를 지키게 할 것이기 때문", "아브라함이 물었기 때문", "롯이 거기 살기 때문만", "아무 이유도 없음"], "question": "하나님이 소돔의 일을 아브라함에게 알리신 까닭으로 말씀하신 것은?", "explanation": "\"내가 어찌 아브라함에게 숨기겠느냐\" 하시며 그가 자손에게 여호와의 도를 가르칠 것을 말씀하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "사라에게 아들이 있으리라고 하신 때는 언제라고 했습니까?", "choices": ["내년 이맘때", "이레 뒤", "삼 년 뒤", "십 년 뒤"], "correctIndex": 0, "explanation": "\"내년 이맘때 내가 반드시 네게로 돌아오리니\"라고 하셨습니다."}, {"id": 7, "type": "choice", "choices": ["주께서 의인을 악인과 함께 멸하려 하시나이까", "소돔은 죄가 없습니다", "롯만 살려 주소서", "제가 가겠습니다"], "question": "아브라함이 간청하며 한 말은 무엇입니까?", "explanation": "\"세상을 심판하시는 이가 정의를 행하실 것이 아니니이까\"라며 하나님의 공의에 근거해 간청했습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 18;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["손을 붙잡아 성 밖으로 끌어냄", "그냥 두고 떠남", "더 기다려 줌", "집을 불태움"], "question": "롯이 지체할 때 천사들이 한 일은 무엇입니까?", "explanation": "\"여호와께서 그에게 자비를 더하심이었더라.\" 롯이 스스로 나온 것이 아니라 끌려 나왔습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "뒤를 돌아본 롯의 아내는 어떻게 되었습니까?", "choices": ["소금 기둥", "돌이 되었다", "불에 탔다", "눈이 멀었다"], "correctIndex": 0, "explanation": "롯의 아내는 뒤를 돌아보았으므로 소금 기둥이 되었습니다."}, {"id": 3, "type": "choice", "choices": ["유황과 불", "큰 물", "지진", "어둠"], "question": "소돔과 고모라에 내린 것은 무엇입니까?", "explanation": "여호와께서 하늘로부터 유황과 불을 비같이 내리셔서 그 성들과 온 들과 주민을 멸하셨습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["도망하여 생명을 보존하라, 돌아보지 말라", "집에 머물라", "성 사람들을 설득하라", "재산을 챙기라"], "question": "천사들이 롯에게 준 명령은 무엇입니까?", "explanation": "뒤를 돌아보지도 말고 들에 머물지도 말고 산으로 도망하라고 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "롯이 도망친 작은 성의 이름은 무엇입니까?", "choices": ["소알", "소돔", "고모라", "세겜"], "correctIndex": 0, "explanation": "롯이 산까지는 못 가겠다며 작은 성으로 피하게 해 달라 청했고, 그 성 이름을 소알이라 했습니다."}, {"id": 6, "type": "choice", "choices": ["농담으로 여겼다", "함께 도망쳤다", "믿고 준비했다", "화를 냈다"], "question": "롯의 사위들은 롯의 말을 어떻게 받아들였습니까?", "explanation": "롯이 사위들에게 성을 떠나라고 했으나 그들은 농담으로 여겼습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["하나님이 아브라함을 생각하셔서 롯을 내보내셨다", "롯이 의로워서만", "천사들이 실수해서", "롯이 값을 치러서"], "question": "이 심판에서 롯이 구원받은 배경으로 성경이 적은 것은?", "explanation": "\"하나님이 아브라함을 생각하사 롯을 그 엎으시는 중에서 내보내셨더라\"고 적습니다. 18장의 간청과 이어집니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 19;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["내 누이라고 함", "내 아내라고 함", "아무 말 안 함", "떠나겠다고 함"], "question": "아브라함이 그랄에서 사라에 대해 한 말은 무엇입니까?", "explanation": "12장 이집트에서와 같은 일을 반복했습니다. 두려움 앞에서 같은 실수를 다시 한 것입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "사라를 데려간 그랄 왕의 이름은 무엇입니까?", "choices": ["아비멜렉", "바로", "멜기세덱", "하몰"], "correctIndex": 0, "explanation": "그랄 왕 아비멜렉이 사람을 보내 사라를 데려갔습니다."}, {"id": 3, "type": "choice", "choices": ["밤에 꿈으로", "천사를 보내서", "음성으로만", "선지자를 통해"], "question": "하나님이 아비멜렉에게 나타나신 방법은 무엇입니까?", "explanation": "하나님이 밤에 꿈에 아비멜렉에게 임하여 경고하셨습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["온전한 마음과 깨끗한 손으로 한 일이다", "몰랐으니 상관없다", "아브라함이 시켰다", "내 권리다"], "question": "아비멜렉이 항변한 내용은 무엇입니까?", "explanation": "하나님도 \"네가 온전한 마음으로 이렇게 한 줄을 내가 알았다\"고 인정하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["이곳에는 하나님을 두려워함이 없어 나를 죽일 것이라 생각해서", "사라가 원해서", "재물을 얻으려고", "왕이 무서워서만"], "question": "아브라함이 그렇게 말한 이유로 든 것은 무엇입니까?", "explanation": "아브라함은 자기 짐작으로 판단했고, 그 짐작이 틀렸다는 것이 이 장에서 드러납니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["양과 소와 종들, 그리고 은 천 개", "아무것도 주지 않음", "땅만 줌", "벌을 줌"], "question": "아비멜렉이 아브라함에게 준 것은 무엇입니까?", "explanation": "아비멜렉은 사라를 돌려보내며 가축과 종과 은 천 개를 주고 원하는 곳에 살라고 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "아브라함이 아비멜렉을 위해 한 일은 무엇입니까?", "choices": ["기도", "제사", "선물", "맹세"], "correctIndex": 0, "explanation": "아브라함이 기도하매 하나님이 아비멜렉과 그 아내와 여종들을 고치셔서 출산하게 하셨습니다."}]'::jsonb where book_id = 1 and chapter = 20;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["하나님이 나를 웃게 하시니", "이제 편히 쉬리라", "아무도 믿지 않으리라", "내가 이겼다"], "question": "사라가 이삭을 낳고 한 말은 무엇입니까?", "explanation": "17장과 18장에서 믿기지 않아 웃었던 웃음이, 여기서는 기쁨의 웃음으로 바뀝니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "아브라함이 이삭을 낳았을 때 나이는?", "choices": ["백 살", "일흔다섯 살", "아흔 살", "백이십 살"], "correctIndex": 0, "explanation": "아브라함이 백 세일 때 이삭이 태어났습니다."}, {"id": 3, "type": "choice", "choices": ["하갈의 눈을 밝혀 샘물을 보게 하심", "비를 내리심", "사람을 보내심", "아무 일도 안 하심"], "question": "광야에서 하갈과 아이가 위험할 때 하나님이 하신 일은?", "explanation": "하나님이 그 어린 아이의 소리를 들으셨고, 하갈의 눈을 밝히시니 샘물이 보였습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["매우 근심했다", "기뻐했다", "아무렇지 않았다", "화를 냈다"], "question": "이스마엘을 내보내는 일에 대한 아브라함의 마음은 어땠습니까?", "explanation": "아들 때문에 아브라함이 매우 근심했으나, 하나님이 사라의 말을 들으라 하시며 이스마엘도 큰 민족이 되게 하겠다고 하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "아브라함과 아비멜렉이 언약을 맺은 곳의 이름은?", "choices": ["브엘세바", "벧엘", "헤브론", "그랄"], "correctIndex": 0, "explanation": "두 사람이 거기서 맹세했으므로 브엘세바(\"맹세의 우물\")라 불렀습니다."}, {"id": 6, "type": "choice", "choices": ["그 우물을 자기가 팠다는 증거로 삼으려고", "선물로", "값을 치르려고", "제사를 위해"], "question": "아브라함이 아비멜렉에게 암양 새끼 일곱을 준 까닭은?", "explanation": "종들이 빼앗았던 우물을 두고 다툼이 있었고, 아브라함은 그 우물이 자기 것임을 증거로 남겼습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["하나님이 말씀하신 기한에 이르러", "뜻밖에", "아무도 모르게", "오랜 뒤에"], "question": "이삭이 태어난 때에 대해 성경이 적는 말은?", "explanation": "\"여호와께서 말씀하신 대로 사라를 돌보셨고 여호와께서 말씀하신 대로 사라에게 행하셨으므로\"라고 강조합니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 21;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "아브라함이 그곳에 붙인 이름은 무엇입니까?", "choices": ["여호와 이레", "여호와 닛시", "여호와 살롬", "엘엘로헤이스라엘"], "correctIndex": 0, "explanation": "\"여호와의 산에서 준비되리라\"는 말이 오늘까지 있다고 성경은 적습니다."}, {"id": 2, "type": "choice", "choices": ["번제할 어린 양은 어디 있나이까", "얼마나 더 가야 합니까", "왜 가는 겁니까", "집에 언제 갑니까"], "question": "이삭이 산에 오르며 물은 것은 무엇입니까?", "explanation": "불과 나무는 있는데 양이 없었습니다. 아브라함은 \"하나님이 친히 준비하시리라\"고 답했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["여호와의 사자가 하늘에서 불러 멈추게 함", "이삭이 도망침", "비가 내림", "아무 일 없음"], "question": "칼을 들었을 때 무슨 일이 있었습니까?", "explanation": "\"그 아이에게 네 손을 대지 말라\" 하시며 멈추게 하셨습니다. 아브라함의 경외함이 확인된 자리였습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["수풀에 뿔이 걸린 숫양", "송아지", "비둘기", "염소"], "question": "이삭 대신 드려진 것은 무엇입니까?", "explanation": "아브라함이 눈을 들어 보니 뒤에 숫양이 수풀에 뿔이 걸려 있었고 그것을 대신 번제로 드렸습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "하나님이 아브라함에게 가라고 하신 땅의 이름은?", "choices": ["모리아", "아라랏", "호렙", "시내"], "correctIndex": 0, "explanation": "모리아 땅의 한 산으로 가서 번제로 드리라고 하셨습니다."}, {"id": 6, "type": "choice", "choices": ["네 씨가 하늘의 별과 바닷가의 모래같이 많게 하겠다", "큰 부자가 되게 하겠다", "오래 살게 하겠다", "왕이 되게 하겠다"], "question": "이 일 뒤 하나님이 다시 확인해 주신 약속은 무엇입니까?", "explanation": "네 씨로 말미암아 천하 만민이 복을 받으리라는 약속도 함께 다시 주셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["아침 일찍 일어나 나귀에 안장을 지움", "사라와 의논함", "기도만 함", "미루었다"], "question": "아브라함이 명령을 받고 한 첫 행동은 무엇입니까?", "explanation": "성경은 설명이나 항변 없이 \"아침에 일찍이 일어나\"로 시작합니다. 그 순종이 이 장의 무게입니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 22;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "사라가 죽었을 때 나이는?", "choices": ["백이십칠 세", "구십 세", "백 세", "백삼십 세"], "correctIndex": 0, "explanation": "사라는 백이십칠 세를 살고 가나안 땅 헤브론에서 죽었습니다."}, {"id": 2, "type": "choice", "choices": ["묘실로 쓸 땅을 팔라는 것", "물을 달라는 것", "집을 달라는 것", "가축을 달라는 것"], "question": "아브라함이 헷 족속에게 청한 것은 무엇입니까?", "explanation": "아브라함은 자기가 나그네이자 거류하는 자라며 매장할 소유지를 팔라고 청했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["그 땅이 확실히 자기 소유가 되게 하려고", "돈이 많아서", "체면 때문에", "헷 족속이 요구해서"], "question": "아브라함이 값을 다 치르겠다고 고집한 까닭으로 알맞은 것은?", "explanation": "그냥 받으면 뒤에 다툼이 생길 수 있었습니다. 아브라함은 값을 달아 주고 정식으로 자기 소유가 되게 했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "아브라함이 산 굴의 이름은 무엇입니까?", "choices": ["막벨라", "마므레", "헤브론", "브엘세바"], "correctIndex": 0, "explanation": "마므레 앞 막벨라 밭과 그 속의 굴을 샀습니다."}, {"id": 5, "type": "choice", "choices": ["은 사백 세겔", "은 백 세겔", "은 천 세겔", "금 사백 세겔"], "question": "아브라함이 치른 값은 얼마입니까?", "explanation": "상인이 통용하는 은 사백 세겔을 달아 에브론에게 주었습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["하나님이 세우신 지도자", "나그네", "손님", "이방인"], "question": "헷 족속이 아브라함을 부른 말은 무엇입니까?", "explanation": "그들은 아브라함을 존중하여 가장 좋은 묘실을 쓰라고 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["약속의 땅에서 아브라함이 처음으로 소유한 땅", "가장 넓은 땅", "가장 비옥한 땅", "왕이 준 땅"], "question": "이 땅이 갖는 의미로 알맞은 것은?", "explanation": "온 땅을 주시겠다는 약속을 받았지만, 살아서 실제로 가진 것은 아내를 묻을 굴 하나였습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 23;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["고향 친척 중에서 이삭의 아내를 데려오는 것", "가나안에서 아내를 구하는 것", "땅을 사는 것", "가축을 파는 것"], "question": "아브라함이 종에게 시킨 일은 무엇입니까?", "explanation": "아브라함은 가나안 사람의 딸 중에서는 택하지 말라고 분명히 못 박았습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["낙타에게까지 물을 마시게 해 주는 여자", "가장 예쁜 여자", "가장 부유한 여자", "먼저 말을 거는 여자"], "question": "종이 우물가에서 구한 표징은 무엇입니까?", "explanation": "낙타 열 마리에게 물을 길어 주는 일은 보통 수고가 아니었습니다. 마음 씀씀이를 보는 표징이었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "우물가에서 만난 여자의 이름은 무엇입니까?", "choices": ["리브가", "라헬", "레아", "밀가"], "correctIndex": 0, "explanation": "리브가는 아브라함의 동생 나홀의 손녀로, 브두엘의 딸이었습니다."}, {"id": 4, "type": "choice", "choices": ["가겠나이다", "더 있겠습니다", "생각해 보겠습니다", "못 가겠습니다"], "question": "가족이 며칠 더 머물라 했을 때 리브가의 대답은?", "explanation": "리브가는 한마디로 결단했습니다. 아브라함이 고향을 떠났듯 리브가도 떠났습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["머리를 숙여 여호와께 경배하고 찬송함", "급히 돌아감", "값을 흥정함", "아무 말 없이 기다림"], "question": "종이 리브가를 만난 뒤 한 일은 무엇입니까?", "explanation": "\"나를 인도하사 내 주인의 동생 집에 이르게 하셨나이다\" 하며 그 자리에서 경배했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["저물 때에 들에 나가 묵상함", "양을 침", "집에서 잠", "우물을 팜"], "question": "이삭은 리브가가 올 때 무엇을 하고 있었습니까?", "explanation": "이삭이 저물 때 들에 나가 묵상하다가 눈을 들어 보니 낙타들이 오고 있었습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "리브가의 오라비 이름은 무엇입니까?", "choices": ["라반", "브두엘", "나홀", "라멕"], "correctIndex": 0, "explanation": "라반은 뒤에 야곱이 이십 년 동안 일하게 되는 외삼촌입니다."}]'::jsonb where book_id = 1 and chapter = 24;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["아이들이 서로 싸웠다", "조용했다", "한 아이만 움직였다", "아무 일 없었다"], "question": "리브가가 임신했을 때 태 속에서 있었던 일은?", "explanation": "아이들이 태 속에서 서로 싸우자 리브가가 여호와께 물으러 갔습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "하나님이 리브가에게 하신 말씀 — \"큰 자가 ○○ 자를 섬기리라\"", "choices": ["어린", "큰", "형된", "많은"], "correctIndex": 0, "explanation": "보통의 순서가 뒤집히는 말씀이었습니다. 이 예고가 창세기 뒷부분을 이끕니다."}, {"id": 3, "type": "choice", "choices": ["떡과 팥죽", "은 스무 개", "양 떼", "땅"], "question": "에서가 장자의 명분을 판 대가는 무엇입니까?", "explanation": "야곱이 떡과 팥죽을 주자 에서가 먹고 마시고 일어나 갔습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["장자의 명분을 가볍게 여겼다", "지혜로웠다", "용감했다", "억울했다"], "question": "성경이 에서에 대해 적은 평가는 무엇입니까?", "explanation": "\"에서가 장자의 명분을 가볍게 여김이었더라\"로 이 대목이 마무리됩니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "아브라함이 죽었을 때 나이는?", "choices": ["백칠십오 세", "백이십칠 세", "백팔십 세", "백십 세"], "correctIndex": 0, "explanation": "아브라함은 백칠십오 세를 살고 나이가 차서 죽었습니다."}, {"id": 6, "type": "choice", "choices": ["에서는 사냥꾼, 야곱은 조용히 장막에 거하는 사람", "둘 다 사냥꾼", "둘 다 농부", "에서는 목자, 야곱은 상인"], "question": "에서와 야곱은 각각 어떤 사람이었습니까?", "explanation": "이삭은 사냥한 고기를 좋아해 에서를 사랑했고 리브가는 야곱을 사랑했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["아이가 없으므로 여호와께 간구함", "다른 아내를 얻음", "기다리기만 함", "고향으로 돌아감"], "question": "이삭이 리브가를 위해 한 일은 무엇입니까?", "explanation": "이삭이 아내를 위하여 간구하매 여호와께서 들으셨고 리브가가 임신했습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 25;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["애굽으로 내려가지 말고 이 땅에 머물라", "애굽으로 가라", "산으로 가라", "고향으로 돌아가라"], "question": "흉년 때 하나님이 이삭에게 하신 말씀은 무엇입니까?", "explanation": "아버지 아브라함은 이집트로 내려갔지만, 이삭에게는 머물라고 하셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["내 누이", "내 아내", "내 딸", "아무 말 안 함"], "question": "이삭이 아비멜렉에게 리브가를 뭐라고 했습니까?", "explanation": "아버지가 두 번 했던 실수를 아들이 또 반복합니다. 사람들이 리브가 때문에 자기를 죽일까 두려워했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "이삭이 다툼 없이 얻어 이름 붙인 세 번째 우물의 이름은?", "choices": ["르호봇", "에섹", "싯나", "브엘세바"], "correctIndex": 0, "explanation": "\"이제는 여호와께서 우리를 위하여 넓게 하셨으니\" 하여 르호봇이라 했습니다. 앞의 둘은 에섹과 싯나였습니다."}, {"id": 4, "type": "choice", "choices": ["다투지 않고 자리를 옮겨 다시 팠다", "싸워서 되찾았다", "왕에게 고소했다", "떠나 버렸다"], "question": "이삭이 우물을 빼앗겼을 때 한 행동은 무엇입니까?", "explanation": "이삭은 세 번을 물러났습니다. 물러섬이 결국 넓은 자리로 이어졌습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["백 배", "열 배", "두 배", "삼십 배"], "question": "이삭이 그 땅에서 농사하여 얻은 수확은 얼마입니까?", "explanation": "그해에 백 배를 얻었고 여호와께서 복을 주셔서 창대하고 왕성했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["두려워하지 말라 내가 너와 함께 있어", "떠나라", "싸우라", "기다리라"], "question": "브엘세바에서 하나님이 하신 말씀은 무엇입니까?", "explanation": "아브라함의 하나님이심을 밝히시며 그를 위해 복을 주고 자손을 번성하게 하겠다고 하셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "아비멜렉이 이삭을 찾아와 맺자고 한 것은 무엇입니까?", "choices": ["언약", "제사", "혼인", "매매"], "correctIndex": 0, "explanation": "아비멜렉은 \"여호와께서 너와 함께 계심을 보았다\"며 서로 해치지 않기로 맹세했습니다."}]'::jsonb where book_id = 1 and chapter = 26;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["염소 새끼로 별미를 만들어 형인 척 축복을 받게 함", "에서를 설득하게 함", "아버지께 사실을 말하게 함", "집을 떠나게 함"], "question": "리브가가 야곱에게 시킨 일은 무엇입니까?", "explanation": "리브가가 계획을 세웠고 야곱은 들킬 것을 걱정했지만 어머니 말대로 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["염소 새끼의 가죽", "양털", "천", "흙"], "question": "야곱이 손과 목에 두른 것은 무엇입니까?", "explanation": "에서는 털이 많은 사람이었기 때문에 만졌을 때 속기 위해 가죽을 둘렀습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["음성은 야곱의 음성이나 손은 에서의 손이로다", "너는 누구냐", "거짓말하지 말라", "나가라"], "question": "이삭이 의심하며 한 말은 무엇입니까?", "explanation": "이삭은 여러 번 확인했지만 결국 알아보지 못하고 축복했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["큰 소리로 울며 자기에게도 축복해 달라고 함", "조용히 받아들임", "아버지를 원망함", "집을 나감"], "question": "축복을 빼앗긴 것을 안 에서의 반응은?", "explanation": "에서는 심히 통곡하며 \"내게도 축복하소서 내 아버지여\" 하고 부르짖었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "리브가가 야곱을 피신시킨 곳은 누구의 집입니까?", "choices": ["라반", "이스마엘", "아비멜렉", "브두엘"], "correctIndex": 0, "explanation": "리브가는 에서의 분노가 풀릴 때까지 하란의 오라버니 라반에게 가 있으라고 했습니다."}, {"id": 6, "type": "choice", "choices": ["아버지의 장례 날이 오면 야곱을 죽이겠다는 것", "용서하겠다는 것", "떠나겠다는 것", "다시 사냥하겠다는 것"], "question": "에서가 마음에 품은 것은 무엇입니까?", "explanation": "리브가가 이 말을 전해 듣고 서둘러 야곱을 보냈습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["집을 떠나 이십 년간 타향살이", "곧바로 큰 부자가 됨", "형과의 화해", "아버지의 재산"], "question": "이 장에서 얻은 복 뒤에 야곱에게 따라온 것은 무엇입니까?", "explanation": "속임수로 얻은 복은 곧바로 누려지지 않았습니다. 야곱은 빈손으로 도망쳐 오래 고생합니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 27;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["땅에서 하늘까지 닿은 사닥다리와 오르내리는 하나님의 사자들", "큰 물", "불기둥", "밝은 별"], "question": "야곱이 꿈에서 본 것은 무엇입니까?", "explanation": "하늘과 땅이 이어진 장면이었고 그 위에 하나님이 서 계셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "야곱이 그곳에 붙인 이름은 무엇입니까?", "choices": ["벧엘", "루스", "브엘세바", "세겜"], "correctIndex": 0, "explanation": "벧엘은 \"하나님의 집\"이라는 뜻입니다. 본래 그 성의 이름은 루스였습니다."}, {"id": 3, "type": "choice", "choices": ["여호와께서 과연 여기 계시거늘 내가 알지 못하였도다", "꿈일 뿐이다", "집으로 돌아가겠다", "두렵지 않다"], "question": "잠에서 깬 야곱이 한 말은 무엇입니까?", "explanation": "도망치는 길, 아무것도 없는 들판에도 하나님이 계셨다는 깨달음입니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["어디로 가든지 함께하며 지키고 이 땅으로 돌아오게 하겠다", "곧 부자가 되게 하겠다", "형을 벌하겠다", "오래 살게 하겠다"], "question": "하나님이 야곱에게 약속하신 것은 무엇입니까?", "explanation": "\"내가 네게 허락한 것을 다 이루기까지 너를 떠나지 아니하리라\"고 하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["베던 돌을 기둥으로 세우고 기름을 부음", "바로 떠남", "집을 지음", "제사를 드림"], "question": "야곱이 아침에 일어나 한 일은 무엇입니까?", "explanation": "그 자리를 표시하고 서원했습니다. 하나님이 함께하시면 여호와를 자기 하나님으로 삼겠다는 서원이었습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["모든 소산의 십분의 일", "양 떼", "첫 아들", "땅"], "question": "야곱이 서원하며 드리겠다고 한 것은 무엇입니까?", "explanation": "\"하나님께서 내게 주신 모든 것에서 십분의 일을 내가 반드시 하나님께 드리겠나이다\"라고 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "야곱이 베개로 삼은 것은 무엇입니까?", "choices": ["돌", "옷", "양털", "짚단"], "correctIndex": 0, "explanation": "그곳의 돌을 가져다 베개로 삼고 누워 잤습니다. 도망길의 형편이 그대로 드러납니다."}]'::jsonb where book_id = 1 and chapter = 28;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["칠 년", "삼 년", "십 년", "이십 년"], "question": "야곱이 라헬을 얻기 위해 일하기로 한 기간은?", "explanation": "\"외삼촌의 작은 딸 라헬을 위하여 칠 년을 외삼촌에게 봉사하리이다\" 하고 약속했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "\"그를 사랑하는 까닭에 칠 년을 ○○ 같이 여겼더라\" — ○○는?", "choices": ["며칠", "하루", "한 해", "잠깐"], "correctIndex": 0, "explanation": "사랑이 시간을 어떻게 느끼게 하는지 보여 주는 구절입니다."}, {"id": 3, "type": "choice", "choices": ["라헬 대신 언니 레아를 들여보냄", "잔치를 열지 않음", "야곱을 내쫓음", "값을 더 요구함"], "question": "혼인날 밤 라반이 한 일은 무엇입니까?", "explanation": "아침에야 그것이 레아인 줄 알게 되었습니다. 속임수로 형의 복을 가로챘던 야곱이 이번엔 속았습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["언니보다 아우를 먼저 주는 것은 우리 지방에서 하지 않는 일이다", "라헬이 원치 않았다", "값이 부족했다", "실수였다"], "question": "라반이 내세운 이유는 무엇입니까?", "explanation": "라반은 관습을 이유로 들며 라헬을 위해 또 칠 년을 일하라고 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "야곱이 라반의 집에서 두 아내를 위해 일한 햇수는 모두 몇 년입니까?", "choices": ["십사 년", "칠 년", "이십 년", "십 년"], "correctIndex": 0, "explanation": "레아를 위해 칠 년, 라헬을 위해 또 칠 년, 모두 십사 년입니다."}, {"id": 6, "type": "choice", "choices": ["여호와께서 레아가 사랑받지 못함을 보시고 그의 태를 여심", "레아가 기도해서", "라반이 부탁해서", "야곱이 원해서"], "question": "레아가 아들을 낳게 된 배경으로 성경이 적은 것은?", "explanation": "덜 사랑받는 쪽을 하나님이 먼저 보셨다는 대목입니다. 레아는 르우벤, 시므온, 레위, 유다를 낳습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["우물가", "장막", "들판", "성문"], "question": "야곱이 라헬을 처음 만난 곳은 어디입니까?", "explanation": "야곱은 우물의 돌을 옮기고 라헬의 양 떼에게 물을 먹인 뒤 소리 내어 울었습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 29;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["요셉", "유다", "단", "레위"], "question": "라헬이 오랫동안 아이를 낳지 못하다가 얻은 아들은 누구입니까?", "explanation": "\"하나님이 라헬을 생각하신지라\" 하고 요셉이 태어납니다. 라헬은 \"여호와는 다시 다른 아들을 내게 더하시기를 원하노라\"고 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["아이를 낳는 문제", "재산 문제", "집터 문제", "가축 문제"], "question": "레아와 라헬이 다툰 이유는 무엇입니까?", "explanation": "한 남편의 두 아내가 아들을 두고 경쟁했습니다. 이름 하나하나에 서운함과 바람이 그대로 담겨 있습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "라헬의 몸종 이름은 무엇입니까?", "choices": ["빌하", "실바", "디나", "레아"], "correctIndex": 0, "explanation": "라헬은 몸종 빌하를 야곱에게 주었고 단과 납달리가 태어났습니다."}, {"id": 4, "type": "choice", "choices": ["아롱진 것과 점 있는 것과 검은 양", "은과 금", "땅", "집"], "question": "야곱이 라반에게 요구한 품삯은 무엇이었습니까?", "explanation": "야곱은 흔하지 않은 무늬의 가축만 자기 몫으로 달라고 했습니다. 얼핏 손해 보는 조건처럼 보였습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["품삯을 여러 번 바꾸며 속였다", "늘 정직하게 대했다", "재산을 나눠 주었다", "아무 관심이 없었다"], "question": "라반은 야곱을 어떻게 대했습니까?", "explanation": "라반은 조건을 계속 바꿨습니다. 그런데도 야곱의 가축이 불어난 것을 성경은 하나님이 하신 일로 봅니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "레아가 낳은 아들 중 뒤에 유다 지파의 조상이 되는 아들은 누구입니까?", "choices": ["유다", "르우벤", "시므온", "레위"], "correctIndex": 0, "explanation": "유다는 앞선 29장에서 태어났고, 이 가문에서 뒤에 다윗과 예수님이 나옵니다."}, {"id": 7, "type": "choice", "choices": ["심히 번창하여 가축과 종이 많아졌다", "가진 것을 다 잃었다", "고향으로 돌아갔다", "병이 들었다"], "question": "이 장 끝에서 야곱의 형편은 어떻게 되었습니까?", "explanation": "\"이 사람이 매우 번창하여 양 떼와 노비와 낙타와 나귀가 많았더라\"로 마칩니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 30;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["하나님이 고향으로 돌아가라고 하심", "가축이 줄어들어서", "아내들이 원해서", "흉년이 들어서"], "question": "야곱이 떠나기로 한 계기는 무엇입니까?", "explanation": "\"네 조상의 땅으로 돌아가라 내가 너와 함께 있으리라\"는 말씀이 있었습니다. 라반의 태도가 변한 것도 함께 작용했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "라헬이 아버지 집에서 몰래 가져간 것은 무엇입니까?", "choices": ["드라빔", "은과 금", "양 떼", "옷"], "correctIndex": 0, "explanation": "라헬은 아버지의 드라빔(집안 우상)을 훔쳤습니다. 라반이 이것 때문에 끝까지 쫓아왔습니다."}, {"id": 3, "type": "choice", "choices": ["내 신을 도둑질하였느냐", "내 양을 죽였느냐", "내 집을 태웠느냐", "내 아들을 데려갔느냐"], "question": "라반이 야곱을 쫓아와 따진 것 중 하나는 무엇입니까?", "explanation": "라반은 딸들을 데려간 것과 자기 신(드라빔)을 훔쳐 간 것을 따졌습니다. 야곱은 훔친 줄 모르고 결백을 주장했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["낙타 안장 아래", "옷 속", "땅속", "나무 위"], "question": "라헬은 드라빔을 어디에 숨겼습니까?", "explanation": "라헬은 낙타 안장 아래 넣고 그 위에 앉아 있었습니다. 그래서 라반이 찾지 못했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "야곱과 라반이 돌무더기를 쌓고 약속한 곳의 이름은 무엇입니까?", "choices": ["미스바", "갈르엣", "벧엘", "마하나임"], "correctIndex": 0, "explanation": "\"우리가 서로 떠나 있을 때에 여호와께서 나와 너 사이를 살피시옵소서\" 하며 미스바라 불렀습니다."}, {"id": 6, "type": "choice", "choices": ["이십 년", "십 년", "칠 년", "삼십 년"], "question": "야곱이 라반의 집에서 일한 기간은 몇 년입니까?", "explanation": "두 아내를 위해 십사 년, 가축을 위해 육 년 — 모두 이십 년이라고 야곱이 직접 말합니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["하나님이 함께하셨기 때문", "자기 지혜 때문", "라반의 호의 때문", "운이 좋아서"], "question": "야곱이 자기 재산이 불어난 것을 무엇 때문이라고 말했습니까?", "explanation": "야곱은 아버지의 하나님이 함께하셨고, 하나님이 라반의 가축을 자기에게 주셨다고 말합니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 31;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["형 에서가 사백 명을 데리고 온다는 소식 때문", "라반이 다시 쫓아와서", "흉년이 들어서", "길을 잃어서"], "question": "야곱이 두려워한 이유는 무엇입니까?", "explanation": "이십 년 전 형의 복을 가로챈 일이 있었기에, 형이 사람들을 데리고 온다는 말에 심히 두렵고 답답했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "야곱이 밤새 씨름한 곳의 강 이름은 무엇입니까?", "choices": ["얍복", "요단", "기손", "그랄"], "correctIndex": 0, "explanation": "야곱은 얍복 나루에서 홀로 남았고 어떤 사람과 날이 새도록 씨름했습니다."}, {"id": 3, "type": "choice", "choices": ["허벅지 관절이 어긋남", "팔이 부러짐", "눈이 멀게 됨", "아무 일 없음"], "question": "씨름 중 야곱의 몸에 생긴 일은 무엇입니까?", "explanation": "그 사람이 야곱의 허벅지 관절을 치자 어긋났습니다. 그 뒤로 야곱은 다리를 절었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "야곱이 받은 새 이름은 무엇입니까?", "choices": ["이스라엘", "아브라함", "에돔", "브니엘"], "correctIndex": 0, "explanation": "\"네 이름을 다시는 야곱이라 부를 것이 아니요 이스라엘이라 부를 것이니.\" 하나님과 겨루어 이겼다는 뜻으로 설명됩니다."}, {"id": 5, "type": "choice", "choices": ["당신이 내게 축복하지 아니하면 가게 하지 아니하겠나이다", "나를 놓아 주소서", "나는 힘이 없습니다", "당신은 누구십니까"], "question": "야곱이 씨름하면서 한 말은 무엇입니까?", "explanation": "날이 새려 하니 놓으라는 말에도 야곱은 축복을 받기 전에는 놓지 않겠다고 붙들었습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["브니엘", "벧엘", "미스바", "마하나임"], "question": "야곱이 그곳 이름을 무엇이라 불렀습니까?", "explanation": "\"내가 하나님과 대면하여 보았으나 내 생명이 보전되었다\" 하여 브니엘이라 불렀습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["많은 가축을 선물로", "편지", "아무것도 안 보냄", "군사"], "question": "야곱이 형에게 먼저 보낸 것은 무엇입니까?", "explanation": "야곱은 염소·양·낙타·소·나귀를 떼로 나누어 앞서 보내며 형의 마음을 풀려 했습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 32;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["달려와 안고 입 맞추며 함께 울었다", "칼을 들고 쫓아왔다", "못 본 척했다", "돈을 요구했다"], "question": "에서는 야곱을 어떻게 맞이했습니까?", "explanation": "야곱이 가장 두려워한 장면이 가장 따뜻한 장면이 되었습니다. 두 형제가 목을 안고 울었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["일곱 번 땅에 엎드렸다", "달려갔다", "숨었다", "선물을 던졌다"], "question": "야곱이 형에게 나아갈 때 한 행동은 무엇입니까?", "explanation": "야곱은 형 앞에서 일곱 번 땅에 엎드려 절했습니다. 완전히 낮춘 자세로 나아갔습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["내게 있는 것이 족하다며 사양했다", "더 달라고 했다", "바로 받았다", "화를 냈다"], "question": "에서가 선물을 대하는 태도는 어떠했습니까?", "explanation": "에서는 \"내 것이 족하니 네 소유는 네게 두라\"고 했습니다. 야곱이 거듭 권하자 그제야 받았습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "야곱이 형과 헤어진 뒤 집과 우릿간을 지은 곳의 이름은?", "choices": ["숙곳", "세겜", "벧엘", "마하나임"], "correctIndex": 0, "explanation": "야곱은 숙곳에 이르러 자기를 위해 집을 짓고 가축을 위해 우릿간을 지었습니다."}, {"id": 5, "type": "choice", "choices": ["밭을 사고 제단을 쌓았다", "성을 쌓았다", "전쟁을 했다", "바로 떠났다"], "question": "야곱이 세겜에서 한 일은 무엇입니까?", "explanation": "세겜 성 앞 밭을 사고 거기 제단을 쌓아 \"엘엘로헤이스라엘\"이라 불렀습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["아이들과 어린 가축이 힘들어할까 봐", "형이 싫어서", "길을 몰라서", "짐이 무거워서"], "question": "야곱이 형과 함께 빨리 가지 않겠다고 한 이유는?", "explanation": "야곱은 아이들이 연약하고 젖 먹이는 짐승이 있어 하루만 몰아도 다 죽는다며 천천히 가겠다고 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "야곱이 세겜에 쌓은 제단의 이름은 무엇입니까?", "choices": ["엘엘로헤이스라엘", "여호와 이레", "여호와 닛시", "엘벧엘"], "correctIndex": 0, "explanation": "\"이스라엘의 하나님, 하나님\"이라는 뜻의 이름입니다."}]'::jsonb where book_id = 1 and chapter = 33;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "이 사건을 당한 야곱의 딸 이름은 무엇입니까?", "choices": ["디나", "리브가", "라헬", "다말"], "correctIndex": 0, "explanation": "레아가 야곱에게 낳은 딸 디나입니다."}, {"id": 2, "type": "choice", "choices": ["성읍의 남자가 모두 할례를 받을 것", "많은 돈을 낼 것", "성을 떠날 것", "땅을 넘길 것"], "question": "야곱의 아들들이 내건 조건은 무엇입니까?", "explanation": "아들들은 속임수로 말하며 할례를 조건으로 걸었습니다. 처음부터 공격할 생각이었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["시므온과 레위", "르우벤과 유다", "단과 납달리", "요셉과 베냐민"], "question": "성읍을 습격한 야곱의 두 아들은 누구입니까?", "explanation": "디나의 오라비 시므온과 레위가 각기 칼을 가지고 가서 성읍 남자들을 죽였습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["나를 이 땅 사람들에게 미움받게 했다며 꾸짖음", "잘했다고 칭찬함", "아무 말도 안 함", "함께 기뻐함"], "question": "야곱은 이 일을 어떻게 여겼습니까?", "explanation": "야곱은 이 땅 주민들에게 자기를 악취 나게 했다며 꾸짖었습니다. 수가 적어 자기 집이 위험해질 것을 걱정했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["그가 우리 누이를 창녀같이 대우함이 옳으니이까", "우리가 잘못했습니다", "더 죽이겠습니다", "떠나겠습니다"], "question": "습격한 아들들이 야곱에게 되받아친 말은 무엇입니까?", "explanation": "아들들은 누이가 당한 일을 들어 되물었습니다. 옳고 그름이 한쪽으로만 정리되지 않는 장면입니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "디나를 아내로 달라고 청한 사람의 이름은 무엇입니까?", "choices": ["세겜", "하몰", "에서", "라반"], "correctIndex": 0, "explanation": "히위 족속 하몰의 아들 세겜입니다. 그 성읍 이름도 세겜입니다."}, {"id": 7, "type": "choice", "choices": ["재물과 가축과 사람들을 빼앗아 왔다", "아무것도 가져오지 않았다", "성을 다시 세웠다", "땅을 사들였다"], "question": "습격 뒤 야곱의 아들들이 성읍에서 한 일은 무엇입니까?", "explanation": "양과 소와 나귀, 성읍과 들에 있는 것, 그리고 여자와 아이들까지 사로잡아 왔습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 34;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["벧엘", "세겜", "헤브론", "브니엘"], "question": "하나님이 야곱에게 올라가라고 하신 곳은 어디입니까?", "explanation": "\"일어나 벧엘로 올라가서 거기 거주하며 제단을 쌓으라.\" 도망하던 때 하나님을 만난 그 자리입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["이방 신상을 버리고 몸을 정결하게 하고 옷을 갈아입게 함", "짐을 싸게 함", "가축을 팔게 함", "아무것도 시키지 않음"], "question": "야곱이 벧엘로 올라가기 전 집안사람들에게 시킨 일은?", "explanation": "야곱은 이방 신상을 모아 상수리나무 아래 묻었습니다. 하나님께 나아가기 전 정리부터 한 것입니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "라헬이 낳다가 죽은 아들의 이름은 무엇입니까?", "choices": ["베냐민", "요셉", "단", "납달리"], "correctIndex": 0, "explanation": "라헬은 죽어 가며 \"베노니\"(내 슬픔의 아들)라 했지만 아버지는 \"베냐민\"(오른손의 아들)이라 불렀습니다."}, {"id": 4, "type": "choice", "choices": ["에브랏 곧 베들레헴 길가", "벧엘", "헤브론", "세겜"], "question": "라헬이 묻힌 곳은 어디입니까?", "explanation": "라헬은 에브랏(베들레헴) 길에 장사되었고 야곱이 그 묘에 비를 세웠습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["이스라엘이라는 이름과 언약", "많은 재산", "형과의 화해", "긴 수명"], "question": "이 장에서 하나님이 야곱에게 다시 확인해 주신 것은?", "explanation": "하나님은 \"네 이름이 이스라엘이 되리라\" 하시고 아브라함과 이삭에게 주신 땅의 약속을 이어 주셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "이 장에서 세상을 떠난 야곱의 아버지는 누구입니까?", "choices": ["이삭", "아브라함", "라반", "에서"], "correctIndex": 0, "explanation": "이삭은 백팔십 세에 죽었고 아들 에서와 야곱이 함께 장사했습니다."}, {"id": 7, "type": "choice", "choices": ["엘벧엘", "엘엘로헤이스라엘", "여호와 이레", "엘샤다이"], "question": "야곱이 벧엘에서 하나님을 부른 이름은 무엇입니까?", "explanation": "형의 낯을 피할 때 하나님이 나타나셨던 곳이라 그 제단을 엘벧엘이라 불렀습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 35;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "에서의 또 다른 이름은 무엇입니까?", "choices": ["에돔", "세일", "이스라엘", "이스마엘"], "correctIndex": 0, "explanation": "\"에서 곧 에돔의 족보는 이러하니라\"로 시작합니다."}, {"id": 2, "type": "choice", "choices": ["재산과 가축이 많아 한곳에 함께 살 수 없어서", "다시 싸워서", "하나님이 명하셔서", "흉년 때문에"], "question": "에서와 야곱이 갈라져 산 이유는 무엇입니까?", "explanation": "두 사람의 소유가 너무 많아 함께 지낼 수 없었고, 에서는 세일 산으로 갔습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["세일 산", "시내 산", "갈멜 산", "아라랏 산"], "question": "에서가 자리 잡은 산지의 이름은 무엇입니까?", "explanation": "에서는 세일 산에 거주했고 에돔 족속의 조상이 되었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["이스라엘에 왕이 서기 전 에돔에 있던 왕들", "에돔의 노래", "에돔의 법", "에돔의 성전"], "question": "이 족보가 특별히 적어 두는 것은 무엇입니까?", "explanation": "\"이스라엘 자손을 다스리는 왕이 있기 전에 에돔 땅을 다스리던 왕들은 이러하니라\"고 밝힙니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["가나안과 이스마엘의 딸", "애굽", "바벨론", "아람"], "question": "에서의 족보에서 그의 아내들은 어느 족속 출신입니까?", "explanation": "에서는 가나안 여인들과 이스마엘의 딸 바스맛을 아내로 맞았습니다. 부모가 기뻐하지 않았던 결혼입니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "에서는 누구의 형입니까?", "choices": ["야곱", "요셉", "이삭", "라반"], "correctIndex": 0, "explanation": "에서와 야곱은 이삭과 리브가에게서 난 쌍둥이 형제입니다."}, {"id": 7, "type": "choice", "choices": ["에서 쪽 이야기를 정리하고 야곱 쪽으로 넘어가려고", "에돔을 높이려고", "전쟁을 기록하려고", "땅값을 적으려고"], "question": "성경이 이 족보를 넣은 까닭으로 알맞은 것은?", "explanation": "창세기는 곁가지를 먼저 정리한 뒤 약속의 줄기로 돌아가는 방식을 반복합니다. 다음 장부터 요셉 이야기가 시작됩니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 36;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["채색옷", "금반지", "지팡이", "칼"], "question": "야곱이 요셉에게 지어 준 것은 무엇입니까?", "explanation": "야곱이 요셉을 다른 아들보다 사랑해 채색옷을 지어 입혔고, 형들은 그것을 보고 미워했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["해와 달과 열한 별이 자기에게 절함", "곡식 단이 절함", "구덩이에 빠짐", "왕이 됨"], "question": "요셉이 꾼 두 번째 꿈의 내용은 무엇입니까?", "explanation": "첫 꿈은 곡식 단, 둘째 꿈은 해와 달과 열한 별이었습니다. 아버지까지 꾸짖을 만큼 당돌한 꿈이었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "형들이 요셉을 판 값은 은 몇 개입니까?", "choices": ["은 이십", "은 삼십", "은 십", "은 백"], "correctIndex": 0, "explanation": "형들은 요셉을 이스마엘 사람들에게 은 이십에 팔았습니다."}, {"id": 4, "type": "choice", "choices": ["르우벤", "시므온", "레위", "단"], "question": "요셉을 죽이지 말자고 한 형은 누구입니까?", "explanation": "르우벤은 생명은 해치지 말고 구덩이에 던지자고 했습니다. 나중에 몰래 건져 내려던 생각이었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["유다", "르우벤", "납달리", "아셀"], "question": "요셉을 팔자고 제안한 형은 누구입니까?", "explanation": "유다가 \"동생을 죽이고 피를 덮어둔들 무엇이 유익하랴\" 하며 상인들에게 팔자고 했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["채색옷에 염소 피를 묻혀 보냄", "거짓 편지를 씀", "아무 말도 안 함", "다른 아이를 데려옴"], "question": "형들이 아버지를 속인 방법은 무엇입니까?", "explanation": "야곱은 옷을 알아보고 짐승에게 찢겼다고 여겨 오래도록 슬퍼했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "요셉이 팔려 간 나라는 어디입니까?", "choices": ["애굽", "가나안", "미디안", "하란"], "correctIndex": 0, "explanation": "요셉은 애굽으로 끌려가 바로의 신하 시위대장 보디발에게 팔렸습니다."}]'::jsonb where book_id = 1 and chapter = 37;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "유다가 \"그는 나보다 옳도다\"라고 말한 사람은 누구입니까?", "choices": ["다말", "리브가", "라헬", "디나"], "correctIndex": 0, "explanation": "유다는 자기가 셋째 아들을 주지 않은 잘못을 인정하며 다말이 자기보다 옳다고 말했습니다."}, {"id": 2, "type": "choice", "choices": ["도장과 끈과 지팡이", "양 한 마리", "옷", "은 이십"], "question": "다말이 담보로 받은 것은 무엇입니까?", "explanation": "신분을 증명하는 물건들이었습니다. 나중에 이것이 유다를 돌이키게 하는 증거가 됩니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["그 아들도 죽을까 두려워서", "다말이 싫어서", "아들이 어려서만", "다른 여자와 약혼해서"], "question": "유다가 다말에게 셋째 아들을 주지 않은 이유는 무엇입니까?", "explanation": "두 아들이 잇달아 죽자 유다는 셋째 셀라도 죽을까 두려워 약속을 미뤘습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["홍색 실", "금줄", "흰 천", "아무것도 없음"], "question": "다말이 낳은 쌍둥이 중 손을 먼저 내민 아이에게 맨 것은?", "explanation": "산파가 손에 홍색 실을 매었으나 그 손이 도로 들어가고 다른 아이가 먼저 나왔습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "다말이 낳은 쌍둥이 중 뒤에 다윗의 조상이 되는 아들은 누구입니까?", "choices": ["베레스", "세라", "오난", "셀라"], "correctIndex": 0, "explanation": "먼저 나온 베레스는 뒤에 다윗과 예수님으로 이어지는 계보에 들어갑니다."}, {"id": 6, "type": "choice", "choices": ["유다가 어떤 사람이었다가 어떻게 달라지는지 보여 주려고", "족보를 채우려고", "땅을 설명하려고", "전쟁을 기록하려고"], "question": "이 장이 요셉 이야기 사이에 들어간 까닭으로 알맞은 것은?", "explanation": "여기서 잘못을 인정한 유다는 뒤에 44장에서 동생 베냐민을 대신해 종이 되겠다고 나섭니다. 사람이 달라지는 이야기입니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["형의 대를 잇는 책임을 피함", "집을 나감", "아버지를 속임", "형을 도움"], "question": "유다의 둘째 아들 오난이 한 일은 무엇입니까?", "explanation": "오난은 자기 자손이 되지 않을 것을 알고 책임을 회피했고, 그 일이 여호와 보시기에 악했습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 38;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["여호와께서 요셉과 함께 하시므로", "요셉이 부자가 되었다", "요셉이 슬퍼했다", "요셉이 도망쳤다"], "question": "이 장에서 반복해서 나오는 말은 무엇입니까?", "explanation": "집에서도 감옥에서도 같은 말이 반복됩니다. 형편이 바뀌어도 함께하심은 바뀌지 않았다는 것입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "요셉을 산 애굽 사람의 이름은 무엇입니까?", "choices": ["보디발", "바로", "아비멜렉", "브두엘"], "correctIndex": 0, "explanation": "바로의 신하 친위대장 보디발이 요셉을 샀습니다."}, {"id": 3, "type": "choice", "choices": ["어찌 이 큰 악을 행하여 하나님께 죄를 지으리이까", "주인이 알면 큰일 납니다", "나는 종입니다", "다음에 하겠습니다"], "question": "요셉이 유혹을 거절하며 한 말은 무엇입니까?", "explanation": "요셉은 사람에게 들킬 걱정이 아니라 하나님께 죄를 짓는 문제로 보았습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["옷을 버려두고 밖으로 나갔다", "옷을 빼앗았다", "소리쳤다", "싸웠다"], "question": "요셉은 옷을 붙잡혔을 때 어떻게 했습니까?", "explanation": "요셉은 옷을 그 손에 버려두고 도망쳐 나갔습니다. 그 옷이 도리어 모함의 증거로 쓰였습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["간수장의 신임을 얻어 죄수들을 맡게 되었다", "곧 풀려났다", "병들었다", "다른 나라로 팔렸다"], "question": "요셉이 감옥에 갇힌 뒤 어떻게 되었습니까?", "explanation": "여호와께서 함께하시고 은혜를 주셔서 간수장이 옥중 모든 죄수를 요셉의 손에 맡겼습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["자기가 먹는 음식 외에는 모든 소유", "마당만", "가축만", "아무것도 안 맡김"], "question": "보디발이 요셉에게 맡긴 것은 어디까지였습니까?", "explanation": "보디발은 자기 먹는 음식 외에는 아무것도 간섭하지 않고 다 요셉에게 맡겼습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "요셉을 모함한 사람은 누구입니까?", "choices": ["보디발의 아내", "술 맡은 관원장", "떡 굽는 관원장", "간수장"], "correctIndex": 0, "explanation": "주인의 아내가 요셉의 옷을 증거로 삼아 거짓으로 고발했습니다."}]'::jsonb where book_id = 1 and chapter = 39;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["해석은 하나님께 있지 아니하니이까", "내가 잘 풉니다", "아무도 못 풉니다", "나중에 알려 주겠습니다"], "question": "요셉이 꿈 해석에 대해 한 말은 무엇입니까?", "explanation": "요셉은 자기 능력으로 돌리지 않고 하나님께 돌렸습니다. 이 태도가 41장에서 바로 앞에서도 그대로 나옵니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["술 맡은 관원장과 떡 굽는 관원장", "군인 두 명", "상인 두 명", "제사장 두 명"], "question": "감옥에서 꿈을 꾼 두 사람은 누구입니까?", "explanation": "바로에게 범죄한 술 맡은 관원장과 떡 굽는 관원장입니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["사흘 만에 복직했다", "사흘 만에 죽었다", "아무 일도 없었다", "다른 나라로 갔다"], "question": "술 맡은 관원장의 꿈은 어떻게 되었습니까?", "explanation": "요셉의 해석대로 사흘 만에 전과 같이 바로의 잔을 받드는 자리로 돌아갔습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "요셉이 두 꿈을 해석하며 말한 \"사흘\"은 무엇을 뜻했습니까?", "choices": ["사흘", "이레", "석 달", "삼 년"], "correctIndex": 0, "explanation": "포도나무 가지 세 개와 광주리 세 개가 각각 사흘을 뜻한다고 풀었습니다."}, {"id": 5, "type": "choice", "choices": ["복직하면 자기를 기억해 바로에게 말해 달라는 것", "음식을 달라는 것", "옷을 달라는 것", "편지를 전해 달라는 것"], "question": "요셉이 술 맡은 관원장에게 부탁한 것은 무엇입니까?", "explanation": "요셉은 자기가 억울하게 잡혀 왔음을 말하며 기억해 달라고 부탁했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["술 맡은 관원장이 요셉을 기억하지 못하고 잊었다", "요셉이 곧 풀려났다", "바로가 요셉을 불렀다", "요셉이 도망쳤다"], "question": "이 장의 마지막은 어떻게 끝납니까?", "explanation": "\"그를 기억하지 못하고 잊었더라\"로 끝납니다. 요셉은 이 뒤로 만 이 년을 더 감옥에 있게 됩니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["얼굴빛을 보고", "말을 듣고", "꿈을 함께 꾸고", "간수에게 듣고"], "question": "요셉이 두 사람의 근심을 알아챈 방법은 무엇입니까?", "explanation": "요셉은 아침에 그들의 근심하는 얼굴빛을 보고 \"어찌하여 오늘 얼굴에 근심의 빛이 있나이까\" 하고 물었습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 40;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["흉악하고 파리한 암소 일곱", "사자", "물", "불"], "question": "바로의 꿈에서 살진 암소 일곱을 삼킨 것은 무엇입니까?", "explanation": "여윈 암소가 살진 암소를 먹었는데도 여전히 흉악해 보였습니다. 흉년이 풍년의 흔적을 다 지운다는 뜻이었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["내가 아니라 하나님께서 바로에게 대답하시리이다", "제가 잘 풉니다", "값을 주시면 풀겠습니다", "아무도 못 풉니다"], "question": "요셉이 바로 앞에서 한 말은 무엇입니까?", "explanation": "감옥에서 두 관원장에게 했던 말과 똑같습니다. 자리에 상관없이 같은 태도였습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "꿈이 뜻한 풍년과 흉년은 각각 몇 해입니까?", "choices": ["일곱 해", "세 해", "열 해", "사십 해"], "correctIndex": 0, "explanation": "일곱 해 큰 풍년 뒤에 일곱 해 흉년이 온다는 뜻이었습니다."}, {"id": 4, "type": "choice", "choices": ["풍년에 곡식의 오분의 일을 거두어 저장하는 것", "다른 나라에서 사 오는 것", "백성을 옮기는 것", "아무 대책 없음"], "question": "요셉이 바로에게 제안한 대비책은 무엇입니까?", "explanation": "명철하고 지혜로운 사람을 세워 풍년의 곡식을 저장해 두었다가 흉년에 쓰자고 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "요셉이 애굽의 총리가 된 나이는?", "choices": ["서른 살", "열일곱 살", "마흔 살", "쉰 살"], "correctIndex": 0, "explanation": "요셉이 바로 앞에 설 때 삼십 세였습니다. 열일곱에 팔려 십삼 년 만이었습니다."}, {"id": 6, "type": "choice", "choices": ["므낫세와 에브라임", "단과 납달리", "베레스와 세라", "셈과 함"], "question": "요셉의 두 아들 이름은 무엇입니까?", "explanation": "므낫세는 \"잊어버리게 하셨다\", 에브라임은 \"번성하게 하셨다\"는 뜻으로 지은 이름입니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["술 맡은 관원장", "떡 굽는 관원장", "간수장", "보디발"], "question": "요셉을 기억해 낸 사람은 누구입니까?", "explanation": "40장 끝에서 요셉을 잊었던 그 사람이 만 이 년 뒤에야 자기 허물을 말하며 기억해 냈습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 41;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["요셉은 알아보았으나 형들은 알아보지 못했다", "서로 알아보았다", "둘 다 못 알아보았다", "형들만 알아보았다"], "question": "형들이 요셉을 만났을 때 어떻게 되었습니까?", "explanation": "이십 년 넘게 지났고 요셉은 애굽 총리 차림이었습니다. 요셉은 옛 꿈을 생각했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["정탐꾼", "도둑", "살인자", "거짓말쟁이"], "question": "요셉이 형들에게 씌운 혐의는 무엇입니까?", "explanation": "요셉은 \"너희는 정탐꾼이라\" 하며 몰아붙였고 막내를 데려오라고 요구했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "볼모로 잡혀 있게 된 형은 누구입니까?", "choices": ["시므온", "르우벤", "유다", "베냐민"], "correctIndex": 0, "explanation": "요셉은 시므온을 잡아 그들의 눈앞에서 결박했습니다."}, {"id": 4, "type": "choice", "choices": ["우리가 아우의 일로 말미암아 벌을 받는도다", "억울하다", "도망치자", "총리를 속이자"], "question": "형들이 자기들끼리 한 말은 무엇입니까?", "explanation": "이십 년 전 일을 스스로 꺼냈습니다. 통역을 세워 말하고 있었기에 요셉이 알아듣는 줄 몰랐습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["돌이켜 울었다", "화를 냈다", "웃었다", "자기를 밝혔다"], "question": "그 말을 들은 요셉은 어떻게 했습니까?", "explanation": "요셉은 그들을 떠나가서 울고 다시 돌아와 말했습니다. 아직 자기를 밝히지는 않았습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["두려워하며 하나님이 어찌 이렇게 하셨는가 했다", "기뻐했다", "돈을 나눴다", "돌려주러 갔다"], "question": "자루에서 돈을 발견한 형들의 반응은?", "explanation": "\"하나님이 어찌하여 우리에게 이런 일을 행하셨는가\" 하며 마음이 놀라 서로 쳐다보았습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "야곱이 절대 보낼 수 없다고 한 아들은 누구입니까?", "choices": ["베냐민", "시므온", "유다", "르우벤"], "correctIndex": 0, "explanation": "야곱은 요셉을 잃었고 시므온도 없는데 베냐민까지 데려가려 한다며 거절했습니다."}]'::jsonb where book_id = 1 and chapter = 42;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["유다", "르우벤", "시므온", "레위"], "question": "베냐민을 데려가겠다고 담보가 된 형은 누구입니까?", "explanation": "유다가 \"내가 그의 몸을 담보하오리니 내게 그 책임을 지우소서\" 하고 나섰습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["전능하신 하나님께서 그 사람 앞에서 은혜를 베푸시기를", "무사히 돌아오기를", "곡식을 많이 얻기를", "아무 말도 안 함"], "question": "야곱이 아들들을 보내며 한 기도는 무엇입니까?", "explanation": "\"내가 자식을 잃게 되면 잃으리로다\"라는 체념 같은 말과 함께 드린 기도였습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["마음이 타올라 안방에 들어가 울었다", "바로 자기를 밝혔다", "화를 냈다", "내보냈다"], "question": "요셉이 베냐민을 보고 한 일은 무엇입니까?", "explanation": "요셉은 얼굴을 씻고 나와 감정을 억제하며 음식을 차리라고 했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["나이 순서대로 자리에 앉혀졌기 때문", "음식이 많아서", "요셉이 말을 걸어서", "돈을 돌려받아서"], "question": "잔치에서 형제들이 놀란 이유는 무엇입니까?", "explanation": "아무도 알려 준 적 없는 형제들의 나이 순서를 정확히 알고 있었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "베냐민에게 준 몫은 다른 형제들의 몇 배였습니까?", "choices": ["다섯 배", "두 배", "세 배", "열 배"], "correctIndex": 0, "explanation": "베냐민의 몫은 다른 사람들의 다섯 배였습니다."}, {"id": 6, "type": "choice", "choices": ["안심하라, 너희 하나님이 재물을 자루에 넣어 주신 것이다", "너희가 훔쳤다", "모른다", "돌려받겠다"], "question": "형들이 자루의 돈에 대해 청지기에게 말했을 때 답은?", "explanation": "청지기는 돈을 이미 받았다고 하며 안심시키고 시므온도 데려다 주었습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["유향, 꿀, 향품, 몰약, 유향나무 열매, 감복숭아", "금과 은", "가축", "옷"], "question": "야곱이 애굽에 보낸 선물은 무엇입니까?", "explanation": "그 땅의 좋은 소산을 조금씩 담아 보냈습니다. 기근 중에도 낼 수 있는 최선이었습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 43;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["자기 은잔", "금덩이", "곡식", "편지"], "question": "요셉이 베냐민의 자루에 넣게 한 것은 무엇입니까?", "explanation": "요셉의 은잔을 몰래 넣게 하고 뒤쫓아가 찾아내게 했습니다. 형들의 마음을 보려는 마지막 시험이었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["옷을 찢고 함께 성으로 돌아갔다", "베냐민만 두고 떠났다", "도망쳤다", "싸웠다"], "question": "잔이 나왔을 때 형제들의 반응은 무엇입니까?", "explanation": "아무도 베냐민을 버리고 가지 않았습니다. 요셉을 팔아넘겼던 그 형제들이 아니었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "베냐민을 대신해 종이 되겠다고 나선 형은 누구입니까?", "choices": ["유다", "르우벤", "시므온", "레위"], "correctIndex": 0, "explanation": "37장에서 요셉을 팔자고 했던 유다가, 이번에는 동생을 대신하겠다고 나섭니다."}, {"id": 4, "type": "choice", "choices": ["아이가 없으면 아버지가 죽는다는 것", "자기가 결백하다는 것", "잔을 훔치지 않았다는 것", "돈을 더 내겠다는 것"], "question": "유다가 간청하며 든 이유는 무엇입니까?", "explanation": "아버지의 생명이 이 아이의 생명과 이어져 있다며, 아버지의 백발이 슬퍼하며 스올로 내려가게 할 수 없다고 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["잔이 발견된 자만 종이 되고 나머지는 돌아가라", "모두 종이 되라", "모두 돌아가라", "모두 가두라"], "question": "요셉이 처음 제시한 처분은 무엇입니까?", "explanation": "나머지를 놓아 주겠다고 한 것이 시험이었습니다. 형들은 그 제안을 받지 않았습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["자기가 아이의 담보가 되었다는 것", "자기가 맏아들이라는 것", "자기가 부자라는 것", "자기가 병들었다는 것"], "question": "유다가 자기 처지를 말하며 밝힌 것은 무엇입니까?", "explanation": "아버지 앞에서 담보가 되었기 때문에 자기가 대신 남겠다고 한 것입니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "이 장에서 형들이 옷을 찢은 까닭은 무엇입니까?", "choices": ["베냐민의 자루에서 잔이 나와서", "곡식을 다 잃어서", "시므온이 붙잡혀서", "아버지가 죽었다는 소식에"], "correctIndex": 0, "explanation": "옷을 찢는 것은 큰 슬픔과 절망을 나타내는 행동이었습니다."}]'::jsonb where book_id = 1 and chapter = 44;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "요셉이 형들에게 자기를 밝히며 한 첫 말은 무엇입니까?", "choices": ["나는 요셉이라", "두려워하지 말라", "내게로 가까이 오라", "나를 판 것을 근심하지 말라"], "correctIndex": 0, "explanation": "\"나는 요셉이라 내 아버지께서 아직 살아 계시니이까.\" 이십이 년 만의 한마디였습니다."}, {"id": 2, "type": "choice", "choices": ["하나님이 생명을 구원하시려고 먼저 보내셨다", "형들의 잘못이다", "자기 운명이다", "우연이다"], "question": "요셉이 자기가 팔려 온 일을 어떻게 설명했습니까?", "explanation": "형들의 잘못이 없어진 것은 아니지만, 요셉은 그 위에서 일하신 하나님을 보았습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["근심하지 말고 한탄하지 말라", "벌을 받으라", "떠나라", "비밀로 하라"], "question": "요셉이 형들에게 당부한 것은 무엇입니까?", "explanation": "\"당신들이 나를 이곳에 팔았다고 근심하지 마소서 한탄하지 마소서\"라고 했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["다섯 해", "두 해", "일곱 해", "열 해"], "question": "요셉이 말한 남은 흉년은 몇 해입니까?", "explanation": "이미 두 해가 지났고 아직 다섯 해가 남았으니 가족을 애굽으로 데려오라고 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["믿지 못하고 어리둥절했다", "바로 기뻐했다", "화를 냈다", "아무 말도 안 했다"], "question": "야곱이 처음 소식을 들었을 때 반응은?", "explanation": "요셉이 보낸 수레를 보고서야 야곱의 기운이 소생했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "요셉이 형들을 데려오라고 정해 준 땅의 이름은?", "choices": ["고센", "라암셋", "숙곳", "세겜"], "correctIndex": 0, "explanation": "요셉은 가족을 고센 땅에 살게 하여 자기 가까이 두겠다고 했습니다."}, {"id": 7, "type": "choice", "choices": ["길에서 다투지 말라", "빨리 오라", "아무 말도 말라", "돈을 아껴라"], "question": "요셉이 형들을 보내며 한 당부는 무엇입니까?", "explanation": "\"당신들은 길에서 다투지 말라\"고 했습니다. 서로 탓할 것을 알고 있었던 말입니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 45;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["애굽으로 내려가기를 두려워하지 말라 내가 함께 내려가겠다", "가지 말라", "기다리라", "혼자 가라"], "question": "브엘세바에서 하나님이 야곱에게 하신 말씀은?", "explanation": "함께 내려가시겠다는 말과 반드시 다시 올라오게 하시겠다는 약속을 함께 주셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "애굽으로 내려간 야곱의 집 사람은 모두 몇 명입니까?", "choices": ["칠십 명", "열두 명", "삼백 명", "육백 명"], "correctIndex": 0, "explanation": "야곱과 함께 애굽에 이른 사람은 모두 칠십 명이었습니다."}, {"id": 3, "type": "choice", "choices": ["브엘세바", "벧엘", "헤브론", "세겜"], "question": "야곱이 애굽으로 가는 길에 제사를 드린 곳은?", "explanation": "브엘세바는 아버지 이삭이 하나님을 만났던 곳이기도 합니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["요셉이 목을 어긋맞겨 안고 오래 울었다", "서로 인사만 했다", "바로 궁으로 갔다", "알아보지 못했다"], "question": "요셉과 야곱이 만났을 때 있었던 일은?", "explanation": "야곱은 \"네가 지금까지 살아 있으니 내가 죽어도 좋다\"고 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["우리는 목축하는 자라고 말하라", "농사꾼이라고 말하라", "아무 말도 말라", "상인이라고 말하라"], "question": "요셉이 가족에게 바로 앞에서 뭐라고 말하라고 했습니까?", "explanation": "애굽 사람은 목축하는 자를 가까이하지 않았기에, 그렇게 말하면 고센 땅에 따로 살 수 있었습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "야곱의 가족이 살게 된 땅의 이름은 무엇입니까?", "choices": ["고센", "라암셋", "브엘세바", "헤브론"], "correctIndex": 0, "explanation": "고센은 목축에 적합한 땅이었고 애굽 사람들과 떨어져 살 수 있는 곳이었습니다."}, {"id": 7, "type": "choice", "choices": ["하나님이 약속하신 땅을 떠나는 것이기 때문", "길이 멀어서", "요셉을 믿지 못해서", "가축이 많아서"], "question": "야곱이 애굽으로 가기를 두려워할 만했던 까닭은?", "explanation": "아브라함과 이삭에게 주신 땅을 떠나는 걸음이었습니다. 그래서 하나님이 먼저 안심시키셨습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 46;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["내 나그네 길의 세월이 백삼십 년이니이다", "기억나지 않습니다", "백 년입니다", "말할 수 없습니다"], "question": "바로가 나이를 묻자 야곱이 한 대답은?", "explanation": "야곱은 자기 인생을 \"나그네 길\"이라 부르고 험악한 세월이었다고 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["축복했다", "선물을 요구했다", "땅을 요구했다", "아무 말도 안 했다"], "question": "야곱이 바로에게 한 일은 무엇입니까?", "explanation": "야곱은 바로 앞에 나아갈 때와 나올 때 모두 바로를 축복했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "야곱의 가족이 자리 잡은 땅의 좋은 곳 이름은?", "choices": ["라암셋", "비돔", "숙곳", "놉"], "correctIndex": 0, "explanation": "바로의 명대로 애굽의 좋은 땅 라암셋에 거주지를 주었습니다."}, {"id": 4, "type": "choice", "choices": ["수확의 오분의 일을 바로에게 바치는 것", "세금을 없애는 것", "땅을 나눠 주는 것", "곡식을 공짜로 주는 것"], "question": "기근 중 요셉이 세운 제도는 무엇입니까?", "explanation": "오분의 사는 백성이 갖고 오분의 일을 바로에게 바치게 했고, 백성들은 \"우리를 살리셨다\"고 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["애굽에 장사하지 말고 조상의 묘실에 묻어 달라는 것", "재산을 나눠 달라는 것", "형들을 용서해 달라는 것", "가나안으로 돌아가 달라는 것"], "question": "야곱이 요셉에게 맹세하게 한 것은 무엇입니까?", "explanation": "야곱은 애굽에서 죽더라도 약속의 땅에 묻히기를 원했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["자기 땅과 몸", "집", "옷", "아무것도 없음"], "question": "애굽 백성이 곡식을 사기 위해 마지막에 내놓은 것은?", "explanation": "돈과 가축이 떨어지자 땅과 몸을 내놓았고, 요셉은 그들에게 씨앗을 주어 다시 농사짓게 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "야곱이 애굽에서 산 햇수는 몇 년입니까?", "choices": ["십칠 년", "칠 년", "십사 년", "삼십 년"], "correctIndex": 0, "explanation": "야곱은 애굽 땅에 십칠 년을 살았고 나이가 백사십칠 세가 되었습니다."}]'::jsonb where book_id = 1 and chapter = 47;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["팔을 엇바꾸어 오른손을 동생 머리에 얹음", "두 손을 들고 기도함", "아무 말 없이 안음", "지팡이를 짚음"], "question": "야곱이 축복할 때 한 특별한 행동은 무엇입니까?", "explanation": "눈이 어두워 실수한 것이 아니라 알고 한 일이었습니다. \"나도 안다 내 아들아 나도 안다\"고 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "야곱이 오른손을 얹은 손자의 이름은 무엇입니까?", "choices": ["에브라임", "므낫세", "베냐민", "요셉"], "correctIndex": 0, "explanation": "동생 에브라임이 형 므낫세보다 더 큰 지파가 되리라고 했습니다."}, {"id": 3, "type": "choice", "choices": ["내 아들로 삼겠다", "종으로 삼겠다", "애굽에 두겠다", "가나안으로 보내겠다"], "question": "야곱이 두 손자에 대해 선언한 것은 무엇입니까?", "explanation": "\"에브라임과 므낫세는 르우벤과 시므온처럼 내 것이 되리라\"고 했습니다. 그래서 두 손자가 지파가 됩니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["맏아들 므낫세에게 오른손이 가야 한다고 여겨서", "아버지가 실수한 줄 알아서만", "에브라임이 싫어서", "순서가 헷갈려서"], "question": "요셉이 아버지의 손을 옮기려 한 이유는 무엇입니까?", "explanation": "오른손의 축복이 맏아들의 몫이라고 생각했습니다. 그러나 야곱은 알고도 그렇게 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["평생 나를 기르신 하나님, 모든 환난에서 건지신 여호와의 사자", "멀리 계신 하나님", "두려운 하나님", "알 수 없는 하나님"], "question": "야곱이 축복하며 부른 하나님은 어떤 분이었습니까?", "explanation": "야곱은 자기 인생 전체를 돌아보며 하나님을 그렇게 불렀습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "야곱이 이 장에서 다시 이야기한, 하나님을 만난 곳은?", "choices": ["벧엘", "브엘세바", "세겜", "헤브론"], "correctIndex": 0, "explanation": "가나안 땅 루스(벧엘)에서 전능하신 하나님이 나타나 복 주신 일을 손자들에게 들려주었습니다."}, {"id": 7, "type": "choice", "choices": ["형들보다 세겜 땅 한 부분을 더 줌", "금과 은", "가축", "아무것도 안 줌"], "question": "야곱이 요셉에게 더 준 것은 무엇입니까?", "explanation": "야곱은 자기가 아모리 족속의 손에서 얻은 세겜 땅 한 부분을 요셉에게 더 주었습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 48;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["규가 유다를 떠나지 아니하리라", "가장 부자가 되리라", "가장 오래 살리라", "흩어지리라"], "question": "야곱이 유다에게 한 말의 핵심은 무엇입니까?", "explanation": "왕의 지팡이가 유다에게서 떠나지 않으리라는 말입니다. 다윗과 예수님이 이 지파에서 납니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["그들의 분노가 맹렬하니 흩으리라", "가장 강한 지파가 되리라", "왕이 되리라", "땅을 많이 얻으리라"], "question": "시므온과 레위에 대해 야곱이 말한 것은?", "explanation": "34장 세겜에서의 일을 두고 한 말입니다. 좋은 말만 하지 않았습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "야곱이 \"무성한 가지\"라고 부른 아들은 누구입니까?", "choices": ["요셉", "유다", "베냐민", "르우벤"], "correctIndex": 0, "explanation": "\"요셉은 무성한 가지 곧 샘 곁의 무성한 가지라\"며 하늘과 땅의 복을 말했습니다."}, {"id": 4, "type": "choice", "choices": ["물의 끓음 같았은즉 뛰어나지 못하리라", "가장 뛰어나리라", "왕이 되리라", "축복을 받으리라"], "question": "맏아들 르우벤에 대한 말은 무엇입니까?", "explanation": "맏아들의 권위가 있었으나 아버지의 침상을 더럽힌 일 때문에 뛰어나지 못하리라 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "야곱이 자기를 어디에 장사해 달라고 했습니까?", "choices": ["막벨라 굴", "벧엘", "세겜의 밭", "라마의 길가"], "correctIndex": 0, "explanation": "아브라함과 사라, 이삭과 리브가, 레아가 묻힌 막벨라 굴을 지목했습니다."}, {"id": 6, "type": "choice", "choices": ["앞으로 당할 일을 각 사람에 맞게 이른 말", "재산 분배", "유언장", "단순한 인사"], "question": "야곱이 아들들에게 말한 것은 어떤 성격의 말이었습니까?", "explanation": "\"너희에게 후일에 당할 일을 내가 이르리라\" 하고 시작합니다. 축복이면서 동시에 예고였습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["발을 침상에 모으고 기운이 다하여 죽어 자기 백성에게로 돌아감", "갑자기 쓰러짐", "길에서 죽음", "홀로 죽음"], "question": "야곱이 숨을 거둘 때의 모습은 어떻게 적혀 있습니까?", "explanation": "할 말을 다 마치고 조용히 정리된 죽음이었습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 49;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "\"당신들은 나를 해하려 하였으나 하나님은 그것을 ○으로 바꾸사\" — ○은?", "choices": ["선", "복", "의", "빛"], "correctIndex": 0, "explanation": "요셉 이야기 전체를 한 문장으로 요약하는 구절입니다. 형들의 악을 없던 일로 하지 않으면서도 하나님의 손을 봅니다."}, {"id": 2, "type": "choice", "choices": ["요셉이 이제 보복할까 봐", "기근이 다시 올까 봐", "애굽에서 쫓겨날까 봐", "재산을 잃을까 봐"], "question": "아버지가 죽은 뒤 형들이 두려워한 이유는 무엇입니까?", "explanation": "형들은 아버지의 말이라며 용서를 구하는 전갈을 보냈고, 요셉은 그 말을 들을 때 울었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["두려워하지 마소서 내가 당신들과 당신들의 자녀를 기르리이다", "이제 갚겠소", "떠나시오", "아무 말도 안 함"], "question": "요셉이 형들에게 한 말은 무엇입니까?", "explanation": "요셉은 \"내가 하나님을 대신하리이까\" 하며 간곡한 말로 위로했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "요셉이 죽었을 때 나이는?", "choices": ["백십 세", "백이십칠 세", "백사십칠 세", "백칠십오 세"], "correctIndex": 0, "explanation": "요셉은 백십 세에 죽어 애굽에서 입관되었습니다."}, {"id": 5, "type": "choice", "choices": ["하나님이 반드시 당신들을 돌보시고 이 땅에서 인도하여 내시리라", "애굽에 머물라", "나를 잊으라", "재산을 나누라"], "question": "요셉이 죽으며 형제들에게 남긴 말은 무엇입니까?", "explanation": "아브라함에게 하신 약속을 붙들고 한 말입니다. 창세기는 아직 이루어지지 않은 약속을 바라보며 끝납니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["하나님이 돌보실 때 내 해골을 메고 올라가라", "애굽에 묻어 달라", "바다에 뿌려 달라", "아무 말도 안 함"], "question": "요셉이 자기 뼈에 대해 부탁한 것은 무엇입니까?", "explanation": "요셉의 유골은 출애굽 때 실제로 함께 올라가 여호수아 때 세겜에 묻힙니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["칠십 일", "삼십 일", "이레", "일 년"], "question": "야곱의 장례를 위해 애굽 사람들이 애곡한 기간은?", "explanation": "애굽 사람들이 칠십 일 동안 애곡했고, 그 뒤 큰 행렬이 가나안으로 올라갔습니다.", "correctIndex": 0}]'::jsonb where book_id = 1 and chapter = 50;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["너무 많아지고 강해져서 전쟁 때 적과 합할까 봐", "재산이 많아서", "왕을 세울까 봐", "농사를 안 지어서"], "question": "바로가 이스라엘 백성을 두려워한 이유는 무엇입니까?", "explanation": "\"이 백성이 우리보다 많고 강하도다\" 하며 지혜롭게 대하자고 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["더욱 번성하고 퍼져 나갔다", "수가 줄었다", "흩어졌다", "항복했다"], "question": "학대를 받은 이스라엘 백성은 어떻게 되었습니까?", "explanation": "\"학대를 받을수록 더욱 번성하여 퍼져 나가니.\" 사람의 계획이 하나님의 뜻을 막지 못했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "바로의 명령을 따르지 않은 두 산파의 이름은?", "choices": ["십브라와 부아", "미리암과 요게벳", "십보라와 미리암", "요게벳과 부아"], "correctIndex": 0, "explanation": "십브라와 부아는 하나님을 두려워하여 남자아이를 살렸습니다."}, {"id": 4, "type": "choice", "choices": ["하나님이 그들에게 은혜를 베푸시고 집안을 흥왕하게 하심", "벌을 받음", "쫓겨남", "아무 일 없음"], "question": "산파들이 하나님을 두려워한 결과는 무엇입니까?", "explanation": "하나님은 산파들을 선대하시고 그들의 집안을 흥왕하게 하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["남자아이가 나거든 나일강에 던지라", "모두 노예로 삼으라", "나라 밖으로 내보내라", "세금을 걷으라"], "question": "바로가 마지막으로 내린 명령은 무엇입니까?", "explanation": "산파들을 통한 방법이 통하지 않자 온 백성에게 직접 명령했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["비돔과 라암셋", "멤피스와 테베", "고센과 소알", "바벨과 니느웨"], "question": "이스라엘 백성이 지은 국고성은 무엇입니까?", "explanation": "감독을 세워 무거운 짐으로 괴롭게 하며 비돔과 라암셋을 건축하게 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "이 장은 누구를 알지 못하는 새 왕이 일어나면서 시작합니까?", "choices": ["요셉", "야곱", "모세", "아브라함"], "correctIndex": 0, "explanation": "\"요셉을 알지 못하는 새 왕이 일어나.\" 애굽을 살린 사람이 잊히면서 고난이 시작됩니다."}]'::jsonb where book_id = 2 and chapter = 1;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["석 달", "한 달", "일 년", "이레"], "question": "모세의 어머니가 아이를 숨긴 기간은 얼마입니까?", "explanation": "준수한 아이임을 보고 석 달 동안 숨겼다가 더 숨길 수 없어 갈대 상자에 넣었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["바로의 딸", "산파", "누이", "애굽 병사"], "question": "아이를 건진 사람은 누구입니까?", "explanation": "바로의 딸이 목욕하러 강에 내려왔다가 갈대 사이의 상자를 보고 건져 냈습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["아이의 친어머니", "바로의 딸", "누이", "이웃 여인"], "question": "아이의 유모가 된 사람은 누구입니까?", "explanation": "누이가 나서서 히브리 여인을 부르겠다고 했고, 데려온 사람이 친어머니였습니다. 삯까지 받으며 자기 아들을 길렀습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "\"모세\"라는 이름의 뜻으로 성경이 밝히는 것은?", "choices": ["물에서 건져냈다", "광야에서 자랐다", "왕자로 컸다", "형에게서 났다"], "correctIndex": 0, "explanation": "\"내가 그를 물에서 건져내었음이라\" 하여 모세라 불렀습니다."}, {"id": 5, "type": "choice", "choices": ["애굽 사람을 쳐죽인 일이 드러나서", "흉년이 들어서", "바로가 불러서", "하나님이 명하셔서"], "question": "모세가 미디안으로 도망친 이유는 무엇입니까?", "explanation": "히브리 사람이 \"누가 너를 우리를 다스리는 자로 삼았느냐\"고 하자 일이 탄로 난 줄 알고 도망쳤습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "모세가 미디안에서 결혼한 여인의 이름은?", "choices": ["십보라", "미리암", "요게벳", "엘리세바"], "correctIndex": 0, "explanation": "미디안 제사장의 딸 십보라와 결혼해 아들 게르솜을 낳았습니다."}, {"id": 7, "type": "choice", "choices": ["그들의 고통 소리를 들으시고 언약을 기억하심", "바로를 벌하심", "모세를 부르심", "아무 일도 안 하심"], "question": "이 장의 마지막에 하나님이 하신 일은 무엇입니까?", "explanation": "하나님이 그 신음 소리를 들으시고 아브라함·이삭·야곱과 세운 언약을 기억하셨습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 2;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["떨기나무에 불이 붙었는데 타지 않음", "바위가 갈라짐", "하늘이 열림", "물이 피가 됨"], "question": "모세가 본 이상한 광경은 무엇입니까?", "explanation": "모세가 \"어찌하여 떨기나무가 타지 아니하는고\" 하고 돌이켜 보러 갔을 때 하나님이 부르셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "하나님이 이름을 물었을 때 하신 대답은 무엇입니까?", "choices": ["나는 스스로 있는 자이니라", "나는 전능한 하나님이라", "나는 네 조상의 하나님이라", "나는 여호와 이레라"], "correctIndex": 0, "explanation": "\"나는 스스로 있는 자이니라.\" 누구에게도 기대지 않고 스스로 계신 분이라는 뜻입니다."}, {"id": 3, "type": "choice", "choices": ["네 발에서 신을 벗으라", "가까이 오라", "엎드리라", "눈을 감으라"], "question": "하나님이 모세에게 먼저 하신 명령은 무엇입니까?", "explanation": "\"네가 선 곳은 거룩한 땅이니라\" 하시며 신을 벗게 하셨습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["내가 누구이기에 바로에게 가리이까", "곧 가겠나이다", "기뻐했다", "아무 말도 안 했다"], "question": "모세가 부르심에 처음 보인 반응은 무엇입니까?", "explanation": "모세는 물러섰고, 하나님은 \"내가 반드시 너와 함께 있으리라\"고 답하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["젖과 꿀이 흐르는 땅", "광야", "애굽의 좋은 땅", "바다 건너 섬"], "question": "하나님이 이스라엘을 인도해 들이겠다고 하신 땅은?", "explanation": "아름답고 광대한 땅, 젖과 꿀이 흐르는 땅으로 인도하겠다고 하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "모세가 하나님을 만난 산의 이름은 무엇입니까?", "choices": ["호렙", "시내", "모리아", "아라랏"], "correctIndex": 0, "explanation": "호렙은 뒤에 시내산이라고도 불리는 같은 산입니다."}, {"id": 7, "type": "choice", "choices": ["아브라함의 하나님, 이삭의 하나님, 야곱의 하나님", "만군의 여호와", "전능한 하나님", "거룩한 하나님"], "question": "하나님이 자신을 소개하신 말은 무엇입니까?", "explanation": "조상들과 맺은 언약을 이어 오신 분임을 먼저 밝히셨습니다. 모세는 두려워 얼굴을 가렸습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 3;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["지팡이가 뱀이 되는 것", "물이 피가 되는 것", "손이 희어지는 것", "불이 내리는 것"], "question": "하나님이 모세에게 주신 첫 번째 표적은 무엇입니까?", "explanation": "지팡이를 땅에 던지자 뱀이 되었고, 꼬리를 잡으니 다시 지팡이가 되었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["나는 입이 뻣뻣하고 혀가 둔한 자니이다", "나이가 많습니다", "길이 멉니다", "가족이 있습니다"], "question": "모세가 마지막으로 내세운 이유는 무엇입니까?", "explanation": "하나님은 \"누가 사람의 입을 지었느냐\" 하시며 입과 함께하여 할 말을 가르치겠다고 하셨습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "하나님이 모세를 돕도록 붙여 주신 형의 이름은?", "choices": ["아론", "훌", "여호수아", "갈렙"], "correctIndex": 0, "explanation": "아론이 모세를 대신해 백성에게 말하게 하셨습니다. 모세가 끝내 사양하자 하나님이 노하셨습니다."}, {"id": 4, "type": "choice", "choices": ["손을 품에 넣으면 나병처럼 희어졌다가 회복되는 것", "지팡이가 꽃피는 것", "땅이 갈라지는 것", "해가 어두워지는 것"], "question": "두 번째 표적은 무엇입니까?", "explanation": "손을 품에 넣었다 내니 나병처럼 되었고, 다시 넣었다 내니 본래대로 회복되었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["머리 숙여 경배함", "믿지 않음", "화를 냄", "떠나감"], "question": "백성이 모세와 아론의 말을 듣고 한 일은?", "explanation": "여호와께서 그들을 찾으시고 고난을 살피셨다 함을 듣고 머리 숙여 경배했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["바로가 마음이 완악하여 보내지 아니하리라", "바로가 곧 허락하리라", "길이 험하리라", "백성이 반대하리라"], "question": "하나님이 모세에게 미리 알려 주신 것은 무엇입니까?", "explanation": "쉽게 풀리지 않을 것을 미리 말씀하시고, 이스라엘은 내 아들 내 장자라고 하셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "세 번째 표적은 나일 물이 무엇이 되는 것입니까?", "choices": ["피", "쓴 물", "불", "모래"], "correctIndex": 0, "explanation": "두 표적도 믿지 않으면 나일 물을 땅에 부으라, 그 물이 피가 되리라고 하셨습니다."}]'::jsonb where book_id = 2 and chapter = 4;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["여호와가 누구이기에 내가 그의 말을 듣겠느냐", "알겠다", "생각해 보겠다", "나가라"], "question": "바로가 모세의 말에 한 첫 대답은 무엇입니까?", "explanation": "\"나는 여호와를 알지 못하니 이스라엘을 보내지 아니하리라\"고 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["짚을 주지 말고 벽돌 수는 그대로 채우게 하라", "일을 줄이라", "먹을 것을 주지 말라", "집을 부수라"], "question": "바로가 새로 내린 명령은 무엇입니까?", "explanation": "백성이 게으르기 때문에 이런 말을 한다며 일을 더 무겁게 했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["여호와는 너희를 살피시고 판단하시기를 원하노라", "고맙습니다", "더 힘내십시오", "함께 갑시다"], "question": "백성이 모세와 아론에게 한 말은 무엇입니까?", "explanation": "우리를 바로의 눈에 미움받게 하여 죽일 칼을 그들 손에 주었다며 원망했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["어찌하여 이 백성이 학대를 당하게 하셨나이까", "감사합니다", "더 기다리겠습니다", "아무 말도 안 함"], "question": "모세가 하나님께 한 말은 무엇입니까?", "explanation": "\"주께서 나를 보내신 것은 무엇 때문이니이까\" 하고 따졌습니다. 시작이 더 나빠졌기 때문입니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "이스라엘 백성이 벽돌을 만들 때 부족해진 재료는?", "choices": ["짚", "물", "흙", "나무"], "correctIndex": 0, "explanation": "짚 없이 벽돌을 만들되 수량은 줄이지 말라고 해서 백성이 온 땅에 흩어져 그루터기를 모았습니다."}, {"id": 6, "type": "choice", "choices": ["이스라엘 자손의 기록원들", "감독들", "모세와 아론", "산파들"], "question": "매를 맞은 사람들은 누구입니까?", "explanation": "수량을 못 채웠다는 이유로 이스라엘 기록원들이 매를 맞았고, 그들이 바로에게 호소했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["순종을 시작했는데 형편이 더 나빠질 수도 있다는 것", "순종하면 곧 좋아진다는 것", "바로가 좋은 왕이라는 것", "모세가 잘못했다는 것"], "question": "이 장이 보여 주는 것으로 알맞은 것은?", "explanation": "하나님의 명령을 따랐는데 상황은 더 나빠졌습니다. 6장에서 하나님이 다시 말씀하십니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 5;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["이제 내가 바로에게 행할 일을 네가 보리라", "기다려라", "돌아가라", "다른 사람을 보내겠다"], "question": "하나님이 낙심한 모세에게 하신 말씀은?", "explanation": "강한 손으로 말미암아 바로가 그들을 보내고 쫓아내리라고 하셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["너희를 부자가 되게 하리라", "너희를 그 고역 아래에서 빼내며", "너희를 내 백성으로 삼고", "그 땅을 너희에게 주어 기업을 삼게 하리라"], "question": "하나님이 주신 약속에 들어 있지 않은 것은?", "explanation": "빼내고 건지고 구속하고 백성 삼고 하나님이 되고 인도하고 기업으로 주시겠다는 약속이 이어집니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["마음이 상하고 고역이 심했기 때문", "말을 못 알아들어서", "모세를 미워해서", "바로가 막아서"], "question": "백성이 모세의 말을 듣지 못한 이유는 무엇입니까?", "explanation": "좋은 소식을 들을 힘조차 남아 있지 않은 상태였습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "모세와 아론은 어느 지파 사람입니까?", "choices": ["레위", "유다", "베냐민", "르우벤"], "correctIndex": 0, "explanation": "이 장의 족보는 모세와 아론이 레위 지파 아므람과 요게벳의 아들임을 밝힙니다."}, {"id": 5, "type": "choice", "choices": ["여호와", "엘샤다이", "엘로힘", "아도나이"], "question": "하나님이 조상들에게 알리지 않았다고 하신 이름은?", "explanation": "전능의 하나님으로는 나타나셨으나 여호와라는 이름으로는 알리지 않으셨다고 하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["나는 입이 둔한 자니 바로가 어찌 내 말을 들으리이까", "못 하겠습니다", "시간을 주십시오", "아무 말도 안 함"], "question": "모세가 다시 물러서며 한 말은 무엇입니까?", "explanation": "백성도 듣지 않는데 바로가 듣겠느냐는 것이었습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "모세의 부모 이름은 무엇입니까?", "choices": ["아므람과 요게벳", "아론과 미리암", "고핫과 요게벳", "아므람과 엘리세바"], "correctIndex": 0, "explanation": "아므람이 고모 요게벳을 아내로 맞아 아론과 모세를 낳았습니다."}]'::jsonb where book_id = 2 and chapter = 6;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["애굽 술사들의 지팡이를 삼켰다", "사라졌다", "다시 지팡이가 되었다", "아무 일 없었다"], "question": "아론의 지팡이가 뱀이 되었을 때 무슨 일이 있었습니까?", "explanation": "술사들도 같은 일을 했지만 아론의 지팡이가 그들의 것을 삼켰습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "첫 번째 재앙은 무엇입니까?", "choices": ["나일 물이 피가 된 것", "개구리", "이", "파리 떼"], "correctIndex": 0, "explanation": "나일 물이 피가 되어 고기가 죽고 강에서 악취가 나 물을 마실 수 없었습니다."}, {"id": 3, "type": "choice", "choices": ["내가 여호와인 줄 알리라", "모세가 강한 줄 알리라", "이스라엘이 많은 줄 알리라", "바로가 약한 줄 알리라"], "question": "재앙을 통해 애굽 사람이 알게 될 것은 무엇이라고 하셨습니까?", "explanation": "재앙의 목적이 벌 자체가 아니라 여호와가 누구신지 알게 하는 데 있음을 밝힙니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["강가를 팠다", "비를 기다렸다", "바다로 갔다", "아무것도 안 했다"], "question": "애굽 사람들이 마실 물을 얻으려고 한 일은?", "explanation": "강물을 마실 수 없어 강 주변을 파서 물을 얻으려 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["마음을 완악하게 하고 궁으로 들어감", "곧 허락함", "모세를 불러 사과함", "백성을 풀어 줌"], "question": "바로의 반응은 어떠했습니까?", "explanation": "술사들도 같은 일을 하자 마음에 두지 않고 궁으로 들어갔습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "이 일들이 있었을 때 모세와 아론의 나이는 각각 몇 살입니까? (모세)", "choices": ["여든 살", "마흔 살", "예순 살", "백스무 살"], "correctIndex": 0, "explanation": "바로에게 말할 때 모세는 팔십 세, 아론은 팔십삼 세였습니다."}, {"id": 7, "type": "choice", "choices": ["이레", "하루", "한 달", "사흘"], "question": "첫 재앙이 지속된 기간은 얼마입니까?", "explanation": "여호와께서 나일강을 치신 후 이레가 지났습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 7;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["개구리", "이", "파리", "메뚜기"], "question": "두 번째 재앙은 무엇입니까?", "explanation": "개구리가 강에서 올라와 집과 침실과 화덕과 반죽 그릇에까지 들어갔습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["내일", "지금 당장", "모레", "언제든지"], "question": "모세가 개구리를 언제 없애 줄지 묻자 바로의 대답은?", "explanation": "당장 없애 달라 하지 않고 \"내일\"이라 한 것이 눈에 띕니다. 하룻밤을 더 개구리와 지낸 셈입니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["이는 하나님의 권능이니이다", "우리도 할 수 있습니다", "더 해 보겠습니다", "아무 말도 안 했다"], "question": "술사들이 흉내내지 못하고 한 말은 무엇입니까?", "explanation": "세 번째 이 재앙에서 술사들이 손을 들었습니다. 그래도 바로의 마음은 완악했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "네 번째 재앙부터 구별된 땅의 이름은?", "choices": ["고센", "라암셋", "숙곳", "비돔"], "correctIndex": 0, "explanation": "내 백성이 사는 고센 땅은 구별하여 파리 떼가 없게 하시겠다고 하셨습니다."}, {"id": 5, "type": "choice", "choices": ["이 땅에서 제사를 드리라", "모두 나가라", "남자만 나가라", "가축은 두고 가라"], "question": "바로가 타협안으로 제시한 것은 무엇입니까?", "explanation": "모세는 애굽 사람이 미워하는 제사이므로 사흘 길쯤 광야로 나가야 한다고 답했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["숨을 돌리고 다시 마음을 완악하게 함", "약속을 지킴", "백성을 보냄", "모세를 불러 감사함"], "question": "개구리가 없어진 뒤 바로는 어떻게 했습니까?", "explanation": "\"숨을 쉴 수 있게 됨을 보았을 때에 그의 마음을 완강하게 하여\"라고 적습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["땅의 티끌", "물", "하늘", "나무"], "question": "세 번째 재앙은 무엇에서 나왔습니까?", "explanation": "아론이 지팡이로 땅의 티끌을 치자 티끌이 애굽 온 땅에서 이가 되었습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 8;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["하나도 죽지 않았다", "절반이 죽었다", "모두 죽었다", "병들었다"], "question": "다섯째 재앙에서 이스라엘의 가축은 어떻게 되었습니까?", "explanation": "애굽의 가축은 죽었으나 이스라엘 자손의 가축은 하나도 죽지 않았습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["독종", "우박", "메뚜기", "흑암"], "question": "여섯째 재앙은 무엇입니까?", "explanation": "풀무의 재를 하늘로 날리자 사람과 짐승에게 악성 종기가 생겼습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["미리 경고하여 사람과 짐승을 집으로 들이게 하심", "아무 예고 없이 치심", "바로만 부르심", "이스라엘만 알리심"], "question": "우박 재앙 전에 하나님이 하신 일은 무엇입니까?", "explanation": "경고를 들은 신하들은 종과 가축을 피하게 했고, 마음에 두지 않은 자들은 들에 두었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["내 능력을 보이고 내 이름이 온 천하에 전파되게 하려 함", "바로를 벌하려고", "애굽을 멸하려고", "이유 없음"], "question": "하나님이 바로를 세우신 까닭으로 말씀하신 것은?", "explanation": "로마서 9장이 이 구절을 인용합니다. 심판 가운데서도 목적이 있었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["고센 땅", "나일 강가", "왕궁", "광야"], "question": "우박이 내리지 않은 곳은 어디입니까?", "explanation": "이스라엘 자손이 있는 고센 땅에는 우박이 없었습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "우박에 상하지 않은 곡식 두 가지는 무엇입니까?", "choices": ["밀과 쌀보리", "보리와 삼", "포도와 무화과", "콩과 팥"], "correctIndex": 0, "explanation": "보리와 삼은 상했으나 밀과 쌀보리는 늦게 자라므로 상하지 않았습니다."}, {"id": 7, "type": "choice", "choices": ["이번은 내가 범죄하였노라 여호와는 의로우시고", "나는 잘못이 없다", "더 보내라", "아무 말도 안 했다"], "question": "바로가 우박 중에 한 말은 무엇입니까?", "explanation": "그러나 우박이 그치자 다시 범죄하여 마음을 완악하게 했습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 9;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["메뚜기", "흑암", "우박", "개구리"], "question": "여덟째 재앙은 무엇입니까?", "explanation": "동풍이 메뚜기를 몰아 왔고 우박에 상하지 않고 남은 것을 다 먹었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["애굽이 망한 줄을 아직도 알지 못하시나이까", "더 버티십시오", "모세를 죽이십시오", "아무 말도 안 함"], "question": "바로의 신하들이 한 말은 무엇입니까?", "explanation": "신하들이 먼저 나서서 그 사람들을 보내 여호와를 섬기게 하라고 청했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["빛이 있었다", "더 어두웠다", "똑같이 어두웠다", "불이 났다"], "question": "아홉째 재앙 중 이스라엘 자손이 사는 곳은 어떠했습니까?", "explanation": "삼 일 동안 애굽에는 캄캄한 흑암이 있었으나 이스라엘 자손이 거주하는 곳에는 빛이 있었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["장정만 가서 섬기라", "모두 가라", "가축만 데려가라", "사흘만 가라"], "question": "바로가 내건 첫 번째 조건은 무엇입니까?", "explanation": "모세는 어린이와 노인, 아들과 딸, 양과 소를 다 데리고 가겠다고 답했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["양과 소는 남겨 두고 가라", "남자만 가라", "사흘 안에 돌아오라", "돈을 내라"], "question": "흑암 뒤 바로가 내건 조건은 무엇입니까?", "explanation": "모세는 \"우리의 가축도 한 마리도 남길 수 없다\"며 거절했습니다. 무엇으로 제사할지 모르기 때문이라 했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "흑암은 며칠 동안 계속되었습니까?", "choices": ["사흘", "이레", "하루", "사십 일"], "correctIndex": 0, "explanation": "삼 일 동안 사람들이 서로 볼 수 없고 일어나지도 못했습니다."}, {"id": 7, "type": "choice", "choices": ["다시는 내 얼굴을 보지 말라 내 얼굴을 보는 날에는 죽으리라", "잘 가라", "내일 다시 오라", "용서한다"], "question": "바로가 모세에게 마지막으로 한 말은 무엇입니까?", "explanation": "모세도 \"당신 말이 옳으니 내가 다시는 당신의 얼굴을 보지 아니하리이다\"라고 답했습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 10;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["애굽의 모든 처음 난 것이 죽는 것", "큰 지진", "홍수", "전염병"], "question": "예고된 마지막 재앙은 무엇입니까?", "explanation": "바로의 장자부터 여종의 장자, 가축의 처음 난 것까지 모두 죽는다고 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["개 한 마리도 혀를 움직이지 않을 것", "똑같이 죽을 것", "큰 소리가 날 것", "알 수 없다"], "question": "이스라엘 자손에게는 어떤 일이 있을 것이라 했습니까?", "explanation": "여호와께서 애굽 사람과 이스라엘 사이를 구별하신다는 것을 알게 하려는 것이었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["이웃에게 은금 패물", "음식", "옷", "가축"], "question": "하나님이 이스라엘 백성에게 구하라고 하신 것은?", "explanation": "여호와께서 애굽 사람들이 백성에게 은혜를 입히게 하셔서 구하는 대로 주었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["밤중", "새벽", "한낮", "저녁"], "question": "이 재앙이 일어날 시간으로 예고된 때는?", "explanation": "\"밤중에 내가 애굽 가운데로 들어가리니\"라고 하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["심히 노하여 떠남", "기뻐하며 떠남", "조용히 떠남", "울며 떠남"], "question": "모세가 바로를 떠날 때의 모습은 어떠했습니까?", "explanation": "모세는 이 말을 하고 심히 노하여 바로에게서 나왔습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["바로의 신하와 백성의 눈에 심히 위대하게 보임", "보잘것없이 보임", "아무도 몰랐음", "미움만 받음"], "question": "애굽 땅에서 모세는 어떤 사람으로 여겨졌습니까?", "explanation": "모세가 애굽 땅에 있어 바로의 신하와 백성의 눈에 아주 위대하게 보였다고 적습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "이 재앙 뒤에 바로가 어떻게 할 것이라고 하셨습니까?", "choices": ["반드시 보낼 뿐 아니라 아주 쫓아낼 것이다", "끝내 보내지 않을 것이다", "절반만 보낼 것이다", "삼 일 뒤에 보낼 것이다"], "correctIndex": 0, "explanation": "\"그가 너희를 여기서 보낼뿐더러 아주 쫓아내리라\"고 하셨습니다."}]'::jsonb where book_id = 2 and chapter = 11;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["어린 양의 피", "기름", "물", "재"], "question": "문 좌우 설주와 인방에 바른 것은 무엇입니까?", "explanation": "\"내가 그 피를 볼 때에 너희를 넘어가리니\" — 유월절이라는 이름이 여기서 나옵니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["일 년 된 흠 없는 수컷", "가장 큰 것", "아무거나", "늙은 양"], "question": "유월절 양은 어떤 것이어야 했습니까?", "explanation": "양이나 염소 중에서 취하되 흠 없는 일 년 된 수컷이어야 했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["허리에 띠를 띠고 신을 신고 지팡이를 잡고 급히 먹으라", "앉아서 천천히 먹으라", "누워서 먹으라", "아무 상관 없다"], "question": "고기를 먹을 때의 모습으로 정해진 것은?", "explanation": "언제든 떠날 수 있는 모습이었습니다. 이것이 여호와의 유월절이라고 했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "이스라엘 자손이 애굽에 거주한 기간은 몇 년입니까?", "choices": ["사백삼십 년", "사백 년", "사십 년", "이백십 년"], "correctIndex": 0, "explanation": "사백삼십 년이 끝나는 그날에 여호와의 군대가 애굽 땅에서 나왔습니다."}, {"id": 5, "type": "choice", "choices": ["급히 나오느라 반죽이 부풀 시간이 없었기 때문", "맛이 좋아서", "값이 싸서", "오래 가서"], "question": "무교병을 먹는 이유는 무엇입니까?", "explanation": "애굽에서 쫓겨나 지체할 수 없었으므로 누룩 없는 떡을 구웠습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["모든 처음 난 것이 죽어 큰 부르짖음이 있었다", "지진이 났다", "불이 났다", "아무 일 없었다"], "question": "밤중에 애굽에 일어난 일은 무엇입니까?", "explanation": "죽은 자가 없는 집이 하나도 없었기에 애굽에 큰 부르짖음이 있었습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["대대로 지켜 영원한 규례로 삼으라", "한 번만 지키라", "잊어버리라", "애굽에서만 지키라"], "question": "유월절에 대해 하나님이 명하신 것은 무엇입니까?", "explanation": "자녀가 \"이 예식이 무슨 뜻이냐\" 물으면 유월절 제사라고 답하라고 하셨습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 12;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["낮에는 구름기둥, 밤에는 불기둥", "천사", "별", "모세의 지팡이"], "question": "하나님이 낮과 밤에 백성을 인도하신 방법은?", "explanation": "길을 인도하시려고 구름기둥과 불기둥이 백성 앞에서 떠나지 않았습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["전쟁을 보면 마음을 돌이켜 애굽으로 돌아갈까 하여", "길이 좁아서", "물이 없어서", "적이 많아서만"], "question": "하나님이 가까운 블레셋 길로 인도하지 않으신 이유는?", "explanation": "가장 빠른 길이 늘 가장 좋은 길은 아니라는 것을 보여 주는 대목입니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "모세가 애굽에서 가지고 나온 유골은 누구의 것입니까?", "choices": ["요셉", "야곱", "아론", "레위"], "correctIndex": 0, "explanation": "창세기 50장에서 요셉이 맹세하게 한 그 부탁이 여기서 지켜집니다."}, {"id": 4, "type": "choice", "choices": ["여호와께서 강한 손으로 애굽에서 인도하여 내신 일", "조상들의 이름", "땅의 크기", "왕들의 역사"], "question": "자녀가 물을 때 무엇을 이야기하라고 하셨습니까?", "explanation": "규례를 지키는 이유를 이야기로 전하게 하셨습니다. 기억은 대를 이어 전해져야 합니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["사람이든 짐승이든 처음 난 것은 내 것이니 거룩히 구별하라", "모두 팔아라", "집에 두라", "이웃에게 주라"], "question": "처음 난 것에 대한 규례는 무엇입니까?", "explanation": "애굽의 처음 난 것을 치신 그날을 기억하게 하는 규례였습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["이레", "사흘", "하루", "한 달"], "question": "무교절 기간은 며칠입니까?", "explanation": "이레 동안 무교병을 먹고 일곱째 날에는 여호와께 절기를 지키라고 하셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "이스라엘이 나온 길은 어느 바다 쪽 광야 길이었습니까?", "choices": ["홍해", "지중해", "요단", "갈릴리"], "correctIndex": 0, "explanation": "하나님은 백성을 홍해의 광야 길로 돌려 인도하셨습니다."}]'::jsonb where book_id = 2 and chapter = 13;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "\"여호와께서 너희를 위하여 싸우시리니 너희는 ○○○ 있을지니라\"", "choices": ["가만히", "굳게 서", "잠잠히", "기다리고"], "correctIndex": 0, "explanation": "앞은 바다, 뒤는 군대인 자리에서 하신 말씀입니다. 사람이 할 수 없는 자리였습니다."}, {"id": 2, "type": "choice", "choices": ["애굽에 매장지가 없어서 우리를 광야에서 죽게 하느냐", "앞으로 가자", "싸우자", "기도하자"], "question": "백성이 두려워하며 모세에게 한 말은 무엇입니까?", "explanation": "애굽 사람을 섬기는 것이 광야에서 죽는 것보다 낫다고까지 했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["모세가 손을 내밀자 큰 동풍이 밤새 불어 바다를 물러가게 함", "갑자기 갈라짐", "배를 만들어 건넘", "얼어붙음"], "question": "바다가 갈라진 방법은 무엇입니까?", "explanation": "여호와께서 밤새도록 큰 동풍으로 바닷물을 물러가게 하시니 바다가 갈라졌습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["구름기둥이 옮겨 와 밤새 서로 가까이 못 하게 함", "불의 벽", "큰 바위", "아무것도 없음"], "question": "이스라엘과 애굽 군대 사이에 있었던 것은 무엇입니까?", "explanation": "애굽 진에는 구름과 흑암이 있고 이스라엘 진에는 밤이 밝았습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["이스라엘 앞에서 도망하자 여호와가 그들을 위하여 싸운다", "더 쫓아가자", "항복하자", "아무 말도 안 함"], "question": "애굽 군대가 바다 가운데서 한 말은 무엇입니까?", "explanation": "병거 바퀴가 벗겨져 달리기가 어렵게 되자 그들도 알아차렸습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["여호와를 경외하며 여호와와 그의 종 모세를 믿었다", "곧 잊었다", "돌아갔다", "싸움을 시작했다"], "question": "이 일 뒤 백성이 한 일은 무엇입니까?", "explanation": "이스라엘이 여호와께서 애굽 사람들에게 행하신 큰 능력을 보고 여호와를 경외했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "이스라엘이 바다를 건넌 땅의 상태는 어떠했습니까?", "choices": ["마른 땅", "진흙", "모래밭", "얕은 물"], "correctIndex": 0, "explanation": "물이 좌우에 벽이 되고 이스라엘 자손은 바다 가운데를 마른 땅으로 지나갔습니다."}]'::jsonb where book_id = 2 and chapter = 14;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "\"여호와는 나의 힘이요 ○○시며 나의 구원이시로다\"", "choices": ["노래", "방패", "산성", "빛"], "correctIndex": 0, "explanation": "홍해를 건넌 뒤 부른 노래의 한 구절입니다. 구원받은 사람의 첫 반응이 노래였습니다."}, {"id": 2, "type": "choice", "choices": ["미리암", "십보라", "요게벳", "드보라"], "question": "소고를 잡고 여인들과 함께 화답한 사람은 누구입니까?", "explanation": "아론의 누이 선지자 미리암이 소고를 잡고 모든 여인이 따라 나오며 춤추었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "물이 써서 마실 수 없었던 곳의 이름은?", "choices": ["마라", "엘림", "신 광야", "르비딤"], "correctIndex": 0, "explanation": "물이 썼으므로 그 이름을 마라(\"쓰다\")라 했습니다."}, {"id": 4, "type": "choice", "choices": ["하나님이 보이신 나뭇가지를 물에 던지자", "비가 내려서", "샘을 파서", "기다려서"], "question": "마라의 물은 어떻게 달게 되었습니까?", "explanation": "여호와께서 모세에게 한 나무를 가리키셨고 그것을 물에 던지니 물이 달게 되었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["나는 너희를 치료하는 여호와임이라", "나는 전능한 하나님이라", "나는 거룩한 하나님이라", "나는 질투하는 하나님이라"], "question": "하나님이 마라에서 자신을 뭐라고 밝히셨습니까?", "explanation": "말씀을 듣고 규례를 지키면 애굽 사람에게 내린 질병을 내리지 않겠다고 하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["물샘 열둘과 종려나무 일흔 그루", "큰 성", "넓은 밭", "아무것도 없음"], "question": "엘림에는 무엇이 있었습니까?", "explanation": "그들이 거기서 물 곁에 장막을 쳤습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["사흘", "하루", "이레", "한 달"], "question": "홍해를 건넌 뒤 며칠 만에 물 문제가 생겼습니까?", "explanation": "수르 광야로 들어가 사흘 길을 걸었으나 물을 얻지 못했습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 15;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "\"이것이 무엇이냐\"는 말에서 나온 양식의 이름은?", "choices": ["만나", "메추라기", "무교병", "떡"], "correctIndex": 0, "explanation": "깟씨 같이 희고 맛은 꿀 섞은 과자 같았다고 합니다."}, {"id": 2, "type": "choice", "choices": ["날마다 그날 먹을 만큼만, 여섯째 날에는 이틀 치", "많이 거둘수록 좋다", "일주일에 한 번", "거두지 말라"], "question": "만나를 거두는 규칙은 무엇이었습니까?", "explanation": "남겨 둔 것에는 벌레가 생기고 냄새가 났지만, 여섯째 날 거둔 것은 안식일까지 상하지 않았습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["메추라기", "이슬", "눈", "모래"], "question": "저녁에 진영을 덮은 것은 무엇입니까?", "explanation": "저녁에는 메추라기가 와서 진에 덮이고 아침에는 만나가 있었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["애굽의 고기 가마와 배부르게 먹던 떡", "애굽의 집", "애굽의 옷", "애굽의 친구"], "question": "백성이 원망하며 그리워한 것은 무엇입니까?", "explanation": "종살이하던 곳을 좋게 기억하는 것이 광야에서 반복되는 모습입니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["많이 거둔 자도 남지 않고 적게 거둔 자도 부족하지 않았다", "많이 거둔 자가 남았다", "적게 거둔 자가 굶었다", "모두 남았다"], "question": "거둔 만나를 되어 보았을 때 어떠했습니까?", "explanation": "각 사람이 먹을 만큼만 거두었다고 합니다. 필요를 채우시는 방식이 그러했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "만나는 몇 년 동안 내렸습니까?", "choices": ["사십 년", "칠 년", "삼 년", "십 년"], "correctIndex": 0, "explanation": "사람이 사는 땅에 이르기까지 사십 년 동안 만나를 먹었습니다."}, {"id": 7, "type": "choice", "choices": ["일곱째 날에는 만나가 없으니 나가지 말라", "두 배로 거두라", "평소와 같이 거두라", "아무 규칙 없음"], "question": "안식일에 대해 정해진 것은 무엇입니까?", "explanation": "그런데도 거두러 나간 사람들이 있었고 하나님은 언제까지 명령을 지키지 않겠느냐고 하셨습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 16;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["호렙 반석을 지팡이로 치자", "샘을 파서", "비가 내려서", "이슬이 모여서"], "question": "르비딤에서 물이 나온 방법은 무엇입니까?", "explanation": "하나님이 반석 위에 서 계시겠다 하셨고, 모세가 치니 물이 나와 백성이 마셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "모세가 제단을 쌓고 붙인 이름은 무엇입니까?", "choices": ["여호와 닛시", "여호와 이레", "여호와 살롬", "엘엘로헤이스라엘"], "correctIndex": 0, "explanation": "\"여호와는 나의 깃발\"이라는 뜻입니다."}, {"id": 3, "type": "choice", "choices": ["모세가 손을 들고 있는지 여부", "군사의 수", "무기의 좋고 나쁨", "날씨"], "question": "아말렉과의 싸움에서 승패를 가른 것은 무엇입니까?", "explanation": "손을 들면 이스라엘이 이기고 내리면 아말렉이 이겼습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["아론과 훌", "여호수아와 갈렙", "아론과 미리암", "이드로와 훌"], "question": "모세의 손을 붙든 두 사람은 누구입니까?", "explanation": "두 사람이 양쪽에서 손을 붙들어 해가 지도록 내려오지 않게 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "아말렉과 싸운 이스라엘의 지휘자는 누구입니까?", "choices": ["여호수아", "아론", "훌", "갈렙"], "correctIndex": 0, "explanation": "모세는 여호수아에게 사람을 택해 나가 싸우라고 했습니다. 여호수아가 처음 등장하는 장면입니다."}, {"id": 6, "type": "choice", "choices": ["백성이 다투었고 여호와를 시험하였기 때문", "물이 달아서", "싸움에서 이겨서", "길이 험해서"], "question": "맛사와 므리바라는 이름이 붙은 까닭은?", "explanation": "\"여호와께서 우리 중에 계신가 안 계신가\" 하고 시험했기 때문입니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["이 백성이 조금 있으면 내게 돌을 던지겠나이다", "물을 주소서", "길을 알려 주소서", "쉬게 하소서"], "question": "모세가 부르짖은 말은 무엇입니까?", "explanation": "지도자가 위협을 느낄 만큼 분위기가 험했습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 17;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "모세를 찾아온 장인의 이름은 무엇입니까?", "choices": ["이드로", "아론", "훌", "브두엘"], "correctIndex": 0, "explanation": "미디안 제사장 이드로가 모세의 아내와 두 아들을 데리고 왔습니다."}, {"id": 2, "type": "choice", "choices": ["혼자 모든 재판을 하려다 지치게 된다는 것", "재판이 불공정하다는 것", "백성이 게으르다는 것", "길이 멀다는 것"], "question": "이드로가 모세에게 지적한 문제는 무엇입니까?", "explanation": "\"너와 이 백성이 필경 기력이 쇠하리니 이 일이 네게 너무 중함이라\"고 했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["하나님을 두려워하고 진실하며 불의한 이익을 미워하는 자", "가장 나이 많은 자", "가장 부유한 자", "가장 힘센 자"], "question": "이드로가 세우라고 한 사람의 자격은 무엇입니까?", "explanation": "능력만이 아니라 사람됨을 먼저 보라는 기준입니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["천부장, 백부장, 오십부장, 십부장", "열두 지파", "동서남북 넷", "장로와 백성"], "question": "나눈 조직의 단위는 무엇입니까?", "explanation": "작은 일은 그들이 재판하고 큰 일만 모세에게 가져오게 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["여호와는 모든 신보다 크시도다", "수고했다", "돌아가자", "믿기 어렵다"], "question": "이드로가 모세의 이야기를 듣고 한 말은?", "explanation": "이드로는 기뻐하며 하나님을 찬송하고 번제와 희생을 드렸습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["그 말을 듣고 그대로 행했다", "거절했다", "미뤘다", "화를 냈다"], "question": "모세는 장인의 조언을 어떻게 했습니까?", "explanation": "지도자가 조언을 받아들이는 장면입니다. 모세는 그대로 사람을 세웠습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "모세의 두 아들 중 첫째의 이름은 무엇입니까?", "choices": ["게르솜", "엘리에셀", "나답", "아비후"], "correctIndex": 0, "explanation": "\"내가 이방에서 나그네가 되었다\" 하여 게르솜, 둘째는 \"내 아버지의 하나님이 나를 도우셨다\" 하여 엘리에셀입니다."}]'::jsonb where book_id = 2 and chapter = 18;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["독수리 날개로 업어 인도함", "배로 건네줌", "수레로 실어 옴", "길을 열어 줌"], "question": "하나님이 애굽에서 인도해 내신 일을 무엇에 비유하셨습니까?", "explanation": "\"독수리 날개로 너희를 업어 내게로 인도하였음을 너희가 보았느니라.\"", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "언약을 지키면 어떤 나라가 되리라고 하셨습니까?", "choices": ["제사장 나라", "강한 나라", "큰 민족", "복된 성읍"], "correctIndex": 0, "explanation": "온 땅이 다 하나님의 것이지만 이스라엘은 특별한 소유, 제사장 나라, 거룩한 백성이 되리라 하셨습니다."}, {"id": 3, "type": "choice", "choices": ["여호와께서 명령하신 대로 우리가 다 행하리이다", "생각해 보겠습니다", "어렵습니다", "아무 대답도 안 함"], "question": "백성이 한 대답은 무엇입니까?", "explanation": "모세가 그 말을 여호와께 전했습니다. 이 약속이 뒤에 어떻게 지켜지는지가 성경의 큰 줄기가 됩니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["사흘 동안 성결하게 하고 옷을 빨게 함", "금식하게 함", "제물을 준비하게 함", "아무 준비도 없음"], "question": "하나님이 내려오시기 전 백성에게 명하신 준비는?", "explanation": "거룩하신 분 앞에 서는 준비였습니다. 산 주위에 경계도 정하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["우레와 번개와 빽빽한 구름, 큰 나팔 소리", "조용했다", "비가 내렸다", "해가 밝았다"], "question": "셋째 날 아침에 있었던 일은 무엇입니까?", "explanation": "진중의 모든 백성이 떨었고 시내산에 연기가 자욱했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "이스라엘이 시내 광야에 이른 것은 애굽을 떠난 지 몇 달째입니까?", "choices": ["석 달", "한 달", "일곱 달", "일 년"], "correctIndex": 0, "explanation": "애굽 땅을 떠난 지 삼 개월이 되던 날 시내 광야에 이르렀습니다."}, {"id": 7, "type": "choice", "choices": ["아무도 산에 오르거나 그 경계를 침범하지 못하게 하려고", "길을 표시하려고", "짐승을 막으려고", "진을 나누려고"], "question": "산에 경계를 정하신 까닭은 무엇입니까?", "explanation": "범하는 자는 죽임을 당한다고 하실 만큼 거룩함이 강조되었습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 19;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "첫째 계명은 무엇입니까?", "choices": ["너는 나 외에는 다른 신들을 네게 두지 말라", "우상을 만들지 말라", "안식일을 기억하라", "네 부모를 공경하라"], "correctIndex": 0, "explanation": "십계명의 첫 자리에 하나님과의 관계가 놓입니다."}, {"id": 2, "type": "choice", "choices": ["나는 너를 애굽 땅 종 되었던 집에서 인도하여 낸 네 하나님 여호와니라", "너희는 내 종이니라", "내 말을 들으라", "두려워하라"], "question": "십계명이 시작되기 전 하나님이 먼저 하신 말씀은?", "explanation": "무엇을 하라는 명령보다 누가 말씀하시는지가 먼저 나옵니다. 구원이 먼저, 계명이 그다음입니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["안식일", "부모 공경", "살인", "도둑질"], "question": "넷째 계명은 무엇에 관한 것입니까?", "explanation": "엿새 동안 일하고 일곱째 날은 쉬라 하시며 창조의 이레를 근거로 드셨습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["네 부모를 공경하라 — 네 생명이 길리라", "살인하지 말라", "도둑질하지 말라", "탐내지 말라"], "question": "약속이 붙어 있는 계명은 무엇입니까?", "explanation": "\"네 하나님 여호와가 네게 준 땅에서 네 생명이 길리라\"는 약속이 함께 있습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["네 이웃의 것을 탐내지 말라", "거짓 증거하지 말라", "간음하지 말라", "우상을 만들지 말라"], "question": "마지막 열째 계명은 무엇입니까?", "explanation": "행동만이 아니라 마음까지 다루는 계명이라는 점에서 특별합니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["떨며 멀리 서서 모세에게 대신 말해 달라고 함", "가까이 다가감", "노래함", "흩어짐"], "question": "백성이 우레와 나팔 소리를 보고 한 일은?", "explanation": "모세는 \"두려워하지 말라 하나님이 임하심은 너희를 시험하고 경외하게 하려 하심이라\"고 답했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "십계명은 모두 몇 개입니까?", "choices": ["열 개", "일곱 개", "열둘", "다섯 개"], "correctIndex": 0, "explanation": "앞의 네 계명은 하나님을 향한 것, 뒤의 여섯 계명은 사람을 향한 것으로 나눕니다."}]'::jsonb where book_id = 2 and chapter = 20;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["육 년", "삼 년", "십 년", "평생"], "question": "히브리 종은 몇 년을 일한 뒤 자유로 나갈 수 있었습니까?", "explanation": "육 년 동안 섬기고 일곱째 해에는 몸값 없이 자유롭게 나가게 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["당한 것보다 더 갚지 말라는 제한", "반드시 똑같이 갚으라는 명령", "두 배로 갚으라는 뜻", "갚지 말라는 뜻"], "question": "\"눈은 눈으로, 이는 이로\"의 본뜻은 무엇입니까?", "explanation": "보복이 끝없이 커지는 것을 막는 상한선이었습니다. 고대 사회에서는 오히려 앞선 규정이었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["그 종을 자유롭게 놓아 주어야 했다", "값을 물어야 했다", "아무 일 없었다", "벌금을 냈다"], "question": "주인이 종을 때려 눈을 상하게 하면 어떻게 해야 했습니까?", "explanation": "눈이나 이를 상하게 하면 그 대가로 놓아 주어야 했습니다. 종에게도 지켜져야 할 몸이 있었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["반드시 죽일지니라", "벌금을 내라", "종으로 삼으라", "추방하라"], "question": "사람을 납치해 판 자에 대한 법은 무엇입니까?", "explanation": "사람을 물건처럼 사고파는 일을 가장 무겁게 다뤘습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["반드시 죽일지니라", "벌금", "추방", "아무 벌 없음"], "question": "부모를 치거나 저주하는 자에 대한 법은?", "explanation": "다섯째 계명(부모 공경)이 실제 법으로 얼마나 무겁게 다뤄졌는지 보여 줍니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "종이 주인과 가족을 사랑해 나가지 않겠다고 하면 무엇에 대고 표를 했습니까?", "choices": ["귀", "손", "이마", "발"], "correctIndex": 0, "explanation": "문이나 문설주 앞에서 송곳으로 귀를 뚫었고, 그는 영원히 그 집을 섬겼습니다."}, {"id": 7, "type": "choice", "choices": ["십계명 바로 다음", "성막 제작 뒤", "홍해를 건너기 전", "가나안에 들어간 뒤"], "question": "이 장의 법들이 놓인 자리는 어디입니까?", "explanation": "큰 원칙(십계명) 다음에 실제 생활에서 어떻게 적용할지가 이어집니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 21;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["해 지기 전에 돌려주라", "한 달 뒤에 돌려주라", "돌려주지 않아도 된다", "팔아도 된다"], "question": "겉옷을 담보로 잡았을 때의 규정은 무엇입니까?", "explanation": "그것이 그의 유일한 몸 덮을 것이기 때문입니다. \"그가 무엇을 입고 자겠느냐\"고 하십니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["이자를 받지 말라", "이자를 두 배로 받으라", "담보를 잡으라", "꾸어 주지 말라"], "question": "가난한 자에게 돈을 꾸어 줄 때의 규정은?", "explanation": "어려운 사람에게 빌려주는 것을 돈벌이로 삼지 말라는 뜻입니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["나그네, 과부, 고아", "왕과 제사장", "부자와 상인", "군인"], "question": "해롭게 하지 말라고 특별히 지목된 사람들은 누구입니까?", "explanation": "스스로를 지킬 힘이 없는 사람들입니다. 하나님이 직접 그들의 부르짖음을 들으신다고 하십니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "소를 훔쳐 잡거나 판 자는 몇 배로 갚아야 했습니까?", "choices": ["다섯 배", "네 배", "두 배", "일곱 배"], "correctIndex": 0, "explanation": "소는 다섯 배, 양은 네 배로 갚아야 했습니다."}, {"id": 5, "type": "choice", "choices": ["너희도 애굽 땅에서 나그네였기 때문", "나그네가 힘이 세기 때문", "법이 그러하기 때문", "이유 없음"], "question": "나그네를 압제하지 말라고 하신 이유는 무엇입니까?", "explanation": "자기가 당해 본 일을 남에게 하지 말라는 것입니다. 이 이유가 성경에서 여러 번 반복됩니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["그들이 내게 부르짖으면 내가 반드시 들으리라", "스스로 살아가게 하라", "나라가 돌보게 하라", "아무 말씀 없음"], "question": "하나님이 과부와 고아에 대해 하신 말씀은?", "explanation": "해롭게 하는 자에게는 진노가 있을 것이라고까지 하셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["반드시 배상할지니라", "사과하면 된다", "아무 책임 없다", "절반만 갚는다"], "question": "불을 놓아 남의 곡식을 태웠을 때는 어떻게 해야 합니까?", "explanation": "고의가 아니어도 자기가 놓은 불이면 책임을 졌습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 22;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["다수를 따라 악을 행하지 말고 가난한 자라고 편들지도 말라", "항상 다수를 따르라", "가난한 자를 늘 편들라", "부자를 편들라"], "question": "재판에 관해 경계한 것은 무엇입니까?", "explanation": "동정도 판단을 흐리게 할 수 있다는 것입니다. 기준은 사실과 공의였습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["반드시 끌어다 주라", "못 본 척하라", "자기가 가지라", "주인에게 알리기만 하라"], "question": "원수의 소나 나귀가 길을 잃은 것을 보면 어떻게 해야 합니까?", "explanation": "미워하는 자의 나귀가 짐에 눌린 것을 보면 도와서 그 짐을 부리라고까지 합니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["가난한 자가 먹게 하고 남은 것은 들짐승이 먹게 하려고", "땅이 쉬게 하려고만", "농사를 못 지어서", "세금을 줄이려고"], "question": "안식년에 밭을 묵히는 이유는 무엇입니까?", "explanation": "쉼과 나눔이 함께 있는 규례였습니다. 안식일에는 종과 짐승도 쉬게 했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "해마다 지키라고 하신 절기는 몇 번입니까?", "choices": ["세 번", "한 번", "두 번", "일곱 번"], "correctIndex": 0, "explanation": "무교절, 맥추절(수확절), 수장절 — 해마다 세 번 절기를 지키라고 하셨습니다."}, {"id": 5, "type": "choice", "choices": ["사자(천사)", "구름", "불", "군대"], "question": "하나님이 길에서 백성을 지키려고 보내겠다고 하신 것은?", "explanation": "\"내가 사자를 네 앞서 보내어 길에서 너를 보호하여 예비한 곳에 이르게 하리니.\"", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["거짓 소문을 퍼뜨리지 말고 악인과 손잡아 위증하지 말라", "증언을 하지 말라", "들은 대로만 말하라", "아무 규정 없음"], "question": "거짓 증언에 대해 경계한 것은 무엇입니까?", "explanation": "재판이 무너지는 첫 자리가 말이라는 것을 짚습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["땅이 황폐해지고 들짐승이 번성할까 하여", "그들이 강해서", "시간이 없어서", "이유 없음"], "question": "하나님이 가나안 족속을 단번에 쫓아내지 않겠다고 하신 이유는?", "explanation": "이스라엘이 번성하여 그 땅을 감당할 수 있을 때까지 조금씩 쫓아내시겠다고 하셨습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 23;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["여호와의 모든 말씀을 우리가 준행하리이다", "어렵습니다", "생각해 보겠습니다", "아무 대답 없음"], "question": "백성이 말씀을 듣고 한 대답은 무엇입니까?", "explanation": "한목소리로 대답했고, 모세는 그 말씀을 글로 기록했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["이는 여호와께서 이 모든 말씀에 대하여 너희와 세우신 언약의 피니라", "이는 속죄의 피니라", "이는 정결의 피니라", "아무 말 없음"], "question": "모세가 피를 뿌리며 한 말은 무엇입니까?", "explanation": "절반은 제단에, 절반은 백성에게 뿌려 양쪽이 함께 묶였음을 나타냈습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "모세가 산에 머문 기간은 며칠입니까?", "choices": ["사십 일", "이레", "사흘", "석 달"], "correctIndex": 0, "explanation": "모세가 구름 속으로 들어가 사십 일 사십 야를 산에 있었습니다."}, {"id": 4, "type": "choice", "choices": ["이스라엘 열두 지파", "열두 계명", "열두 절기", "열두 제사장"], "question": "모세가 세운 열두 기둥은 무엇을 나타냅니까?", "explanation": "산 아래 제단을 쌓고 이스라엘 열두 지파대로 열두 기둥을 세웠습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["모세, 아론, 나답, 아비후와 이스라엘 장로 칠십 인", "모세 혼자", "모든 백성", "제사장들만"], "question": "산에 올라가 하나님을 뵌 사람들은 누구입니까?", "explanation": "그들이 하나님을 뵙고 먹고 마셨는데도 손을 대지 않으셨다고 적습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["맹렬한 불 같이 보였다", "밝은 빛으로만 보였다", "보이지 않았다", "물처럼 보였다"], "question": "여호와의 영광이 산 위에 어떻게 보였습니까?", "explanation": "이스라엘 자손의 눈에 여호와의 영광이 산꼭대기에서 맹렬한 불 같이 보였습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "모세가 산에 오를 때 백성의 일을 맡긴 두 사람은?", "choices": ["아론과 훌", "아론과 여호수아", "훌과 갈렙", "나답과 아비후"], "correctIndex": 0, "explanation": "\"무릇 일이 있는 자는 그들에게로 나아갈지니라\" 하고 아론과 훌에게 맡겼습니다."}]'::jsonb where book_id = 2 and chapter = 24;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "성막을 지으라 하신 목적은 무엇입니까?", "choices": ["그들 중에 거하시려고", "제물을 받으시려고", "율법을 두시려고", "백성을 모으시려고"], "correctIndex": 0, "explanation": "\"내가 그들 중에 거할 성소를 그들이 나를 위하여 짓되.\" 건물이 목적이 아니라 함께 계심이 목적이었습니다."}, {"id": 2, "type": "choice", "choices": ["기쁜 마음으로 내는 자에게서 받으라", "모두에게 똑같이 걷으라", "부자에게만 받으라", "정해진 액수를 내게 하라"], "question": "예물을 받는 기준은 무엇이었습니까?", "explanation": "자원하는 마음이 조건이었습니다. 35~36장에서 이 원칙이 실제로 어떻게 나타나는지 볼 수 있습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["증거판(돌판)", "만나", "지팡이", "기름"], "question": "언약궤 안에 넣으라고 하신 것은 무엇입니까?", "explanation": "\"내가 네게 줄 증거판을 궤 속에 둘지며\"라고 하셨습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["그룹 둘", "기둥 둘", "등불 둘", "나팔 둘"], "question": "속죄소 양쪽에 만든 것은 무엇입니까?", "explanation": "금으로 그룹 둘을 만들어 날개를 펴서 속죄소를 덮고 서로 얼굴을 마주 보게 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["속죄소 위 두 그룹 사이", "제단 위", "성막 문", "산꼭대기"], "question": "하나님이 만나 말씀하시겠다고 하신 자리는 어디입니까?", "explanation": "\"거기서 내가 너와 만나고 속죄소 위 두 그룹 사이에서 네게 말하리라\"고 하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "등잔대의 가지는 모두 몇 개의 등잔을 가집니까?", "choices": ["일곱", "셋", "열둘", "다섯"], "correctIndex": 0, "explanation": "순금으로 쳐서 만든 등잔대에 등잔 일곱을 만들어 앞을 비추게 했습니다."}, {"id": 7, "type": "choice", "choices": ["산에서 보인 양식대로", "사람의 뜻대로", "애굽의 방식대로", "가장 값비싸게"], "question": "모든 것을 무엇대로 만들라고 하셨습니까?", "explanation": "\"너는 삼가 이 산에서 네게 보인 양식대로 할지니라.\" 사람이 고안한 것이 아니었습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 25;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["휘장", "널판", "문", "돌담"], "question": "성소와 지성소를 나눈 것은 무엇입니까?", "explanation": "청색·자색·홍색 실과 고운 베 실로 그룹을 정교하게 수놓은 휘장으로 나눴습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["증거궤", "등잔대", "진설병 상", "분향단"], "question": "휘장 안쪽 지성소에 두는 것은 무엇입니까?", "explanation": "휘장 안에 증거궤를 들여놓아 성소와 지성소를 구분하게 하셨습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["네 겹", "한 겹", "두 겹", "여섯 겹"], "question": "성막 덮개는 몇 겹으로 되어 있습니까?", "explanation": "고운 베 휘장, 염소털 휘장, 붉게 물들인 숫양 가죽, 해달 가죽 — 안쪽은 화려하고 바깥은 투박했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "널판을 만든 나무의 이름은 무엇입니까?", "choices": ["조각목", "잣나무", "백향목", "감람나무"], "correctIndex": 0, "explanation": "조각목으로 널판을 만들어 금으로 싸고 은 받침에 세웠습니다."}, {"id": 5, "type": "choice", "choices": ["광야를 옮겨 다니며 세우고 걷어야 했기 때문", "재료가 부족해서", "시간이 없어서", "가볍게 하려고만"], "question": "성막이 조립식으로 만들어진 까닭은 무엇입니까?", "explanation": "널판과 띠와 받침이 모두 끼우고 빼는 구조였습니다. 하나님이 함께 움직이신다는 뜻이기도 합니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["청색 자색 홍색 실과 고운 베 실로 수놓은 휘장", "나무 문짝", "금 문", "아무것도 달지 않음"], "question": "성막 문에는 무엇을 달았습니까?", "explanation": "성막 문에도 휘장을 달고 기둥 다섯을 세워 놋 받침에 끼웠습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["보인 양식대로 정확히 만들 것", "되도록 크게 만들 것", "싸게 만들 것", "빨리 만들 것"], "question": "이 장의 지시에서 반복되는 기준은 무엇입니까?", "explanation": "치수와 재료가 세세히 정해져 있습니다. 사람이 정하는 예배가 아니었습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 26;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["놋", "금", "은", "나무 그대로"], "question": "번제단은 무엇으로 쌌습니까?", "explanation": "조각목으로 만들고 놋으로 쌌습니다. 성소 안의 기구가 금이었던 것과 대비됩니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["뿔", "고리", "기둥", "등잔"], "question": "번제단의 네 모퉁이에 있는 것은 무엇입니까?", "explanation": "네 모퉁이에 뿔을 만들되 제단과 한 덩이가 되게 하고 놋으로 쌌습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["감람으로 찧어 낸 순수한 기름", "아무 기름이나", "동물 기름", "수입한 기름"], "question": "등불에 쓸 기름은 어떤 것이어야 했습니까?", "explanation": "등불을 위해 감람으로 찧어 낸 순결한 기름을 가져오게 하셨습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["저녁부터 아침까지", "아침부터 저녁까지", "하루 종일", "정해지지 않음"], "question": "등불을 관리하는 시간은 언제부터 언제까지입니까?", "explanation": "아론과 그 아들들이 여호와 앞에서 저녁부터 아침까지 등불을 보살피게 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["번제단", "등잔대", "증거궤", "진설병 상"], "question": "성막 뜰에 들어설 때 가장 먼저 마주치는 것은?", "explanation": "하나님께 나아가는 길의 첫 자리가 제사였습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "뜰의 문에 단 것은 무엇입니까?", "choices": ["휘장", "놋 그물", "성막 널판", "번제단"], "correctIndex": 0, "explanation": "청색 자색 홍색 실과 고운 베 실로 수놓아 짠 휘장을 뜰 문에 달았습니다."}, {"id": 7, "type": "choice", "choices": ["이스라엘 자손이 대대로 지킬 영원한 규례", "한 해만 지키는 규례", "광야에서만 지키는 규례", "제사장만 아는 규례"], "question": "등불을 지키는 규례는 어떤 규례라고 했습니까?", "explanation": "\"이스라엘 자손이 대대로 지킬 영원한 규례이니라\"고 하셨습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 27;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["영화롭고 아름답게", "검소하게", "가볍게", "되도록 싸게"], "question": "제사장의 옷을 어떻게 지으라고 하셨습니까?", "explanation": "거룩한 옷을 지어 영화롭고 아름답게 하라고 하셨습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["이스라엘 아들들의 이름", "십계명", "제사장의 이름", "아무것도 새기지 않음"], "question": "에봇 어깨받이의 호마노에 새긴 것은 무엇입니까?", "explanation": "기념 보석으로 삼아 아론이 두 어깨에 그 이름을 메어 여호와 앞에서 기념이 되게 했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "흉패에 물린 보석은 모두 몇 개입니까?", "choices": ["열둘", "일곱", "넷", "열"], "correctIndex": 0, "explanation": "네 줄로 열두 보석을 물리고 각각에 열두 지파의 이름을 새겼습니다."}, {"id": 4, "type": "choice", "choices": ["우림과 둠밈", "만나", "돌판", "기름"], "question": "흉패 안에 넣은 것은 무엇입니까?", "explanation": "아론이 여호와 앞에 들어갈 때 이스라엘 자손의 판결을 항상 그의 가슴에 두게 했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["금방울과 석류를 번갈아", "술과 끈", "보석", "아무것도 달지 않음"], "question": "겉옷 가장자리에 단 것은 무엇입니까?", "explanation": "성소에 들어갈 때와 나올 때 소리가 나게 하여 죽지 않게 하려는 것이었습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "관 앞의 금 패에 새긴 말은 무엇입니까?", "choices": ["여호와께 성결", "여호와는 나의 깃발", "여호와 이레", "거룩한 백성"], "correctIndex": 0, "explanation": "아론의 이마에 있어 이스라엘 자손이 드리는 성물의 죄를 담당하게 했습니다."}, {"id": 7, "type": "choice", "choices": ["어깨와 가슴", "손과 발", "머리", "허리"], "question": "제사장이 열두 지파의 이름을 지고 들어간 자리는 어디입니까?", "explanation": "어깨받이의 호마노와 가슴의 흉패 — 백성을 지고 하나님 앞에 선다는 뜻이 담겨 있습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 28;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["오른쪽 귓부리, 오른손 엄지, 오른발 엄지", "이마, 손바닥, 발바닥", "가슴, 어깨, 무릎", "눈, 코, 입"], "question": "제사장 위임식에서 피를 바른 곳 세 군데는 어디입니까?", "explanation": "듣는 것과 하는 것과 걷는 것을 구별해 드린다는 뜻으로 읽습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "question": "위임식은 며칠 동안 이어졌습니까?", "choices": ["이레", "사흘", "사십 일", "여드레"], "correctIndex": 0, "explanation": "이레 동안 위임식을 행하여 제단을 거룩하게 했습니다."}, {"id": 3, "type": "choice", "choices": ["관유", "물", "피", "향"], "question": "아론의 머리에 부은 것은 무엇입니까?", "explanation": "관유를 가져다 그의 머리에 부어 발라 거룩하게 구별했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["내가 이스라엘 자손 중에 거하여 그들의 하나님이 되리라", "땅을 넓혀 주리라", "적을 물리쳐 주리라", "오래 살게 하리라"], "question": "이 장 끝에서 하나님이 하신 약속은 무엇입니까?", "explanation": "성막과 제사장 제도의 목적이 결국 함께 계시는 데 있음을 다시 밝힙니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["회막 문에서 물로 씻김", "옷을 입힘", "기름을 부음", "제사를 드림"], "question": "위임식을 시작할 때 가장 먼저 한 일은 무엇입니까?", "explanation": "씻고, 입히고, 기름 붓고, 제사를 드리는 순서였습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["일 년 된 어린 양 두 마리 (아침 하나, 저녁 하나)", "수송아지 한 마리", "숫양 세 마리", "비둘기 두 마리"], "question": "날마다 드리는 상번제는 무엇을 몇 마리씩 드렸습니까?", "explanation": "대대로 여호와 앞 회막 문에서 끊이지 않고 드리는 번제였습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "question": "제사장으로 세워진 사람은 아론과 누구입니까?", "choices": ["그의 아들들", "레위 사람 전체", "장로들", "브살렐과 오홀리압"], "correctIndex": 0, "explanation": "아론과 그의 아들들을 이스라엘 자손 중에서 구별해 제사장 직분을 맡기셨습니다."}]'::jsonb where book_id = 2 and chapter = 29;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["부자라고 더 내지 말고 가난한 자라고 덜 내지 말라", "재산에 따라 내라", "지파별로 다르게 내라", "자원해서 내라"], "question": "속전으로 내는 금액에 대한 규정은 무엇입니까?", "explanation": "모두 반 세겔이었습니다. 하나님 앞에서 생명의 값이 같다는 뜻입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["회막과 제단 사이, 손발을 씻는 데", "성소 안, 향을 사르는 데", "뜰 문 앞, 제물을 씻는 데", "지성소 안"], "question": "물두멍은 어디에 두고 무엇에 썼습니까?", "explanation": "제사장이 회막에 들어갈 때와 제단에 가까이 갈 때 씻어야 죽지 않는다고 했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["아침에 등불을 손질할 때와 저녁에 등불을 켤 때", "한낮에만", "안식일에만", "절기에만"], "question": "분향단에서 향을 사르는 때는 언제입니까?", "explanation": "대대로 여호와 앞에 끊이지 않는 향이었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["같은 배합으로 개인이 만들어 쓰지 말라", "팔지 말라", "두 번 만들지 말라", "아무 규정 없음"], "question": "관유와 향에 대한 금지 규정은 무엇입니까?", "explanation": "거룩한 용도로 구별된 것을 일상으로 끌어내리지 말라는 뜻입니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "인구 조사 때 각 사람이 낸 속전은 얼마입니까?", "choices": ["반 세겔", "한 세겔", "십분의 일 세겔", "두 세겔"], "correctIndex": 0, "explanation": "스무 살 이상 계수된 자마다 성소의 세겔로 반 세겔을 냈습니다."}, {"id": 6, "type": "choice", "choices": ["증거궤 앞 휘장 밖", "지성소 안", "뜰 가운데", "성막 문 앞"], "question": "분향단은 성소의 어디에 두었습니까?", "explanation": "증거궤 위 속죄소 맞은편, 휘장 바깥에 두어 여호와를 만나는 자리로 삼았습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["회막 봉사에", "제사장 급여로", "왕에게", "가난한 자에게"], "question": "속전으로 거둔 돈은 어디에 썼습니까?", "explanation": "회막 봉사에 쓰게 하여 여호와 앞에서 기념이 되고 생명을 대속하게 했습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 30;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "성막을 만들도록 하나님이 지명해 부르신 사람은 누구입니까?", "choices": ["브살렐", "오홀리압", "아론", "훌"], "correctIndex": 0, "explanation": "유다 지파 훌의 손자 우리의 아들 브살렐을 지명하여 부르셨습니다."}, {"id": 2, "type": "choice", "choices": ["하나님의 영, 지혜와 총명과 지식과 여러 재주", "많은 재물", "큰 힘", "긴 수명"], "question": "브살렐에게 채우신 것은 무엇입니까?", "explanation": "성경에서 \"하나님의 영이 충만하다\"는 표현이 처음 쓰인 대상이 기술자였다는 점이 눈에 띕니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "브살렐을 도우라고 세우신 사람은 누구입니까?", "choices": ["오홀리압", "브살렐", "이다말", "엘르아살"], "correctIndex": 0, "explanation": "단 지파 아히사막의 아들 오홀리압을 함께 세우셨습니다."}, {"id": 4, "type": "choice", "choices": ["안식일", "헌금", "제사", "기도"], "question": "성막 일 가운데 다시 강조하신 것은 무엇입니까?", "explanation": "거룩한 일을 한다는 이유로도 안식을 건너뛸 수 없었습니다. 안식일은 표징이라고 하셨습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["나와 너희 사이의 표징 — 나는 너희를 거룩하게 하는 여호와인 줄 알게 하려 함", "언약궤의 표징", "제사장의 표징", "땅의 표징"], "question": "안식일은 무엇의 표징이라고 하셨습니까?", "explanation": "대대로 지킬 영원한 언약이라 하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["하나님이 친히 쓰신 증거판 두 돌판", "성막 설계도", "지팡이", "제사장 옷"], "question": "이 장 마지막에 모세가 받은 것은 무엇입니까?", "explanation": "\"하나님이 친히 쓰신 것이더라\"고 적습니다. 이 돌판이 32장에서 깨집니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["기술과 재주도 하나님이 주신 것이라는 것", "기술은 세상 것이라는 것", "제사장만 거룩하다는 것", "재주는 배워야 한다는 것"], "question": "이 장이 손재주에 대해 보여 주는 것은 무엇입니까?", "explanation": "마음이 지혜로운 모든 자에게 지혜를 주어 명령한 것을 다 만들게 하셨다고 합니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 31;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["우리를 인도할 신을 만들라", "모세를 찾아오라", "애굽으로 돌아가자", "먹을 것을 달라"], "question": "백성이 아론에게 요구한 것은 무엇입니까?", "explanation": "모세가 어떻게 되었는지 알 수 없다는 것이 이유였습니다. 기다림이 무너진 자리였습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["금송아지", "금 기둥", "금 뱀", "금 상자"], "question": "아론이 만든 것은 무엇입니까?", "explanation": "백성의 금 고리를 모아 부어서 송아지 형상을 만들었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["두 돌판을 산 아래로 던져 깨뜨림", "조용히 지켜봄", "바로 기도함", "아론을 죽임"], "question": "산에서 내려온 모세가 한 일은 무엇입니까?", "explanation": "언약이 이미 깨졌다는 것을 눈에 보이게 한 행동으로 읽습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["불에 던졌더니 이 송아지가 나왔나이다", "제가 만들었습니다", "몰랐습니다", "백성이 시켰습니다만"], "question": "아론의 변명은 무엇입니까?", "explanation": "자기 손으로 새겨 만들었으면서도 저절로 나온 것처럼 말했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["그렇지 아니하시오면 주께서 기록하신 책에서 내 이름을 지워 버려 주옵소서", "저는 상관없습니다", "벌하소서", "기다리소서"], "question": "모세가 하나님께 간구하며 한 말은 무엇입니까?", "explanation": "자기를 걸고 백성을 위해 선 중보였습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "모세가 백성에게 물어본 말은 \"누구든지 ○○○께 속한 자는 내게로 나아오라\"입니다.", "choices": ["여호와", "모세", "아론", "이스라엘"], "correctIndex": 0, "explanation": "레위 자손이 다 모여들었고 그날 삼천 명가량이 죽었습니다."}, {"id": 7, "type": "choice", "choices": ["불살라 부수어 가루로 만들어 물에 뿌려 마시게 함", "땅에 묻음", "녹여서 그릇을 만듦", "그대로 둠"], "question": "모세가 금송아지를 어떻게 했습니까?", "explanation": "자기들이 만든 것이 아무것도 아니라는 것을 몸으로 알게 한 셈입니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 32;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "\"내가 친히 가리라 내가 너를 ○○ 하리라\"", "choices": ["쉬게", "이기게", "가게", "살게"], "correctIndex": 0, "explanation": "함께 가지 않으시겠다는 말씀에 모세가 매달렸고, 하나님이 돌이켜 주신 말씀입니다."}, {"id": 2, "type": "choice", "choices": ["너희와 함께 올라가지 아니하리라", "곧 가나안에 들어가리라", "다시 애굽으로 가라", "여기 머물라"], "question": "하나님이 처음에 하신 말씀은 무엇입니까?", "explanation": "사자를 보내 땅은 주시겠지만 친히 함께 가지는 않으시겠다는 것이었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["사람이 자기의 친구와 이야기함 같이", "멀리서 소리로만", "꿈으로만", "글로만"], "question": "모세가 회막에서 하나님과 말한 모습을 성경은 어떻게 적습니까?", "explanation": "\"여호와께서 모세와 대면하여 말씀하시며\"라고 적습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["주께서 친히 가지 아니하시려거든 우리를 여기서 올려 보내지 마옵소서", "땅을 넓혀 주소서", "적을 물리쳐 주소서", "음식을 주소서"], "question": "모세가 간청한 내용은 무엇입니까?", "explanation": "약속의 땅보다 함께 계심이 먼저라는 고백입니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["바위 틈에 두고 손으로 덮었다가 등을 보게 하심", "얼굴을 보여 주심", "거절하심", "불로 나타나심"], "question": "모세가 영광을 보여 달라 하자 하나님이 하신 일은?", "explanation": "\"내 얼굴을 보지 못하리니 나를 보고 살 자가 없음이니라\" 하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["슬퍼하며 단장품을 떼어 냄", "기뻐함", "떠남", "아무 일도 안 함"], "question": "백성이 하나님의 말씀을 듣고 한 일은?", "explanation": "함께 가지 않으시겠다는 말이 그들에게 가장 무거운 소식이었습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["그것이 우리를 세상 모든 백성과 구별되게 하는 것이기 때문", "길이 험해서", "적이 많아서", "백성이 원해서"], "question": "모세가 하나님의 함께하심을 구한 이유로 든 것은?", "explanation": "함께 계심 자체가 이 백성의 정체성이라는 것입니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 33;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "하나님이 자신을 선포하신 말씀 — \"자비롭고 은혜롭고 ○○○를 더디하고\"", "choices": ["노하기", "말하기", "심판하기", "잊기"], "correctIndex": 0, "explanation": "인자와 진실이 많은 하나님이라고 하셨습니다. 성경에서 여러 번 인용되는 구절입니다."}, {"id": 2, "type": "choice", "choices": ["모세", "하나님", "아론", "브살렐"], "question": "두 번째 돌판은 누가 다듬었습니까?", "explanation": "처음 것은 하나님이 만드셨지만 두 번째는 모세가 다듬어 올라갔고, 글씨는 하나님이 쓰셨습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["광채가 났다", "어두웠다", "창백했다", "변화 없었다"], "question": "산에서 내려온 모세의 얼굴은 어떠했습니까?", "explanation": "하나님과 말하였으므로 얼굴 피부에 광채가 났고 백성이 가까이 하기를 두려워했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["말을 마치고 수건으로 얼굴을 가림", "산으로 돌아감", "아무 일도 안 함", "백성을 물리침"], "question": "모세가 광채 때문에 한 일은 무엇입니까?", "explanation": "여호와 앞에 들어가 말할 때에는 수건을 벗었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["그 땅 주민과 언약을 세우지 말고 그들의 제단을 헐라", "전쟁을 하지 말라", "농사를 짓지 말라", "성을 쌓지 말라"], "question": "새 언약에서 특별히 경계하신 것은 무엇입니까?", "explanation": "그들의 신을 섬기게 될까 하여 우상과 아세라 상을 찍으라고 하셨습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "모세가 산에 머문 기간은 며칠입니까?", "choices": ["사십 일", "이레", "사흘", "석 달"], "correctIndex": 0, "explanation": "떡도 먹지 않고 물도 마시지 않으며 사십 일 사십 야를 머물렀습니다."}, {"id": 7, "type": "choice", "choices": ["죄를 용서하시되 형벌 받을 자는 결단코 면죄하지 아니하시고", "모든 죄를 없던 일로 하시고", "아무도 벌하지 않으시고", "모두 벌하시고"], "question": "하나님의 선포에 이어 나오는 말씀은 무엇입니까?", "explanation": "자비와 공의가 함께 선포됩니다. 한쪽만 떼어 읽으면 안 되는 대목입니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 34;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["마음에 원하는 자, 자원하는 자", "모든 사람이 똑같이", "지도자만", "부자만"], "question": "예물을 가져오는 기준은 무엇이었습니까?", "explanation": "마음이 감동된 모든 자와 자원하는 모든 자가 예물을 가져왔습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["손수 실을 자아 가져옴", "금을 가져옴", "나무를 베어 옴", "음식을 준비함"], "question": "마음이 지혜로운 여인들이 한 일은 무엇입니까?", "explanation": "염소털로 실을 자은 여인들도 있었습니다. 저마다 할 수 있는 것으로 참여했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["안식일", "제사", "전쟁", "인구 조사"], "question": "예물을 청하기 전에 모세가 먼저 말한 것은 무엇입니까?", "explanation": "성막 짓는 일이 바빠도 이레째 날은 쉬어야 했습니다. 31장에 이어 다시 강조됩니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "성막 만드는 일을 맡도록 지명된 두 사람은?", "choices": ["브살렐과 오홀리압", "아론과 훌", "나답과 아비후", "이다말과 엘르아살"], "correctIndex": 0, "explanation": "하나님이 그들에게 지혜를 채우시고 가르치는 능력까지 주셨다고 합니다."}, {"id": 5, "type": "choice", "choices": ["호마노와 보석, 기름과 향품", "곡식", "가축", "무기"], "question": "지도자들이 가져온 것은 무엇입니까?", "explanation": "에봇과 흉패에 물릴 보석, 등불과 관유와 향에 쓸 기름과 향품을 가져왔습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["남녀와 신분을 가리지 않고 저마다 가진 것으로 참여함", "지도자들만 참여함", "제사장만 참여함", "아무도 참여하지 않음"], "question": "이 장이 보여 주는 참여의 모습으로 알맞은 것은?", "explanation": "금붙이를 낸 사람도, 실을 자은 사람도, 나무를 가져온 사람도 있었습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["불을 피우지 말라", "걷지 말라", "말하지 말라", "먹지 말라"], "question": "안식일에 하지 말라고 특별히 언급된 것은?", "explanation": "\"안식일에는 너희의 모든 처소에서 불도 피우지 말지니라\"고 했습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 35;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["백성이 너무 많이 가져오므로 넉넉하고도 남습니다", "재료가 모자랍니다", "일이 너무 힘듭니다", "시간이 부족합니다"], "question": "일하던 사람들이 모세에게 와서 한 말은 무엇입니까?", "explanation": "모세는 더 이상 가져오지 말라고 명령을 내렸습니다. 부족해서가 아니라 넘쳐서 멈춘 드문 장면입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["남녀를 막론하고 다시는 예물을 만들지 말라", "더 가져오라", "절반만 가져오라", "돈으로 바꿔 오라"], "question": "모세가 내린 명령은 무엇입니까?", "explanation": "백성이 가져오기를 그쳤고, 있는 재료가 모든 일을 하기에 넉넉했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["성막의 휘장과 널판과 띠, 그리고 두 휘장", "제사장 옷", "언약궤", "번제단"], "question": "이 장에서 만든 것은 주로 무엇입니까?", "explanation": "성막의 뼈대와 덮개, 성소와 지성소를 나누는 휘장, 성막 문의 휘장을 만들었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["마음이 지혜롭고 여호와께서 지혜를 주신 자들", "가장 나이 많은 자들", "지도자들", "제사장들"], "question": "일한 사람들의 공통점은 무엇입니까?", "explanation": "마음에 감동을 받아 와서 일하려고 하는 모든 자가 함께했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "성소와 지성소를 나누는 휘장에 수놓은 것은 무엇입니까?", "choices": ["그룹", "종려나무", "석류", "백합화"], "correctIndex": 0, "explanation": "청색 자색 홍색 실과 고운 베 실로 그룹을 정교하게 수놓아 만들었습니다."}, {"id": 6, "type": "choice", "choices": ["다르지 않고 지시받은 그대로 만들었다", "더 크게 만들었다", "더 간단하게 만들었다", "재료를 바꿨다"], "question": "제작이 지시와 어떻게 달랐습니까?", "explanation": "25~31장의 지시와 35~40장의 제작이 거의 같은 문장으로 반복됩니다. 그대로 했다는 뜻입니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["자원하는 마음이 모이면 넘칠 수도 있다는 것", "헌금은 강제해야 모인다는 것", "지도자가 다 감당해야 한다는 것", "재료는 늘 부족하다는 것"], "question": "이 장이 보여 주는 것으로 알맞은 것은?", "explanation": "25장에서 \"기쁜 마음으로 내는 자에게서 받으라\" 하신 원칙의 결과입니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 36;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "이 장에서 기구들을 만든 사람은 누구입니까?", "choices": ["브살렐", "오홀리압", "아론", "이다말"], "correctIndex": 0, "explanation": "브살렐이 조각목으로 궤를 만드는 것으로 시작합니다."}, {"id": 2, "type": "choice", "choices": ["순금으로 안팎을", "놋으로", "은으로", "가죽으로"], "question": "궤는 무엇으로 쌌습니까?", "explanation": "안팎을 순금으로 싸고 위쪽 가장자리로 돌아가며 금 테를 만들었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["날개를 펴서 속죄소를 덮고 서로 얼굴을 마주 봄", "등을 돌리고 섬", "아래를 내려다봄", "날개를 접고 있음"], "question": "두 그룹은 어떤 모습으로 만들어졌습니까?", "explanation": "그 얼굴은 속죄소를 향했습니다. 하나님이 만나 주시겠다고 하신 자리입니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["순금을 쳐서 한 덩이로", "여러 조각을 붙여서", "나무에 금을 입혀서", "놋으로"], "question": "등잔대는 어떻게 만들었습니까?", "explanation": "줄기와 가지와 잔과 꽃받침과 꽃이 한 덩이로 연결되게 쳐서 만들었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["25·30장의 지시를 그대로 실행한 기록", "새로운 지시", "백성의 불평", "전쟁 기록"], "question": "이 장의 성격으로 알맞은 것은 무엇입니까?", "explanation": "같은 내용이 지시와 실행으로 두 번 적힙니다. 그대로 순종했다는 것을 보여 주는 방식입니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "등잔대의 등잔은 몇 개입니까?", "choices": ["일곱", "셋", "열둘", "다섯"], "correctIndex": 0, "explanation": "등잔 일곱과 불집게와 불똥 그릇을 순금으로 만들었습니다."}, {"id": 7, "type": "choice", "choices": ["향을 만드는 법대로 정결하게", "아무렇게나", "애굽 방식대로", "만들지 않음"], "question": "관유와 향은 어떻게 만들었습니까?", "explanation": "거룩한 관유와 정결한 향품으로 만든 향을 향 만드는 법대로 제조했습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 37;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["회막 문에서 수종드는 여인들의 놋 거울", "새로 산 놋", "금", "돌"], "question": "물두멍은 무엇으로 만들었습니까?", "explanation": "자기를 비추던 거울을 씻는 그릇으로 내놓은 셈입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["쓰인 금·은·놋의 결산", "새로운 지시", "제사장 명단", "전쟁 기록"], "question": "이 장 뒷부분에 나오는 것은 무엇입니까?", "explanation": "무게를 하나하나 적어 어디에 얼마가 쓰였는지 밝힙니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["계수된 자들이 낸 속전", "애굽에서 가져온 것", "지도자들의 예물", "전쟁에서 얻은 것"], "question": "은은 어디에서 나온 것입니까?", "explanation": "스무 살 이상 계수된 자마다 낸 반 세겔이 모여 성소의 받침을 만드는 데 쓰였습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "question": "결산을 감독한 레위 사람의 이름은 무엇입니까?", "choices": ["이다말", "엘르아살", "브살렐", "오홀리압"], "correctIndex": 0, "explanation": "제사장 아론의 아들 이다말이 모세의 명령에 따라 레위 사람을 시켜 계산했습니다."}, {"id": 5, "type": "choice", "choices": ["놋", "금", "은", "가죽"], "question": "번제단은 무엇으로 쌌습니까?", "explanation": "조각목으로 만들고 놋으로 쌌으며 기구들도 다 놋으로 만들었습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["드린 예물이 어디에 쓰였는지 분명히 밝히는 것", "많이 모으는 것", "빨리 짓는 것", "아끼는 것"], "question": "이 장이 보여 주는 태도로 알맞은 것은?", "explanation": "거룩한 일일수록 회계가 투명해야 한다는 것을 성경이 몸소 보여 줍니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["놋", "금", "은", "나무"], "question": "뜰의 기둥 받침은 무엇으로 만들었습니까?", "explanation": "뜰 기둥의 받침은 놋이고 갈고리와 가름대는 은이었습니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 38;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["여호와께서 모세에게 명령하신 대로", "백성이 원하는 대로", "보기 좋은 대로", "형편이 되는 대로"], "question": "이 장에서 반복되는 말은 무엇입니까?", "explanation": "거듭 반복되면서 지시와 실행이 어긋나지 않았음을 강조합니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["얇게 쳐서 오려 실을 만듦", "녹여서 부음", "가루를 냄", "사서 씀"], "question": "금은 어떻게 실로 만들었습니까?", "explanation": "금을 얇게 쳐서 오려 실을 만들어 청색 자색 홍색 실과 고운 베 실에 섞어 짰습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "순금 패에 새긴 말은 무엇입니까?", "choices": ["여호와께 성결", "여호와는 나의 깃발", "거룩한 백성", "제사장 나라"], "correctIndex": 0, "explanation": "거룩한 패를 만들어 청색 끈으로 관 위에 매었습니다."}, {"id": 4, "type": "choice", "choices": ["살펴보고 명령대로 된 것을 보고 축복함", "다시 만들라고 함", "아무 말도 안 함", "일부를 돌려보냄"], "question": "모든 것을 가져왔을 때 모세가 한 일은?", "explanation": "모세가 그 마친 모든 것을 본즉 여호와께서 명령하신 대로 되었으므로 그들에게 축복했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["이스라엘 열두 지파의 이름", "십계명", "제사장 이름", "아무것도 없음"], "question": "흉패에 물린 보석에 새긴 것은 무엇입니까?", "explanation": "인장을 새김 같이 열두 지파의 이름대로 새겼습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["금방울과 석류를 번갈아", "보석", "술", "아무것도 달지 않음"], "question": "겉옷 가장자리에 단 것은 무엇입니까?", "explanation": "28장의 지시대로 방울과 석류를 번갈아 달았습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["성막의 모든 부품이 준비되어 모세에게 가져옴", "성막이 세워짐", "제사가 시작됨", "백성이 떠남"], "question": "이 장이 끝나는 시점의 상태는 무엇입니까?", "explanation": "세우는 것은 다음 장의 일입니다. 여기서는 모든 부품이 완성됩니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 39;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "question": "성막이 완성되었을 때 무엇이 성막에 충만했습니까?", "choices": ["여호와의 영광", "불 기둥", "향의 연기", "제물의 피"], "correctIndex": 0, "explanation": "\"구름이 회막에 덮이고 여호와의 영광이 성막에 충만하매.\" 함께 계시겠다는 약속이 눈에 보이게 된 순간입니다."}, {"id": 2, "type": "choice", "choices": ["회막에 들어갈 수 없었다", "가장 먼저 들어갔다", "지성소에 들어갔다", "아무 일 없었다"], "question": "영광이 충만했을 때 모세는 어떻게 되었습니까?", "explanation": "구름이 회막 위에 덮이고 영광이 충만하여 모세도 들어가지 못했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["구름이 성막에서 떠오르면 행진하고 머물면 머물렀다", "모세의 판단", "정해진 날짜", "백성의 결정"], "question": "이스라엘이 행진하고 머무는 기준은 무엇이었습니까?", "explanation": "낮에는 구름이, 밤에는 불이 그 구름 가운데 있어 온 이스라엘의 눈앞에 있었습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["둘째 해 첫째 달 초하루", "첫째 해 마지막 날", "셋째 해 봄", "정해지지 않음"], "question": "성막을 세운 때는 언제입니까?", "explanation": "애굽을 떠난 지 둘째 해 첫째 달 초하루에 성막을 세웠습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["여호와께서 모세에게 명령하신 대로", "백성이 원한 대로", "형편대로", "보기 좋은 대로"], "question": "이 장에서도 반복되는 말은 무엇입니까?", "explanation": "세우는 순서 하나하나에 이 말이 붙습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["씻기고 옷을 입히고 기름을 부어 제사장 직분을 맡김", "뜰을 지키게 함", "제물을 준비하게 함", "백성을 가르치게 함"], "question": "아론과 그 아들들에게 한 일은 무엇입니까?", "explanation": "그 기름 부음으로 대대로 영영히 제사장이 되게 하셨습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["하나님이 백성 가운데 거하시게 된 것", "가나안에 들어간 것", "전쟁에서 이긴 것", "왕이 세워진 것"], "question": "출애굽기가 끝나는 자리로 알맞은 것은?", "explanation": "종살이하던 백성이 하나님이 함께 거하시는 백성이 되는 데서 출애굽기가 끝납니다.", "correctIndex": 0}]'::jsonb where book_id = 2 and chapter = 40;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["제물을 통째로 태워 드림", "일부만 태움", "태우지 않음", "먹기만 함"], "question": "번제의 특징은 무엇입니까?", "explanation": "전부를 드린다는 뜻이 담긴 제사였습니다. 그래서 \"온전한 번제\"라고도 합니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["물고기", "소", "양이나 염소", "비둘기"], "question": "번제로 드릴 수 있는 제물이 아닌 것은?", "explanation": "소, 양이나 염소, 산비둘기나 집비둘기 새끼 중에서 형편에 맞게 드렸습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["이 제물이 나를 대신한다는 표시", "제물을 붙잡는 동작", "축복하는 동작", "아무 뜻 없음"], "question": "드리는 사람이 제물의 머리에 손을 얹은 것은 무엇을 뜻합니까?", "explanation": "\"그를 위하여 기쁘게 받으심이 되어 그를 위하여 속죄가 될 것이라\"고 합니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["흠 없는 수컷", "가장 큰 것", "가장 살진 것", "아무거나"], "question": "번제물의 조건은 무엇이었습니까?", "explanation": "흠 없는 것으로 드리되 회막 문에서 여호와 앞에 기쁘게 받으심이 되도록 드렸습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["비둘기로도 드릴 수 있게 했기 때문", "무료로 제물을 주었기 때문", "제사를 면제했기 때문", "나라에서 대신 드렸기 때문"], "question": "가난한 사람도 제사를 드릴 수 있었던 이유는?", "explanation": "형편에 따라 드릴 수 있게 열어 두어 아무도 배제되지 않게 했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "레위기의 제사가 드려지는 장소는 어디입니까?", "choices": ["회막", "시내 산", "성전", "장막 뜰 밖"], "correctIndex": 0, "explanation": "여호와께서 회막에서 모세를 부르시고 말씀하시는 것으로 레위기가 시작됩니다."}, {"id": 7, "type": "choice", "choices": ["성막이 세워졌으니 이제 어떻게 나아갈지를 다루려고", "전쟁을 준비하려고", "족보를 적으려고", "땅을 나누려고"], "question": "레위기가 출애굽기 뒤에 오는 까닭으로 알맞은 것은?", "explanation": "함께 계시는 하나님 앞에서 어떻게 살 것인가가 레위기의 주제입니다.", "correctIndex": 0}]'::jsonb where book_id = 3 and chapter = 1;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["곡식(고운 가루)", "소", "양", "비둘기"], "question": "소제는 무엇으로 드리는 제사입니까?", "explanation": "피 흘림이 없는 제사로, 고운 가루에 기름을 붓고 유향을 놓아 드렸습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["누룩과 꿀", "소금과 기름", "유향과 기름", "물과 소금"], "question": "소제에 넣지 말라고 한 두 가지는 무엇입니까?", "explanation": "누룩과 꿀은 넣지 말고, 대신 소금은 반드시 치라고 했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "question": "모든 소제물에 반드시 쳐야 했던 것은 무엇입니까?", "choices": ["소금", "기름", "유향", "누룩"], "correctIndex": 0, "explanation": "\"네 하나님의 언약의 소금을 네 소제에 빼지 못할지니\"라고 했습니다."}, {"id": 4, "type": "choice", "choices": ["아론과 그의 자손(제사장)", "드린 사람", "가난한 자", "태워 없앰"], "question": "소제물의 나머지는 누구의 몫이 되었습니까?", "explanation": "한 줌을 기념물로 태우고 그 나머지는 지극히 거룩한 것으로 제사장의 몫이었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["물에 끓이기", "화덕에 굽기", "철판에 부치기", "냄비에 삶기"], "question": "소제를 만드는 방법으로 나오지 않는 것은?", "explanation": "화덕, 철판, 냄비 세 가지 방법이 나옵니다. 모두 기름을 섞어 만들었습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "choices": ["피 흘림이 없다", "제사장이 드린다", "밤에만 드린다", "절기에만 드린다"], "question": "소제가 다른 제사와 다른 점은 무엇입니까?", "explanation": "동물이 아니라 땅의 소산을 드리는 제사였습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["언약", "깨끗함", "기쁨", "슬픔"], "question": "소금이 뜻하는 것으로 설명되는 말은?", "explanation": "\"언약의 소금\"이라 불렀습니다. 변하지 않는 관계를 뜻하는 표현입니다.", "correctIndex": 0}]'::jsonb where book_id = 3 and chapter = 2;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["드리는 사람도 제물을 함께 먹었다", "피를 뿌리지 않았다", "제사장이 드리지 않았다", "밤에만 드렸다"], "question": "화목제가 다른 제사와 다른 점은 무엇입니까?", "explanation": "하나님 앞에서 함께 먹는 식사와 같아 기쁨과 감사의 자리에서 드려졌습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["기름과 피", "고기와 뼈", "내장과 다리", "머리와 꼬리"], "question": "먹지 못하게 한 두 가지는 무엇입니까?", "explanation": "기름은 하나님께 드리는 몫이었고, 피는 생명을 뜻하기 때문이었습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["하나님과 사람, 사람과 사람 사이의 화목", "전쟁이 끝남", "죄가 없어짐", "수확이 끝남"], "question": "화목제라는 이름이 뜻하는 것은 무엇입니까?", "explanation": "관계가 회복된 자리에서 함께 먹는 것이 이 제사의 성격입니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["소나 양이나 염소, 암수 상관없이 흠 없는 것", "수컷만", "소만", "새만"], "question": "화목제로 드릴 수 있는 제물은 무엇입니까?", "explanation": "번제가 수컷만이었던 것과 달리 암수를 가리지 않았습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "기름과 피를 먹지 말라는 것은 어떤 규례라고 했습니까?", "choices": ["영원한 규례", "한 해 규례", "제사장만의 규례", "광야에서만의 규례"], "correctIndex": 0, "explanation": "\"너희는 기름과 피를 먹지 말라\"는 것이 대대로 지킬 영원한 규례라고 못 박습니다."}, {"id": 6, "type": "choice", "choices": ["여호와께 드리는 화제의 음식", "제사장의 몫", "백성의 몫", "버리는 것"], "question": "하나님께 드린 기름을 무엇이라 불렀습니까?", "explanation": "\"모든 기름은 여호와의 것이니라\"고 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["제물의 머리에 안수함", "옷을 찢음", "금식함", "노래함"], "question": "화목제를 드릴 때도 반복되는 동작은 무엇입니까?", "explanation": "제물이 자기를 대신한다는 표시로 손을 얹고 회막 문에서 잡았습니다.", "correctIndex": 0}]'::jsonb where book_id = 3 and chapter = 3;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["부지중에(모르고) 지은 죄", "고의로 지은 죄", "남이 지은 죄", "조상의 죄"], "question": "속죄제가 다루는 죄는 어떤 죄입니까?", "explanation": "몰랐다고 없던 일이 되지 않는다는 것이 이 장의 전제입니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["흠 없는 수송아지", "숫염소", "암염소", "비둘기"], "question": "제사장이 죄를 지었을 때의 제물은 무엇입니까?", "explanation": "온 회중이 죄를 지었을 때와 같은 제물입니다. 책임이 큰 자리일수록 무겁게 다뤘습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["암염소나 어린 암양", "수송아지", "숫염소", "소 떼 전부"], "question": "평민이 죄를 지었을 때의 제물은 무엇입니까?", "explanation": "신분과 형편에 따라 제물이 달랐습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["흠 없는 숫염소", "수송아지", "암염소", "비둘기"], "question": "족장이 죄를 지었을 때의 제물은 무엇입니까?", "explanation": "제사장·회중은 수송아지, 족장은 숫염소, 평민은 암염소나 어린 양이었습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "choices": ["책임이 큰 자리일수록 죄도 무겁게 다뤄진다", "지도자는 죄가 없다", "평민만 죄를 짓는다", "모르면 죄가 아니다"], "question": "이 장이 보여 주는 원칙으로 알맞은 것은?", "explanation": "제사장의 죄가 온 회중의 죄와 같은 제물을 요구했습니다.", "correctIndex": 0}, {"id": 6, "type": "choice", "question": "속죄제의 피는 어디에 발랐습니까?", "choices": ["제단 뿔", "휘장", "성막 문", "언약궤"], "correctIndex": 0, "explanation": "휘장 앞에 일곱 번 뿌리고 향단 뿔에 바르며 남은 피는 제단 밑에 쏟았습니다."}, {"id": 7, "type": "choice", "choices": ["그가 사함을 받으리라", "그가 부자가 되리라", "그가 오래 살리라", "아무 말 없음"], "question": "속죄제를 드린 결과로 반복되는 말은 무엇입니까?", "explanation": "제사장이 그를 위하여 속죄한즉 그가 사함을 받으리라는 말이 반복됩니다.", "correctIndex": 0}]'::jsonb where book_id = 3 and chapter = 4;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["본래 것에 오분의 일을 더해 갚는 것", "금식하는 것", "한 해 동안 봉사하는 것", "아무것도 없음"], "question": "속건제에는 제사 외에 무엇이 더 요구되었습니까?", "explanation": "하나님께 드리는 제사와 사람에게 갚는 배상이 함께 있었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["자기 죄를 자백하는 것", "금식하는 것", "옷을 갈아입는 것", "기다리는 것"], "question": "제물을 드리기 전에 먼저 해야 할 일은 무엇입니까?", "explanation": "\"그는 그 범한 죄를 자복하고\"라고 합니다. 형식보다 인정이 먼저였습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["산비둘기 두 마리, 그것도 어려우면 고운 가루", "아무것도 안 드려도 됨", "돈으로만", "이웃이 대신 드림"], "question": "형편이 어려운 사람은 무엇으로 드릴 수 있었습니까?", "explanation": "가난이 하나님께 나아가는 것을 막지 못하게 했습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["남의 밭을 사들인 것", "증인으로 알면서 말하지 않은 것", "부정한 것을 모르고 만진 것", "함부로 맹세한 것"], "question": "이 장에 나오는 죄의 예가 아닌 것은?", "explanation": "알면서 침묵한 것도 죄로 다뤄진다는 점이 눈에 띕니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "속건제에서 더해 갚아야 하는 비율은 얼마입니까?", "choices": ["오분의 일", "십분의 일", "절반", "두 배"], "correctIndex": 0, "explanation": "성물에 대해 손해를 끼쳤으면 본래 것에 오분의 일을 더해 제사장에게 주었습니다."}, {"id": 6, "type": "choice", "choices": ["알면서 말하지 않는 것도 죄가 된다", "증언은 하지 않아도 된다", "들은 것만 말하면 된다", "증인은 벌을 받지 않는다"], "question": "증인에 관한 규정이 뜻하는 것은 무엇입니까?", "explanation": "\"증인이 되어 그가 본 것이나 알고 있는 것을 알리지 아니하면 그 허물이 그에게로 돌아가리라.\"", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["기름과 유향", "소금", "가루", "물"], "question": "가난한 자의 소제에 넣지 않은 것은 무엇입니까?", "explanation": "속죄제이므로 기름을 붓지 않고 유향도 놓지 않았습니다.", "correctIndex": 0}]'::jsonb where book_id = 3 and chapter = 5;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["먼저 주인에게 오분의 일을 더해 갚고 그다음 제사를 드림", "제사만 드리면 됨", "제사를 먼저 드리고 나중에 갚음", "갚지 않아도 됨"], "question": "이웃을 속여 손해를 끼쳤을 때의 순서는 무엇입니까?", "explanation": "사람에게 진 빚을 그대로 두고 하나님께만 드릴 수는 없었습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["꺼지지 않게 하고 아침마다 나무를 얹으라", "밤에는 꺼도 된다", "절기에만 피운다", "규정 없음"], "question": "번제단의 불에 대한 규정은 무엇입니까?", "explanation": "\"불은 끊임없이 제단 위에 피워 꺼지지 않게 할지니라\"고 했습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["세금을 늦게 낸 것", "맡은 물건에 대하여 속인 것", "강도질한 것", "잃은 물건을 줍고 아니라고 한 것"], "question": "이 장에 나오는 속건제의 예가 아닌 것은?", "explanation": "남의 것에 관한 문제들입니다. 하나님께 범죄한 것이라고 표현합니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["세마포 옷을 입고 재를 치운 뒤 옷을 갈아입고 진영 밖으로 내감", "아무 옷이나 입어도 됨", "재를 치우지 않음", "백성이 치움"], "question": "제사장이 제단의 재를 치울 때의 규정은?", "explanation": "거룩한 자리에서 입는 옷과 밖에서 입는 옷을 구별했습니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "이웃에게 손해를 끼쳤을 때 더해서 갚는 비율은?", "choices": ["오분의 일", "십분의 일", "절반", "다섯 배"], "correctIndex": 0, "explanation": "본래 물건에 오분의 일을 더하여 그 임자에게 돌려주었습니다."}, {"id": 6, "type": "choice", "choices": ["거룩한 곳 회막 뜰", "자기 집", "아무 데나", "진영 밖"], "question": "제사장이 소제의 남은 것을 먹는 곳은 어디입니까?", "explanation": "누룩을 넣지 않고 구워 거룩한 곳에서 먹게 했습니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["하나님께 드리는 일과 사람에게 갚는 일이 따로가 아니라는 것", "제사만 드리면 된다는 것", "배상은 선택이라는 것", "제사장은 예외라는 것"], "question": "이 장이 보여 주는 원칙으로 알맞은 것은?", "explanation": "예배와 정직이 한 몸으로 묶여 있습니다.", "correctIndex": 0}]'::jsonb where book_id = 3 and chapter = 6;
update reading_helper_chapter_content set questions = '[{"id": 1, "type": "choice", "choices": ["그날에 다 먹어야 함", "사흘까지", "일주일까지", "제한 없음"], "question": "감사로 드리는 화목제물은 언제까지 먹어야 했습니까?", "explanation": "서원이나 자원으로 드린 것은 이튿날까지 먹을 수 있었고, 사흘째까지 남은 것은 불사르게 했습니다.", "correctIndex": 0}, {"id": 2, "type": "choice", "choices": ["흔든 가슴과 든 뒷다리", "머리와 다리", "내장", "가죽만"], "question": "제사장의 몫으로 정해진 것은 무엇입니까?", "explanation": "이것을 이스라엘 자손에게서 받는 영원한 소득으로 삼으셨습니다.", "correctIndex": 0}, {"id": 3, "type": "choice", "choices": ["백성 중에서 끊어지리라", "벌금을 낸다", "아무 일 없다", "제사를 다시 드린다"], "question": "부정한 몸으로 화목제물을 먹으면 어떻게 된다고 했습니까?", "explanation": "거룩한 것을 아무렇게나 다루지 못하게 하는 경고였습니다.", "correctIndex": 0}, {"id": 4, "type": "choice", "choices": ["기름과 피를 먹지 말라", "고기를 먹지 말라", "떡을 먹지 말라", "물을 마시지 말라"], "question": "다시 강조된 금지 규정은 무엇입니까?", "explanation": "3장에 이어 반복됩니다. 그만큼 중요하게 다뤄진 규정입니다.", "correctIndex": 0}, {"id": 5, "type": "choice", "question": "화목제 가운데 감사로 드리는 것과 함께 드린 것은?", "choices": ["무교병", "포도주", "소금", "향"], "correctIndex": 0, "explanation": "기름 섞은 무교병과 무교전병, 그리고 유교병도 함께 드렸습니다."}, {"id": 6, "type": "choice", "choices": ["기름 부음의 분깃", "거룩한 세금", "백성의 선물", "제단의 몫"], "question": "제사장의 몫을 뭐라고 불렀습니까?", "explanation": "제사장으로 세워진 날부터 받는 몫이라는 뜻입니다.", "correctIndex": 0}, {"id": 7, "type": "choice", "choices": ["번제·소제·속죄제·속건제·화목제 다섯", "두 가지", "세 가지", "일곱 가지"], "question": "이 장에서 정리되는 제사는 모두 몇 가지입니까?", "explanation": "1~7장에서 다룬 다섯 제사의 규례를 정리하며 마칩니다.", "correctIndex": 0}]'::jsonb where book_id = 3 and chapter = 7;
